/* 平成14年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h14.committeeSessions.push(...[{"id":"h14-20020417-14","meetingId":"h14-cm04","date":"2002年4月17日","dateIso":"2002-04-17","committee":"行財政改革特別委員会","time":"午後１時０５分～午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"字句はこれで内容を一任したことですから、あえてですけれども、文章が「なお」から「意見が出された」までの全部を一つでずっと書いてあるんですね。途中で、できれば……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"桜井委員","kind":"質問","question":"「出された」までの４行がずっと一つの文章になっていて、途中で区切ったほうがわかりやすいかなと思っているんです。願わくばお願いしたいと思っているのは、二つに分けたらどうかなというふうにちょっと考えたんですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"桜井委員","kind":"意見","question":"「を守ることを基本姿勢とし、」その２行目の「公的責任」とありますね。２番目のところ、コストよりも住民の必要性に対応しているかを優先基準とされたい」というふうに整理したらいかがなものかということなんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"鶴委員","kind":"質問","question":"これは、単独の会派からという原案の段階で共産党からお出しになった文言をそのまま挿入して、尊重してお入れになったものじゃないですか。だから、どうしてそういうふうにしてほしいのかということの説明がないと。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"桜井委員","kind":"質問","question":"一任したわけですからいいですけれども、そういうふうにしたらどうかという、そういう意味です。最初の文章、お出しした文章そのものと比べてもらえばわかります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"皆さん、載せることになった以上はここのまとめた中でこういうふうにしたいという形、それは尊重してもいいんじゃないですかね。変えればいいということで。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"佐藤委員","kind":"質問","question":"僕はいつも不思議で仕方ないのは、桜井委員の会派の委員が副委員長で入っておられるわけですよね。当然菊地副委員長は、これを了解した上で出されているわけでしょうから、桜井委員の思いはよくわかりますけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"桜井委員","kind":"提案","question":"それで、副委員長も出ていますから、これの提案に私がそこで言うことは、筋からすればちょっといかがなものかというのはあるかもしれません。そういう正式に、さっき事務局には申し上げて、急だったものですからとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"桜井委員","kind":"質問","question":"この計算式で４２３万というのが出たんでしょうか。財政というんでしょうか、１枚半ぐらいかな、そういう行政水準がありますよね。","respondent":"榎本行財政改革担当課長","answer":"そういう指標をとって進めていきたいということで出た指標だったのですけれども、各データ、サンプルがあります。他の自治体レベルでの地区計画となっているかというものの指標も当然位置づけを考えて、評価の中に入れていく必要はあるかと考えております。","id":"exchange-009"},{"speaker":"桜井委員","kind":"質問","question":"もう一つは、そのさっきの大崎なんですけれども、４２３万でいくと、さっき言ったコストの、これは教えてください。このコスト計算にした場合にはどういうことか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"この資料のまとめのときには、各地区の中学生の参画した事業ということで、その二つを考え合わせながら最終的にはお示ししているというような形です。人件費が４００万、減価償却費が８万ということで４２３万という形になってありますけれども、１２年度予算では。","id":"exchange-010"},{"speaker":"桜井委員","kind":"確認","question":"最後にそのコストのことだけちょっと確認をしたいんですけれども、移転支出的コストというお話がありましたね。そういうところにもなっていく可能性がありますから、そういう点では、この移転支出的コストというのをちょっと説明を求めました。","respondent":"市岡企画財政課長","answer":"これまでも何回かご説明しましたけれども、正しくコストを把握するにはどうしたらいいかというところを工夫しているという、こういう趣旨です。対応させた関係でのコスト計上がなかなかできてこなかったことを改善をするために、４分類のコストだとか…","id":"exchange-011"},{"speaker":"辻副委員長","kind":"質問・要望","question":"だから、今言った温度を１度上げるとかあるじゃないですか。どの加点が入るのかというのは私は大きな事業評価になるんではないかなと思うんですけれども、その辺はいかがか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"先ほどの言葉の問題ですけれども、言葉の問題というのは、ちょっと各いろんな事業部ごとにそれぞれやはり難しい言葉等が入ってあります。それから、去年１３年度を実施した段階でまだＩＳＯの取得段階の途中ということで…","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"簡潔にお尋ねいたしますが、我々の要望として、その評価が変わってしまうのかというふうなとらえ方もできます。もう最優先で１００％達成するということで当然受けとめるんですが、そうした質問があると思うんで、的確に使っていただきたいと要望として。","respondent":"榎本行財政改革担当課長","answer":"それとも重点的に実施すべきなのかとか、優先的な事業という意味での拡大、本質的には拡大という意味をあらわしています。ちょっとこの部分につきましては、最終的な評価の方向性が整合性がとれているかどうかというのは点検して、改善していきたいと考えております。","id":"exchange-013"},{"speaker":"田中委員","kind":"意見","question":"一方、新年の名刺交換会は５０％の参加率でＢだと。区民の方が目にする数字だけでは、また誤解を招くような理解をされてしまう可能性もあると思いますので、ぜひご検討をお願いしたいと思いますとの意見を述べました。","respondent":"中尾根企画部長","answer":"ただやってみて、さっき言った非常に難しいというのはちょっと一言どうしても言っておきたいなというところがあります。できるだけみんなにわかりやすくしたいというふうに思っておりますが、１点だけ、苦労の部分だけもちょっと紹介させていただきたいと思います。","id":"exchange-014"},{"speaker":"金高委員","kind":"質問・要望","question":"１点ちょっと教えていただきたいんですけれども、２番、３番まではそれぞれわかります。それで、その最後にその他のコストに総額１９億となっていますけれども、具体的に何を示すか、それをちょっとお知らせ願えませんか。","respondent":"市岡企画財政課長","answer":"現実に計上してある１９億１,８００万というのは、利払い分ですね、これです。もう少し、特に行革委員会でのご審査に資するように、細かな説明も整理したいと思います。","id":"exchange-015"},{"speaker":"嶋委員","kind":"質問","question":"これはこの委員会のほうにお聞きしていいのかどうかわかりませんが、このＣという中の評価であればお聞きをしたいなと思いますけれども。そこのところだけ説明を求めました。","respondent":"榎本行財政改革担当課長","answer":"その辺は要はやってもやらなくても同じという形での委託ではなく、もっとそういうような委託方法を研究したらいいのか検討して、実際的に利用率が多くなるような形での運営に努める努力を求めるというような形での方向性になってくると思います。","id":"exchange-016"},{"speaker":"嶋委員","kind":"質問・要望","question":"なぜか不思議と暖景苑はいいという人と悪いという人の評価が、エンジンというか、ガソリンのにおいが常にしている部屋があるんです。女性ですから特に利用する方が多いので、もうぜひ存続していただきたいし、ひとつこの辺はちょっとどういうふうに。","respondent":"中尾根企画部長","answer":"そういうところから見たときにどうなのかという、非常に厳しい根底的な問い詰めをしていかなきゃならないという認識でやっております。それを含んで、今回についてはそういう認識で職員側はいるということでご理解をいただければと思います。","id":"exchange-017"},{"speaker":"松澤委員","kind":"質問","question":"事務事業評価レポートも２年目ですけれども、１年前も大変反響を呼びまして、あとこれの配付方法ですね。一般区民にこれが届くまでの過程、各団体に郵送したりとかいろんなことがあるでしょうけれども、その辺をちょっと教えてほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"と同時に３月２１日号の広報しながわで、その各地区センター等、図書館等の施設内で配付しておりますということをあわせて載せております。この事務事業評価レポートの内容と事務事業評価報告書の内容がホームページで閲覧できるような形での掲載をしています。","id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"そうしますと、地域センターなんかに行けばパンフレットや何かが置いてあって、いただけますかというと自由にいただけるという形という理解でよろしいんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"窓口のほうで置いてありますので、区役所の区政資料コーナー等を含めて、窓口のほうで置いてあります。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/373656?Template=document&Id=5704#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":29151,"voices":60}},{"id":"h14-20020430-6","meetingId":"h14-cm04","date":"2002年4月30日","dateIso":"2002-04-30","committee":"区民委員会","time":"午前１０時０４分～午後４時３３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/345074?Template=document&Id=2324#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":2068,"voices":5}},{"id":"h14-20020508-6","meetingId":"h14-cm05","date":"2002年5月8日","dateIso":"2002-05-08","committee":"区民委員会","time":"午後１時０４分～午後２時３４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"ちょっとお聞きしたいんですけれども、年２回訪問しておられるということですから、この間に何回か訪問されたんだと思います。今の時点で、また新たにこういう事例が発生する可能性を持っているケースというのはあるのかどうか、その辺をちょっとお聞かせ願えればと思います。","respondent":"宮地区民課長","answer":"ほかに３件ありますが、連絡を取りながら、払えるような状況について打合せを行っているところです。訪問２回とかの回数に関係なく、例の賃金雇用対策のための取り決めなども活用しながら、積極的に回収に努めていきたいと考えているところです。","id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"訪問した際に、例えば、そのときに無職であるとか、どうあがいても、年間にしても、毎月の返済はその時点で不可能である場合に、例えば就職するまで待ちましょうとか、そういう対応の仕方というのがあるのかどうか、ちょっとそこだけとの意見を述べました。","respondent":"宮地区民課長","answer":"例えば、まとまったお金が入ったときにでもお支払いいただくとかいったことはあります。審査会の中で決定をしていただくとかということもありますので、その厳しさの状況に応じた手段が一応取れるような形にはなっているところです。","id":"exchange-002"},{"speaker":"原委員","kind":"確認","question":"一つだけ確認をしたいんですけれども、これは初めてのケースか尋ねました。","respondent":"宮地区民課長","answer":"過去にも、平成１０年に一度あります。私が掌握しているのは、平成１０年６月２９日に、やはり区民委員会の中でご報告しました。","id":"exchange-003"},{"speaker":"原委員","kind":"意見","question":"そのときの状況と今回の状況とは似たようなものなのかどうかということと、それから、基本的に、例えば滞納年数が何年とか、あるいは督促が何回とか、そういうものは決まっていて、話の上でこういう形になったのかどうなのかということなんですがとの意見を述べました。","respondent":"宮地区民課長","answer":"各月の分割を引き続き行っているところです。夜間、あるいは休日等も含めまして何回でも訪問、あるいは督促電話をしています。","id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"話し合いの中では応じなかった特別な事情というのがあったのか、どうか、このケースは。その辺は、何か特徴的なことがあるんか尋ねました。","respondent":"宮地区民課長","answer":"この方は２００１年７月には在宅していたので、滞納を説明して、支払うように話はしたということの履歴を繰り返しになるわけです。そういう工夫ができないかなとは思っているんですけれども、まだまだ工夫をしなければならない点はあろうかと考えています。","id":"exchange-005"},{"speaker":"本田委員","kind":"質問・要望","question":"制度ですから、貸し金融業とは違いますので、すぐに訴訟を起こして取り立てるというのも決していいとは思いません。あまり役所が冷たさを感じられるようなやり方はしないほうがいいと思っているんですが、その辺、要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"それと、平成１４年２月からということですけれども、２、３、４月というのは、実際に返済されているのでしょうか。本田委員の質問に対する課長のご答弁の中で、「債権回収のプロに」というお言葉が出たんですけれども、これは具体的にどんな人なんか尋ねました。","respondent":"宮地区民課長","answer":"そちらのほうで、既にもう求職の方が２４件、求人が３件ということで、２４日にオープンしてから今までの件数はそういったところだそうです。５月に入りましたので、今、計画しているところです。","id":"exchange-007"},{"speaker":"石田副委員長","kind":"質問・要望","question":"１点だけ教えていただきたいんですが、違約金２万１,０００円というのがあるんですが、何かこれといってこちらから求める基準があるのか。違約金の内容というのか、どこまで求めて、どれだけこの金額に追加になっているのか。","respondent":"宮地区民課長","answer":"一応、支払い期限までに払っていただかなかった分ということで、それぞれの元金に対する率を掛けて計算しております。２万１,０００円の部分がちょうど違約金に当たるところで、１０万９,０００円が、そもそも貸し付けている奨学金の元金ということになります。","id":"exchange-008"},{"speaker":"石田副委員長","kind":"質問","question":"いろいろな決め事があると思うんですが、わかれば、後で教えてください。今、資料をお持ちじゃないんでしょう。","respondent":"宮地区民課長","answer":"置いてきました。","id":"exchange-009"}]},{"id":"topic-02","title":"４月３０日に南多摩斎場を視察に行きまして、それを受けて、臨海部広域斎場の運営","agenda":"４月３０日に南多摩斎場を視察に行きまして、それを受けて、臨海部広域斎場の運営","exchanges":[{"speaker":"原委員","kind":"意見","question":"今、ご説明いただいたんですが、ここのオープンについて、当初の説明より若干早くなっているという話もありますので、そういった予算の関係、あるいは、今度はそれに対する我々の意見をどう持って行かれるかというところの時系列的なものを含めて、ちょっとお話を聞かせてくださいとの意見を述べまし…","respondent":"宮地区民課長","answer":"一定程度の運営についての方針が固まっておりませんと、そういう意味からも、かなり急ピッチで検討を進めていかなければならないという状況です。６月ぐらいには、こちらの意見を持ち込みたいと考えておりますので、その段取りをつける意味でお願いできればと考えております。","id":"exchange-010"},{"speaker":"原委員","kind":"質問・要望","question":"例えば環境は全部やりましょうとか、あるいは、全体的な中で、すぐに決められないものがありますよね。その辺のところも、ちょっとあわせて決めていくというか、はっきりしていただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"本田委員","kind":"質問","question":"議論する前にベースになる話なんですけれども、基本方針は、一部事務組合に入っている他区の議会、所管でも、同じ資料で議論をすることになっているんか尋ねました。","respondent":"宮地区民課長","answer":"はい、同じ資料を、各区の議会でも検討するということです。こういう意見が出ているということで持込みたいと考えていますので、ぜひ、ご協力をお願いいたします。","id":"exchange-012"},{"speaker":"本田委員","kind":"質問","question":"ＩＳＯを取るべきだという意見を、3)の今後の課題にしようじゃないかというようなこともあるかもしれない、そういうところに落ち着くかもしれない。そういうふうに進んでいくわけなんか尋ねました。","respondent":"宮地区民課長","answer":"５区のことですから、ご意見はご意見で出していくという形に、それぞれの区でやっています。そういうおつもりで結構です。","id":"exchange-013"},{"speaker":"本田委員","kind":"質問","question":"それなら、きょう、限られた時間の中でできるところまで進めて、お互いに一致できるところではどんどん意見として上げたほうがいいではないのですか。残ったら、残ったで、また次の委員会でやっていけばいいんじゃないか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"原委員","kind":"質問","question":"ごみの扱い等については、各業者が持ち帰っているのが現状になっているんですから、そういった形を続けるしかない。したがって、仕出し業者は指定した形で斎場に入れてくるわけですから、そういった中での持ち帰りという話になってくるのではないか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"堺委員","kind":"意見","question":"それから、５の副葬品の制限については、摘要にも書いてありますとおり、2)の制限あり。というふうなことで落ち着きましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"菊地委員","kind":"意見","question":"共産党は、１、２、３、それから５番目の副葬品の制限のところまでは、今の公明党のご意見と同様であります。ＩＳＯにつきましては、今のごみ等の問題も含めて、取得をしていくという方向で考えていけるのではないかと考えておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"本田委員","kind":"質問・要望","question":"２３区として初めてつくる斎場ですから、業者の方々とも十分協議をして、協力をいただいて対応していくことを進めていただきたいと思うんです。〔「生花は1)ですか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"石田副委員長","kind":"質問","question":"式場のみじゃなくて、全部を使用許可範囲内でどこでも認めるということですか。1)ですか、2)か尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"本田委員","kind":"質問","question":"そういう認識なんですけど、設置を認めるのと、式場内のみの限定で認めるというのは、どう違うんですか。普通、生花というのは。","respondent":"宮地区民課長","answer":"設置を認めるというのは、もう屋外も含めてなんです。式場の中のみは2)ということです。","id":"exchange-020"},{"speaker":"金高委員","kind":"意見","question":"検討課題ではなくて、前向きな検討課題とするということで、どちらかというと1)に近いような形の検討課題と理解していただいて結構です。５番目の副葬品については、遺族が、やはり全体的な環境問題で制限したほうがいいんじゃないかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"原委員","kind":"質問","question":"ほとんど協定葬儀をしてないのが多いわけですから、一応、とにかく現状の品川区でやっているものが可能かどうか持って行ってほしいということです。〔「実施するのですか」と呼ぶ者あり〕実施するです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"石田副委員長","kind":"質問・要望","question":"４対１ということもあって、なぎさ会館でやっているわけですから、品川区独自の協定葬儀をやっていただきたいというのが希望であります。言い方は変だけど、採算ベースというのか、安くなるというものが見えた場合には設置をしてほしいという話です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"堺委員","kind":"質問・要望","question":"５番目の仮泊については1)、６の協定葬儀については1)、ぜひそういう方向で取り組んでいただきたい。ですから、あえて、もう一言申し上げると、全く同じなんですが、組織市民についての火葬料については無料。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"菊地委員","kind":"質問","question":"桐ケ谷斎場が今後休んでいるということもありまして、せっかく行政でやるものですから、年始外は開業する方向が一番望ましいのではないかと考えます。結構、いずれにしても、できる限り安い料金で利用ができればいいというのが私どもの考えです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"本田委員","kind":"質問・要望","question":"１番のところは、もう桐ケ谷斎場は１週間ぐらい待っている状況ですから、友引でも構わないという考え方が結構多いですから。それが弔うような因習というのがあるものですから、ここでは、持込みオーケーとしていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"金高委員","kind":"質問・要望","question":"安い費用で行うのが一番いいわけですから、2)、3)を適応した形での方向づけが望ましいと思います。当然、これは負担をそれなりに葬儀を行う家のほうで考えるわけですから、持込みオーケーにしていただければ対応しやすいのではないかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"原委員","kind":"質問・要望","question":"現在２４９台を予定されているということなんですけれども、それについて、管理をどうするかということが課題になるわけです。そこからの関連もあるわけですから、その辺の折衝もしていただき、視野に入れた形での中で進めていただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"堺委員","kind":"質問・要望","question":"１２番目の交通アクセスについては、最寄りの駅からの交通アクセスについては、十分検討してほしいと求めました。そういうふうに要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"菊地委員","kind":"質問","question":"先日、南多摩斎場に伺ったときに、火葬業務の大変さという裏話が出ておりました。骨壺販売については、1)、2)を混ぜて、自由に考えるべきものではないかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"本田委員","kind":"質問・要望","question":"流通センターのところからは、全く人気のないところで、ふだんでは何もないところですから、あそこは。犯罪などが起きないことを願っておりますが、そういう場所ですから、十分安全の確保というのは検討していただきたいということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"金高委員","kind":"質問・要望","question":"それから、受付業務ですけれども、これは日中ですから、当然、組合のほうで行うのが望ましいのかなという感じがいたします。そこに行かれる方が一番便利で安全な方法がとれるように、ぜひ、いろいろな角度から検討していただきたいです。","respondent":"南委員長","answer":"では、皆さんからそれぞれ意見を出していただきまして、ありがとうございました。ここは言い残したとか、こういうふうにもう１回考えたいとか、ご意見、補足がもしありましたら、出してください。","id":"exchange-032"},{"speaker":"原委員","kind":"質問","question":"そういうのにあわせて一体統一的な考え方でできるならと思うんです。時間がかなり難しいという話にもなっているわけですから、その辺は十分、お考えいただければと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"石田副委員長","kind":"質問・要望","question":"今の段階では、白タクみたいな形で許されないと思うけれども、そういうことも含めて折衝するという考え方も持っていただきたい。ただ、法律でだめというのではなくて、そういう考え方も持てるのかどうか、法的なことも含めて調べていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/345074?Template=document&Id=2326#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":26093,"voices":96}},{"id":"h14-20020508-7","meetingId":"h14-cm05","date":"2002年5月8日","dateIso":"2002-05-08","committee":"厚生委員会","time":"午後１時６分～午後３時４８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"船波委員","kind":"質問","question":"障害者ホームヘルプサービスについて、まずお伺いしたいと思います。平成１０年度から実績の数が減ってきているんですが、どうして減ってきてしまっているのか尋ねました。","respondent":"日下部障害者福祉課長","answer":"「品川区の福祉」の中で、平成１０年度が２６０世帯、平成１１年度が２７７世帯、平成１２年度が１１４世帯ということで半分以下に減っております。基本的には６５歳以上の方については介護保険のほうに移行いたしましたので、かなり対象者が急減したです。","id":"exchange-001"},{"speaker":"船波委員","kind":"質問","question":"それから、東京都の政策の見直しに伴っての変更というご報告ですけれども、２・３・４段階の方々の無料の部分を廃止するというのも、東京都がやめてしまうから仕方なくやめるということなんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"東京都がやめるから仕方なくと、先ほども説明の中で触れましたけれども、もともと品川区としても実施にあたっては要綱のもとに実施しております。これを一つの契機にしまして品川区としても、これにあわせて原則に戻してご負担をいただくということで進めてまいりたいと…","id":"exchange-002"},{"speaker":"船波委員","kind":"質問","question":"そうしますと、週３回９時間を無料にする分の費用的な負担というのは、東京都がすべて担っているわけか尋ねました。","respondent":"日下部障害者福祉課長","answer":"実は東京都の制度では週２回６時間、これに品川区が加算をして週３回９時間まで無料ということで対応してまいりました。したがって、残りの１回分については品川区が独自に持ち出しましょうということで今まで対応しておりました。","id":"exchange-003"},{"speaker":"船波委員","kind":"質問","question":"東京都が週２回６時間のところを、それはホームヘルプサービスというのが、ここでどうして廃止してしまうのかということを疑問に思うんです。２番の障害者ホームヘルプサービス事業は東京都が減らすから品川区も減らすという、１番と２番の考え方の違いはどこから出てくるんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"ただ、先ほども申し上げましたけれども、９０％の、一定の収入しかない方については、利用者負担についてはいただかない。ただ、相応の収入のある方については、収入に応じまして一定のご負担をいただくという考え方をきちんと生かしてまいりたいということです。","id":"exchange-004"},{"speaker":"船波委員","kind":"質問","question":"その方々が週３回９時間の無料制度を目いっぱい利用したとしても、その部分の費用は大きな額ではないと思うんです。ですから、これぐらいだったら継続してはどうかと思うんですけれども、そういう検討はされなかったんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"確かに金額としてそんなに大きいものではありませんけれども、それぞれの収入に応じた形でご負担をいただくということであります。介護のほうでいくと大体７％程度のものについては、一定のご負担をいただこうという考え方でいきたいということです。","id":"exchange-005"},{"speaker":"船波委員","kind":"質問","question":"わかりました。「品川区の福祉」によりますと、その人が全体で利用している時間のうち週３回９時間というのはどれぐらいの割合のものだったんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"一方で、１階層の無料の方たちがどのぐらい利用しているかということで計算をしてみますと、やはり平均で月当たり１世帯１７時間です。必ずしも今後負担があるから利用を抑制されてしまうという結果にはなってこないのではないかと考えております。","id":"exchange-006"},{"speaker":"船波委員","kind":"質問","question":"では、１番のほうと２番の障害のある方に対するサービスですけれども、平成１５年度以降に新規制度ということになった場合、どういうふうに変化していくものなんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"ただ、これは以前の委員会でもご説明させていただきました。来年４月以降も、基本的にこの中身が大きく変化するということはございません。","id":"exchange-007"},{"speaker":"船波委員","kind":"質問","question":"３番のほうですけれども、指定廃止をされてしまう二つの病気に関しては、どうして廃止されてしまうのか尋ねました。","respondent":"日下部障害者福祉課長","answer":"私のほうでご説明させていただいて、もしそれ以上の話になれば、専門家のほうから補足をさせていただきたいというふうに思います。そういうことを勘案しますと、もはや従来の難病という形でこのまま指定を継続することは、必ずしも適切ではない。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１点目のところからお聞きしたいんですが、小規模と中規模の違いについて教えていただきたい。３点目のところでは、これ以後はどうするのかということと、人数がどのぐらいいるかということを教えてほしいと求めました。","respondent":"日下部障害者福祉課長","answer":"それから、全体の丸々かかっている経費は平成１３年度の実績でまいりますと、７８３万７,０００円ということになります。人数ですけれども、全体でどのぐらいかということであたってみましたら、最大で２００世帯ぐらいいくのではないかというふうに見込んでおります。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２番目についてですが、１１人で７８３万円ということなんですが、そのことについて教えていただきたい。介護保険で言えば、利用料というのは１割ですけれども、その点についてはどういうふうに考えているか説明を求めました。","respondent":"日下部障害者福祉課長","answer":"ただ、それについての自己負担分の割合をどのくらいかということで計算すると４％ぐらいになってまいります。ですから、確かに介護保険の１割より若干高めにはなってまいります。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"生計中心者の前年所得が３０４万５,０００円以下でなければ無料でなくなるということなんですけれども、ほかの家族もいるわけです。この辺の３０４万５,０００円という考え方というか、しかも生計中心者というところではどういうふうに考えられているのか尋ねました。","respondent":"日下部障害者福祉課長","answer":"そういう形で、必要な対応というのを品川区として実施をしていく責任があると思います。その分の金額の加算ということで、そういうことをいろいろ勘案しますと、相応の負担ということで納得はいただけるのではないかと考えております。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この辺のところはぜひ１４０万円を節約するために３０４万５,０００円以上の所得の方から無料制度を廃止するということはぜひ改めていただきたい。そういうことに対して東京都が医療費助成を打ち切ることになったわけですが、そういう点について品川区としてどう考えられているか尋ねました。","respondent":"日下部障害者福祉課長","answer":"やはり国の政策の問題、国としてどういう形で対応していくか、そういう視点も含めて総合的な観点で物事をとらえるということが重要だと思います。少なくとも平成１５年３月までは現行を継続する、それから経過措置についても実施をするということで…","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、新たにＣ型肝炎の問題が大きくクローズアップされて、これから検診でさらにＣ型肝炎が発見される人が増えてくるんじゃないかと思うんです。品川区からも言っていただきたいなという思いがするんですけれども、その点に関してはいかがか尋ねました。","respondent":"日下部障害者福祉課長","answer":"私どもとしましてはその辺の専門的な考え方も含めて、なかなかそれについてものを申すというのは非常に難しい立場にあります。医療費の助成は東京都の判断で進められるわけですから、何とか激変緩和ということで経過措置を講じていくということで進めていきたいということです。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"きちんと治療すればすぐに生命がどうのということではないというところまでいっているのがＣ型肝炎の今の現状だと思うんです。本当に二重の大変さになるわけですから、ますます治療が受けにくいという状況をつくり出すわけですから、いかがか尋ねました。","respondent":"小林品川区保健所保健サービス課長、日下部障害者福祉課長","answer":"先ほど答弁申し上げましたように、新たな感染症としての対策を講じていく必要があるということで、東京都が施策を変えてきたという考え方です。患者に対しての療養上の支援については、今までと何ら変わらなく対応してまいりますし… 先ほどから再三ご説明していますように、おそらくこういう形での経過措置というのは、２３区の中でも非常に一番手厚い形で対応する中身だと思います。そういった意味では、品川区としてもできる限り頑張っているつもりですので…","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、保健サービス課長からお話がありましたけれども、Ｃ型肝炎、慢性肝炎の通院治療の必要性というところについてはいかがでしょうか、その辺のところが一番大事なところかなと思うんですけれども、その辺について専門家としてご意見をお聞かせいただきたいと思うんです。","respondent":"小林品川区保健所保健サービス課長","answer":"もちろん治療の必要性ということについては、私どもも十分認識しております。ほかの疾患等の不公平性、ほかの疾患との公平性等を考えますと、この制度を含めていくというには無理があるのではないかというふうに考えております。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"Ｃ型肝炎は旧厚生省の責任の問題もありますし、Ｃ型肝炎がこれからさらに増えて、国民の中でかなり重要な位置を占める病気になると思うんです。そしてまた、ぜひこのことについてはさらに実態を見ながら考えていただいて、品川区としても対応してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"嶋委員","kind":"質問","question":"所得制限もあるということでお聞きしたいのは、限度額を超えた分を利用者が負担をする場合、分割ができないのかどうか。さっきは小規模、次はこういうふうに改善したいという回数的なものが出てくるのかなと考えていますが、その辺をお聞きしたいと思います。","respondent":"日下部障害者福祉課長","answer":"その辺のやり方が、実際の制度の運用上も含めて可能なのかどうかということについては検討をさせていただきたい。すべてがいいというわけにいきませんけれども、そういうことも可能だということです。","id":"exchange-017"},{"speaker":"嶋委員","kind":"質問・要望","question":"区民健診での啓発が広報紙以外にどのようにされているのか、もしわかったら教えていただきたい。それから２番目の新規難病指定の６疾病のことなんですが、６疾病がわかりましたら教えてほしいと求めました。","respondent":"田中健康課長","answer":"昨年の６月に当時の厚生労働省が緊急に検査をということで、保健所等でＨＩＶ検査の中に取り込みまして、昨年１０月まで実施をいたしました。それから、アレルギー性肉芽腫性血管炎、原発性硬化性胆管炎、肝内結石症、自己免疫性肝炎の６疾病です。","id":"exchange-018"},{"speaker":"嶋委員","kind":"意見","question":"これは後で勉強したいと考えています。５０名ということなんですが、それだけのスピードでこういう方たちがいらっしゃるということを私たちも認識していきたいと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"須藤委員","kind":"意見","question":"１番目の住宅改造ですけれども、どうして小規模、中規模だけやるのかなと。それから、介護保険との兼ね合いというのはどういうふうに絡んでくるのかなと、２点お願いしますとの意見を述べました。","respondent":"日下部障害者福祉課長","answer":"これ以外にも１級の方、歩行が全くできなくて、これについては１３３万２,０００円ということで限度額を設定して実施をしておりますし。そこで不足前が出てくれば、障害者の住宅改修を不足前の部分についてはこちらで埋め合わせをするという仕組みになっております。","id":"exchange-020"},{"speaker":"鶴副委員長","kind":"質問","question":"今も多くのことでレジュメ１枚しか報告書は書いてありませんが、質問の対象となったことについてどうして最初から説明をなさらないのか。二点、そして当該課が職員を派遣するなり審査を行って給付の額を決定するということになるのでしょうか、そうではないのか尋ねました。","respondent":"日下部障害者福祉課長","answer":"ご質問の中にございました、まずはご相談をいただきまして、私どものケースワーカーが実際に住宅を拝見します。経費の問題とかいろいろ付け合わせをさせていただいて、正式にご申請をいただくという形で手続を進めていくという形になっております。","id":"exchange-021"},{"speaker":"鶴副委員長","kind":"質問","question":"それについて従前の高齢者のための介護保険制度以前のものですが、品川区で行っていた助成事業がございました。その比較においては遜色のあるものですか、ないものですか、詳しく説明していただけませんか。","respondent":"日下部障害者福祉課長","answer":"高齢者の住宅改修のほうと全く同一ではありませんけれども、大体中身としましては同じような中身を基本にして制度を運用してまいりましたので、そういった意味では障害者のほうも従前の高齢者の住宅改修に比べて遜色はないのではないかと受け止めております。","id":"exchange-022"},{"speaker":"鶴副委員長","kind":"質問","question":"今回大きくわけて三つのサービスの改正につきましての当該受益者がそういう事業の対象となるであろうと思われる障害者の方々に対する説明というか、改正の徹底というのはどういう方法でなされるわけか尋ねました。","respondent":"日下部障害者福祉課長","answer":"ですから、しっかりとその辺の制度の改正、利用の促進については取り組んでいきたい。対象となるような方については、その辺の内容を十分に個別にも周知をしていくと、このように取り組んでまいりたいと考えております。","id":"exchange-023"},{"speaker":"鶴副委員長","kind":"質問","question":"しかるべき措置をとっているという、他と違った施策の展開をやっているわけですから、広報「しながわ」にはスペースの関係があります。アンケート調査を取るということは大変ですので、いかがか尋ねました。","respondent":"日下部障害者福祉課長","answer":"それと同時に、やはり区民の皆さん方に対しても説明責任をしっかりと果たすと。そういった意味で、ホームページの活用というのは、非常に重要な役割を果たしますので、最大限その辺の活用を図ってまいりたいと考えております。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それから、ちょっと気になったところが、３３ページにありますモニタリング情報の収集がよくわからなかったので、簡単に教えていただきたい。これをただ提言だけに終わらせるのではなくて、何かしら品川区としてやっていく必要があるのではないでしょうかということを説明を求めました。","respondent":"新美保健高齢事業部長","answer":"第１期の２年間、今後のことを考えますと、これは十分品川区としても引き続き検討していきたいということで考えております。２点目の、それぞれ所属する組織体、我々も合わせて連携して体制を取っていきたいと考えています。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問・要望","question":"実際、提供しているサービスがどうなっているかということをフィードバックするシステムが今のところないというわけですから。これは人と人とのサービスですから非常に難しいところがありますけれども、それはある程度品川区のほうで手当てしたほうがいいんじゃないか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから、９ページに在宅介護支援センター別抽出結果というところで、ケアマネージャー６３名のセンター別の数を教えてほしいと求めました。そして、１００件以上が２５.４％という数になっているんですが、この辺のことについて品川区としてどう考えられているのか説明を求めました。","respondent":"新美保健高齢事業部長","answer":"つまり手法の開発・実施ということを含めて、３年間で仕組みづくりをしようということで考えておりまして、向上の仕組みづくりをしていく予定です。今年度は一応３年目で一通り手法・基本サービスについて、今年度以降はどうするかも含めて検討するわけですが…","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここのケアマネージャーの方々の質問項目の中で、この結果に対しては品川区としてどういうふうに考えられているのかお聞かせほしいと求めました。もう一つ、それとも別な形で、それプラスの形で研修をどう考えられているのかについてもお聞かせほしいと求めました。","respondent":"高橋介護保険担当課長、新美保健高齢事業部長","answer":"年が明けますとそれぞれの在宅介護支援センターに呼びかけて、新人を含めた研修を４日間ぐらいやってあります。それぞれ時期に合わせて、在宅介護支援センターの連絡委員会の中で… 現時点の考え方は、先ほど申し上げたとおりですが、検討をしていきたいというふうに考えております。自由回答も含めて不安とか悩みとか、今日は特にご報告しませんでしたが、引き続き受け止めてしかるべき対応をしていきたいと思います。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"悩み、そういう形のものを充実させるというところと、やっぱり体制をきちんと取っていくということが求められているんじゃないかと思うんです。ここで基本的な考え方のところに書かれていますが、ここのところでは具体的にどういうふうに考えられているのかお聞かせほしいと求めました。","respondent":"新美保健高齢事業部長","answer":"今、ご質問にありましたように、最後の提言のところで今後の地域におけるケアマネジメント体制についても触れられております。在宅介護支援センターを核としつつも、それ以外の居宅支援との関係のつくり方等々を含めて検討をしていきたいというふうに考えております。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところなんですが、ずっと民間の居宅介護支援事業者の方に対しても説明会をしてほしいということで、今年の２月にされたと思うんですが、その中でどのような民間の居宅介護支援事業者の方からの意見が出されたのかお聞かせいただきたいんですけれども。","respondent":"早津高齢福祉課長","answer":"大きなテーマは東京都が実施した利用料軽減についてどう扱うかということを説明しつつ、いろいろなご意見をお伺いいたしました。私どもとしましては、５月中旬に第２回目の会を開催する予定です。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ変えていただきたいというふうに思いますし、そしてさらに品川区全体が前進していけるような形でやっていただきたいというふうに思いますけれども、いかがか尋ねました。","respondent":"早津高齢福祉課長","answer":"今後の評価の事柄については、また介護サービス向上委員会の中で検討をしていきたいと思います。介護サービス向上委員会の中で検討をしていきたいというふうに考えてあります。","id":"exchange-031"},{"speaker":"嶋委員","kind":"質問","question":"４７ページの日常業務を通じて自己研鑽を深める、いわゆる個々のケアマネージャーの裁量を尊重しながらという文面がたくさん出てまいります。そういう意味では、背中を押すというのがどのぐらいのペースで１７カ所を回っていらっしゃるのか、この１点だけお聞きをしたいと思います。","respondent":"早津高齢福祉課長","answer":"そうたくさん回っているわけではございませんが、機会を見つけて行くようにはしています。例えば、在宅介護支援センターによってばらつきが出ているのは事実なんですが、私のほうでもなるべく現場の在宅介護支援センターの状況。","id":"exchange-032"},{"speaker":"須藤委員","kind":"質問","question":"平成１４年３月に答申が出されたんですけれども、答申が出された時期は介護保険制度が始まってどのくらいの期間が経ったんか尋ねました。","respondent":"早津高齢福祉課長","answer":"３月ですので、約２年ということになります。","id":"exchange-033"},{"speaker":"須藤委員","kind":"意見","question":"「まもなく２年を迎えよう」というのが冒頭に書いてあるので、昨年も「まもなく１年を迎えよう」というのが昨年度の報告に書いてあるんです。１４年３月に出てきたときに、「まもなく２年を迎えよう」という表現で答申書を出してきてしまうと、カウントの仕方が私が違うのかなとの意見を述べました。","respondent":"新美保健高齢事業部長","answer":"３月２５日の品川区介護サービス向上委員会で取りまとめ、３月時点でまもなく月末には２年という意味で書いております。その辺は、ご理解をいただきたいと思います。","id":"exchange-034"},{"speaker":"須藤委員","kind":"質問","question":"これは残るものなんだから、その辺を気をつけていただければと思うので、わざとそういう質問をしました。利用者の回答率が５８％、そのときの介護度については１１ページに載っているんだけれども、返答のない４２％の人の介護度というのはわかりますか。","respondent":"新美保健高齢事業部長","answer":"今回、抽出を全数ではなくて、全体の３分の１程度を無作為で抽出したので、介護度別にバランスを取るというのはなかなか難しくて、結果どういう要介護度かしか、ここではわかりません。","id":"exchange-035"},{"speaker":"須藤委員","kind":"質問・要望","question":"逆にここから数字を見ると、感謝が３８.９％、要望と苦情というのを加えると５７.７％という数値が出てきているんです。そのことに対しては逆に言うと３割、そういうところの回答者と同列に比較をして統計上の分析の仕方がいいのかどうか、その辺はいかがか尋ねました。","respondent":"新美保健高齢事業部長","answer":"ただ、確かに無回答の率が１０ポイントほど全体に高くなっておりますので、どうしても無回答の回答が多くなる傾向は受け止めざるを得ないので。最後の自由記入欄は、ここの特色も有効回答７２７人中１５５人、２割強の方が自由回答欄に記入をしていただいていたんですが…","id":"exchange-036"},{"speaker":"須藤委員","kind":"質問","question":"今言ったように無回答を入れちゃうと４割ぐらいのものも出てきているわけで、そういうものはどういうふうに考えて分析をされているのか。そうしないと、落差がこうあったとか、そういう誤差みたいなものはどういうふうに考えていらっしゃるのかなというのを説明を求めました。","respondent":"新美保健高齢事業部長","answer":"やはり、数も３分の１やっておりますので、６割の回収率であれば大筋の傾向を見るべきものという認識でおります。どうしてもこういう結果になってくるとか、単純に数字同士を比較して、単純に云々ということはすべきではないというふうに考えているところです。","id":"exchange-037"},{"speaker":"須藤委員","kind":"質問","question":"今、５８％ぐらいあって、実質的な回答率というのはもっと下がっているわけです。先ほど言った返事がなかったのはどういう人たちなんだという、こんなふうに考えるんですが、いかがか尋ねました。","respondent":"新美保健高齢事業部長","answer":"今回、初めてこういう形でやりましたので、ご意見あるいは今後の状況と、また何年かに１回ずつ繰り返しやっていく形を取っていきたいと現時点では考えておりますので、そういったところにもう１回工夫をしていきたいというふうに考えます。","id":"exchange-038"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"ここのところを目を落としたものですから失礼いたしました。つらいけれどもお年寄りのために、私自身にとっても課題になっているわけですが、どうしていこうというふうに思っていらっしゃるか尋ねました。","respondent":"新美保健高齢事業部長","answer":"４ページ５ページぐらいは、では今のケアマネジメントサービスはどうなのかということを見ていかなければいけないという認識で構成をしています。ただ個々の事業者、それをきちんと果たしていくことは保険者責任という部分にあたるのではないかというふうに認識をしています。","id":"exchange-039"},{"speaker":"鶴副委員長","kind":"質問","question":"そこで働く人たちのことについては給与の面でも、処遇はどういうふうになっているのかなというふうに、それは疑問の点なんです。何かわかれば、わからなければわからないでいいんですが、どうなっているんだろうというものがありますので、わかれば教えていただけませんか。","respondent":"新美保健高齢事業部長","answer":"ただ、それぞれの人事体制をつくっていくということで、今それぞれが頑張っていただいているところだというふうに我々は認識しております。違法があれば、もちろん区としての指導は当然いたしますけれども、通常は自主努力です。","id":"exchange-040"},{"speaker":"高木委員","kind":"質問・要望","question":"される側の意見、そういう人は意見を求めてもなかなか取り上げるのは難しいのかもしれませんけれども、介護体験者。私は昨年の８月２４日にちょっとした事故で１週間入院して、そういう生活を送ったものですから、私は介護される体験を得たと思っているわけなんです。","respondent":"新美保健高齢事業部長","answer":"ただ、利用者アンケートのほうは、今回につきましてはご本人が記入されたのが４割は占めております。今ご意見があったような利用者本人をどういうふうに声を把握するか、その辺を工夫していきたいというふうに考えております。","id":"exchange-041"},{"speaker":"高木委員","kind":"意見","question":"私は１年間分６万５,０００円ぐらいかな、これは深刻になりましたね、１年間まとめて納めるとするとですね。いろいろ私は口出しはあまりしないつもりですけれども、一人の被保険者としての実感を、びっくりしたということを申し上げて終わらせていただきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一つ、私も半年に一遍の更新のときぐらいしかケアマネージャーの方が来ないという話を何回かお聞きしたことがあるんです。この辺のところの実態についてと、本来あるべきモニタリングがどうなっているのか説明を求めました。","respondent":"早津高齢福祉課長","answer":"１カ月といわずに必要なときにケアマネージャーたちは顔を出し、電話をしたりというような活動を続けております。なるべくこのようなことのないように、私どものほうでもモニタリングを継続的に行うようにということをお願いしています。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"本来であれば、１カ月に一度くらいは利用者のところにケアマネージャーがお伺いして、実態を見るということが必要だというところなんか尋ねました。","respondent":"新美保健高齢事業部長","answer":"すべてを１カ月に１回行くというのはなかなか難しいかと思いますし、それが本当に必要かどうかということにもなるかと思います。あるいはヘルパー、いずれにしてもいろんな手段を取ってきちんと状況を把握していくことが肝心である、機械的である必要はないという考え方です。","id":"exchange-044"},{"speaker":"林（和）委員長","kind":"質問・要望","question":"平成１３年請願第１２号、新たな大気汚染公害被害者の救済を求める意見書に関する請願につきましては、よろしゅうありますか。〔「異議なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"鶴副委員長","kind":"質問","question":"この１年、かつ活発な質問、今ご推察をしています。この１年、本当にありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/534819?Template=document&Id=3016#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":44792,"voices":103}},{"id":"h14-20020508-8","meetingId":"h14-cm05","date":"2002年5月8日","dateIso":"2002-05-08","committee":"建設委員会","time":"午後１時０５分～午後３時１０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"平成１３年請願第５号、住友不動産による「仮称 大崎５丁目マンション」超高層、高さ１００ｍ、３０階建てに対する請願","agenda":"平成１３年請願第５号、住友不動産による「仮称 大崎５丁目マンション」超高層、高さ１００ｍ、３０階建てに対する請願","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"都の建築審査会ですか、住民が総合設計の取り消しですか、この取り消しを求める関係で６月２０……６月か。何かあるんですか、その辺は。","respondent":"浜脇住環境整備課長","answer":"結べなかったので、やっと４月２０日の日に結んだから、ある意味では大手を振ってやっているということだと思うんですね。ですけど、今も粛々と工事をやっているのは事実です。","id":"exchange-001"},{"speaker":"築舘委員","kind":"質問","question":"この本工事協定を結んだ守る会というのは、この請願書を出している大崎および品川の環境を守る会ということでよろしいんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"はい、冒頭にありましたでしょうけども、大崎および品川の環境を守る会ということで、請願代表者以下1,９６６名という方々だと思われます。しかし、そのうちの何名かがそういうことで、会じゃなくして、個人的な形で出されているというふうに聞いております。","id":"exchange-002"},{"speaker":"辻委員","kind":"質問・要望","question":"個々の問題についてはちょっと大きい問題ですから、地域地域によって、こっちについては風害の問題とかというふうな交渉に入ったよということですね。継続で、できればお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"ある程度、本体工事ができたから、採択というのもあれなんだけども、正直言って扱いが難しいなと。これは請願者とまた違うものですから、取り下げてもらうのが一番いいかなという気がするんですけど、そういう可能性があるかということでしたら。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"本間委員","kind":"意見","question":"そういう部分をどういうふうにして配慮していくか、逆の意味での、それを出したことによっておかしくなるのであれば困るということは確かにあります。基本的な形として、この大崎および品川の環境を守る会、一応この辺で結論を出してもいいのではないかなという気がしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"辻委員","kind":"質問","question":"それで、それが多少手直しができた、ですから、沢田委員が話したように、どういう扱いをするか、不採択で願意に沿いがたいというのもおかしな話だ。ですから、こういう状態になっているんですよということをもう一回請願代表者にちょっと話してみたら。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"沢田委員","kind":"意見","question":"終わった後にどうするかという結論が、協定書が結ばれたから採択といっても、それから協定書ができているのに不採択というのも。不採択というのも何かやりづらいような気がするんですけどねとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-02","title":"平成１３年請願第６号、石井ビル建築計画に関する請願","agenda":"平成１３年請願第６号、石井ビル建築計画に関する請願","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"そうすると、これは誓約書を提出して着工したということは、基本点では合意に達したということなんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"１２項目ぐらいあって、変更できなかったという事情があったようでございまして、そういった意味ではすべてが解決したわけじゃございませんでした。こういう工事を行いますということで、設計変更も若干含めた形で時間や搬入路や、そういう誓約書です。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"この問題についても請願者、区議会議員を通じて特に取り下げることはしないと。そのまま出してくださいということなんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"中層棟の設計変更というのと、それから安全な工事を十分説明するようにというのと、みんなアンダーラインしてあるところがメインですよね。さっきの趣旨採択とのバランス上、こっちはだめだというふうにいかないから、この程度であれば趣旨採択としていいんじゃないでしょうかね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"築舘委員","kind":"意見","question":"一番いいのは工事が進んでいるので、取り下げてもらえばいいかなというふうには思うんですけど、それが難しいというさっきの委員長のお話なので、大分進んでいて、そんなに、そういう意味では趣旨に関しての採択をしても…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"辻委員","kind":"意見","question":"だから、ギャラリーがどうこうというのは別として。やっぱり、そういうＰＲをして関心を持たせたほうがいいんじゃないかなとの意見を述べました。","respondent":"中谷まちづくり事業部長","answer":"本件につきましては、広報等につきましても連携いたしまして、パブリシティー等お願いするということになっておりまして、また、デジタルビデオ等で撮影いたしますので、そういうものでＣＡＴＶ等で周知できる余裕があれば、そちらにお願いするということにしていく予定です。","id":"exchange-012"},{"speaker":"辻委員","kind":"質問","question":"このデータを出したときに、沿線の住民に対しては、どういう形でバックするんか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"より詳細な情報が入るですが、こちらの戸越幹線経由については少し検討させていただきたい。今年、事実ＣＡＴＶで情報等を提供するように今ちょっと検討しておりますが、それとあわせてやることも将来的には考えられますし。","id":"exchange-013"},{"speaker":"辻委員","kind":"意見","question":"ただそれをどう使うかということを要するに住民がどうすればいいか。まさしくこれは水防訓練と一緒で、連携が必要との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、形は丸と。ちょっと初歩的な質問で。","respondent":"中谷まちづくり事業部長","answer":"四角い断面の中に、真ん中のところに少し常時水が流れる、雨水が流れるようにつくってあるというのが大体一般的な立会川・戸越幹線の構造になっております。","id":"exchange-015"},{"speaker":"沢田委員","kind":"質問","question":"光ファイバーケーブルなんですけれども、東京都なんかは下水管に光ファイバーを通して、これを売って一もうけするみたいな、前にそんな報道があったと思うんですが、基本的には全部入っているものなんか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"それを民間に開放してということで一時考えたようですが、正直言いまして、ちょっと乗り遅れたというのが実情です。従来から、１０年近く前から都庁周辺では光ファイバーを試験的に敷設して、うまくいけば広げていきたいという考えを持っていると聞いております。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問","question":"ですから、そこら辺がどうなっているのか１点と、系統はどのぐらいあるのか。そこだけ説明を求めました。","respondent":"中谷まちづくり事業部長","answer":"そのような形で変更しておりますので、このシステムが確立されれば、戸越幹線系列だけ流すことはできるというふうになっているです。４カ所既に入っておりますので、警報が鳴るようになっておりますので、そういう点では立会川系統については既にそのようになされております。","id":"exchange-017"},{"speaker":"横山委員","kind":"質問","question":"それとあわせて、品川全体、一つですかね、それとも荏原地区、大崎地区、品川とか、そういう分け方はされてなかったですかね。どういう系統、地域的に分割されていると思ったけど、その辺のちょっと内容を知りたい。","respondent":"中谷まちづくり事業部長","answer":"もしよろしければ、後ほど調査の上、ご報告させていただきたいと存じます。","id":"exchange-018"},{"speaker":"横山委員","kind":"質問","question":"なぜこんなことを言うかというと、この前ちょっと子どもを連れて公園に遊びに行っていたら、防災無線を使って５時にチャイムが鳴りますよね。ですから、ほんとうにうるさく聞こえるというか、何を言われているかわからない。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"辻委員","kind":"質問","question":"ですから、月見橋まで雨水下水管を引っ張ってくるの。立会川のあいているところはどうなるの。","respondent":"中谷まちづくり事業部長","answer":"これで説明させていただきましたが、これを内径3,２００mmの管を月見橋まで抜きまして、そして５０mmの雨まではその管で今度は流れる。一時ためて、雨水をためる工事もできますので、非常に水質状態についても寄与するものです。","id":"exchange-020"},{"speaker":"築舘委員","kind":"質問・要望","question":"それをどういうふうにして、どういうふうに今度持っていくか、ちょっと教えていただきたい。","respondent":"中谷まちづくり事業部長、佐藤委員長、中島街路事業担当課長","answer":"どちらかのことを今検討しまして、具体的にこの施行計画等の過程の中でその辺をはっきりさせていきたい、こう考えております。 ほかに。なければ、本件の質疑を終了いたします。 ４月２７日に用地説明会をするということでご報告させていただきましたけれども、予定通り４月２７日に実施いたしましたので、ご報告申し上げます。…","id":"exchange-021"},{"speaker":"上山委員","kind":"質問","question":"今これでまだ説明会は２７日ですから、例えば、買収の話ですよね。概略教えていただければ、わからないならわからないで構わないんですが、どんな感じなのか。","respondent":"中島街路事業担当課長","answer":"今のご質問は成立したということですか。","id":"exchange-022"},{"speaker":"上山委員","kind":"質問・要望","question":"そういうふうに出た場合、どんなふうに考えているのか、そこのところをちょっと教えていただきたい。","respondent":"中島街路事業担当課長","answer":"私ども、先般もご報告させていただきましたけれども、今年の３月１日から宅建の品川支部とあっせんの協力協定を結んです。そういった不動産業者の方と連携を密にしながら、うまく、いわゆる民民での売買可能な形にできればというふうに判断しております。","id":"exchange-023"},{"speaker":"沢田委員","kind":"質問","question":"２軒残って訴訟なんかになって、その辺の感触はどうなのかということと、再開発を希望する地区があるとおっしゃいましたよね。その問題で、買収を進めていくという問題は、どうとらえたらいいんか尋ねました。","respondent":"中島街路事業担当課長","answer":"先ほどこちらの補償の説明の最後のほうにあるんですけれども、私どもとすれば、あくまでも任意の契約ということを追求していきたい。実際に現場のほうに出ていって再開発の事業の説明だとか、趣旨をお話しして、ご理解を１軒１軒いただきながら話を進めていくという状況です。","id":"exchange-024"},{"speaker":"沢田委員","kind":"質問","question":"それから、再開発と街路事業としての用地買収というのは、再開発というのは、どっちかというと権利変換じゃないですか。どう処理を、とりあえず買いましょうみたいな形でやるのか、そこらがもう一つ見えないんですけど。","respondent":"中島街路事業担当課長","answer":"最初にちょっと再開発との関係ですけれども、私どもが道路用地として買収する蓄積といいますかね、そこは再開発の区域とは違うところです。","id":"exchange-025"},{"speaker":"辻委員","kind":"質問","question":"やっぱり新しく新築するというので、初めて隣近所とやり出したんだけど、公図に合わせてドーンとやってみたら違ったというようなことが出てくる。その辺の折衝なんていうのはまさしく課長のほうでやっていくんか尋ねました。","respondent":"中島街路事業担当課長","answer":"私どもが持っている資料とか、お互いが合意したところでもって線が引かれるという形でもって進めていきたいというふうに思っています。２ページ目にＡさんの土地とありますけど、お互いそれぞれが納得できる形で境界を決めていきたい、いければというふうに考えてあります。","id":"exchange-026"},{"speaker":"辻委員","kind":"質問","question":"背後にもあるわけですから、その辺を確定していくということになると、ちょっとやそっとの生半可な作業じゃないと思うんですね。背後地にも関係するわけですから、それじゃどうしようもないと思いますので、ぜひお願いしたいと思います。","respondent":"佐藤委員長、田村住宅課長","answer":"ほかに。ほかになければ、本件を終了いたします。 １、募集内容ですが、１４年６月の区民住宅（空き家）の入居予定者の登録募集です。区のお知らせにつきましては、５月２１日号の区のお知らせで、今回の対応についてお知らせすることになります。","id":"exchange-027"},{"speaker":"沢田委員","kind":"質問","question":"どういう委託をしたのかというのと、さっきの話だと、抽選もここに任せるんですか。ちょっとよく聞き取れなかったんで教えてほしいんですが。","respondent":"田村住宅課長","answer":"逆に、集中でありませんので、ぜひ地域の足元産業を生かした形で活用できないかという趣旨で今回品川都市整備公社と契約ということになりました。２点目のご質問の抽選等ですが、それについては区に残して、基本的には抽選等は区のほうでやるというふうになります。","id":"exchange-028"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、宅建管理センターに委託した委託内容というのは何と何なんか尋ねました。","respondent":"田村住宅課長","answer":"短期滞納者の対応、あるいは苦情があった場合の対応、そういうような苦情があったときの対応。それ以外のところ、委託先が違いますので、それは現在委託先が決まってその後の空き家についてはどうするか調整していきたいという形になっています。","id":"exchange-029"},{"speaker":"沢田委員","kind":"質問","question":"大手にという話がありましたよね。それとこれとの関係はどうなんか尋ねました。","respondent":"田村住宅課長","answer":"今後調整して検討していくという形になります。マテリアルの西品川一丁目の区民住宅も竣工が来年の１月ですけど、既存住宅とあわせて、先ほど申し上げた宅建管理センターに委託するです。","id":"exchange-030"},{"speaker":"築舘委員","kind":"質問・要望","question":"区民住宅であけなきゃいけない部屋というんですか、空き家の２０団地というのが多いのか少ないのか、その辺のことをお聞かせいただきたい。","respondent":"田村住宅課長","answer":"今回の事業に基づく……。","id":"exchange-031"},{"speaker":"辻委員","kind":"質問","question":"その場合、資格審査は区がやるの、それとも、委託先か尋ねました。","respondent":"田村住宅課長","answer":"やはり、入居決定そのものは区がやらなきゃだめ。先ほど自治法でやらなきゃならないとなっておりますので、最終的に区のほうでチェックして、抽選という形になります。","id":"exchange-032"},{"speaker":"沢田委員","kind":"質問","question":"区民住宅ができてから１０年たちますか。そうすると、早く建ったものの家賃は、古いは、家賃が高くなるはというんで、だんだん空きが大きくなる傾向はないか尋ねました。","respondent":"田村住宅課長","answer":"最初の設置当時から比べると、将来を考えると、募集しても現実になかなか当初１年になっても登録のない団地も徐々に出始めているということです。見て、何とかまだ空きの状況はありますけれども、何とか今の段階では埋めていけると思っています。","id":"exchange-033"},{"speaker":"沢田委員","kind":"質問","question":"1.６倍に２０年後にはなって、それなのにこっちのは確実に1.６倍まで、最初５％でやったのは。早晩空きが出てくることを、埋まらないということを想定しておかないとまずいんじゃないかなと思うんですけど、それはないんか尋ねました。","respondent":"田村住宅課長、山室住宅指導担当部長","answer":"それと、区民住宅の中では、最近ですと、平成１０年度以降ですと収入部位により異なるんですね。９年だとか、８年だとか、そういう課題が出てくるかな。 ですから、繰り返しになりますが、２０年たって、一般の民間の賃貸住宅市場に委ねられるわけですから、そこでの家賃設定に合わせる。基本的にその間、２０年たてば我々のほうの家賃補助といいますか…","id":"exchange-034"},{"speaker":"沢田委員","kind":"質問","question":"片一方で、１０年たつと３％として３割上がって、今後さらに３割それに上乗せ、近づいてくると、これはどこかでクロスするんじゃないか。そんなのはやっぱり制度としてはあり得ないことですから、どうも私は不安でしようがないんですけど、ここで言ってもしようがないですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/807981?Template=document&Id=3718#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":34167,"voices":135}},{"id":"h14-20020508-9","meetingId":"h14-cm05","date":"2002年5月8日","dateIso":"2002-05-08","committee":"文教委員会","time":"午後１時０３分～午後２時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"川西委員","kind":"質問","question":"ですから、一貫校の第二日野小学校が目指して、平成１８年開校のモデルとして、既存の小・中学校はすぐ一貫校にはならないですね。それで、多少は説明の中でおっしゃっていたけれども、平成１８年開校までの施設計画というのは、組織づくりはできているんか尋ねました。","respondent":"富田教育改革担当課長","answer":"果たすべき役割のところで、「他の学校にとってもモデルとなるような」というのを入れることについて検討をしてまいりたいと思います。当面、施設計画検討部会につきましては月１回程度、教育課程等検討部会は月２回程度ということで開催をしていく予定にしております。","id":"exchange-001"},{"speaker":"川西委員","kind":"質問","question":"もう１点、施設計画検討部会の庁内のスタッフというのはもう大体固まったんですか。何課がどういうふうに参加するか。","respondent":"富田教育改革担当課長","answer":"施設計画検討部会のメンバーですが、予定校の第二日野小学校長、教育課程検討部会と合同の部会を第１回目を開催したところです。","id":"exchange-002"},{"speaker":"川西委員","kind":"質問","question":"体育館の複合化とか、お考えが多少ありますよね。それは区も含めてのことだと思いますが、その辺はいかがか尋ねました。","respondent":"鷹倉庶務課長","answer":"それの外側にといいますか、体育館のほうの検討委員会というのを大きく立ち上げていきたい。施設計画検討部会とのパイプをつなぎながら、建物全体の形を形づくっていきたい、こういう考えを持ってあります。","id":"exchange-003"},{"speaker":"桜井委員","kind":"質問・要望","question":"小中一貫校検討準備委員会のメンバーの氏名をもう一度教えてほしいと求めました。最初に説明を求めました。","respondent":"富田教育改革担当課長、鷹倉庶務課長","answer":"小中一貫校準備委員会の委員ですが、９名です。公募区民として２名、東京学芸大学教授、あとは若月教育長です。 小中一貫校検討準備委員会とか部会があるわけですけれども、こう説明をしながら、途中経過の段階でも積極的に説明をしていく必要があるのではないか。こういった形で文教委員会に説明した後に、特にＰＴＡの役員だけでなくて…","id":"exchange-004"},{"speaker":"桜井委員","kind":"提案","question":"説明会のほうですけれども、こちらが説明していくということも大事ですけれども、ここに出ているだけでも８項目ですね。公聴会というところの設定をして、いろいろ広く意見を聞くということを提案したことがあるんですけれども、その辺についてはどうなんか尋ねました。","respondent":"鷹倉庶務課長","answer":"公聴会という部分については、今のところ考えてございません。いろいろお知らせする手だては考えていかなければいけないと考えていますけれども、今のところ委員ご提案のことについては考えてございません。","id":"exchange-005"},{"speaker":"桜井委員","kind":"質問","question":"それは何か理由があるんでしょうか。あるいはこういう点についてはどうだとかと聞くというのが基本だと思うんですけれども、公聴会を避けるというのはどういうことなんか尋ねました。","respondent":"鷹倉庶務課長","answer":"我々はシステムを説明しているとおり、話を聞くという形で、まさに聞く場を設けております。こういう姿勢ですから、聞かないということでは全然ないと、このようにご理解いただきたいと思います。","id":"exchange-006"},{"speaker":"桜井委員","kind":"質問","question":"そのことをすごく問題にしているんでしょうか。６歳で１年生に上がるということを問題にしているんか尋ねました。","respondent":"青木指導課長","answer":"教育に対する考え方の中でも、データ云々というようなことではなくて、現在の教育学の中でも一貫教育を求める考え方というのは強く出ております。そうした社会的な背景の捉え方というのが客観的な内容になっているかというふうに考えております。","id":"exchange-007"},{"speaker":"桜井委員","kind":"質問","question":"というのは、小中一貫というのは、基本的にはその学校だけですから、学校選択というのは、どこでもいいからというので自由でしょう。だから、私は小中一貫の言われる、親たちの願いとか、教師の願いの、何か具体的なデータがあるんですかという質問をしたんです。","respondent":"青木指導課長","answer":"そういう意味で、先ほどの連携については、そのように考えていただきたいと思います。私たちも校長を通してとか、ＰＴＡの方を通してとかというようなことでの一貫教育とか、連携教育についてのそうした声はいただいております。","id":"exchange-008"},{"speaker":"桜井委員","kind":"質問・要望","question":"拘束されないでやるということは、これは文部科学省の研究開発校だからなんですか。そこだけちょっと確認しておきたいんです。","respondent":"青木指導課長","answer":"ですから、１点目は、研究開発校になれば、そうした学習指導要領に対する特例が認められるということ。今もすでに、そういうようなことも含めまして学習指導要領を弾力的に考えていけるような方向で進めてまいりたいというふうに考えてあります。","id":"exchange-009"},{"speaker":"桜井委員","kind":"確認","question":"一つ忘れたんですけれども、まちづくりのことで確認だけしておきたいんですけれども、「この地域にまちづくりの全体像を示してほしい」とありますね。どこまで説明するかどうかは別としても、それはそれで説明されたならばいいですけれども、それだけ確認します。","respondent":"鷹倉庶務課長、青木指導課長","answer":"本来の、我々のつくる学校が、東五反田地区の中でどういうふうに占めるのかというお話をしたところです。これが東五反田地区のところの核的な役割を担えばいいな、担いたいなと、こういうような話をしたところです。 先ほどもお話しした、研究開発ということにおいてかなり自由にできるということが１点目にあります。他校においては、それにしましても弾力的な取り組みというのは今後検討していくことになるというふうに思います。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"確認","question":"先に確認的なところですけれども、今後の品川区内の展開としてどういうふうに考えていらっしゃるのかという点。先ほど小中連携校７校と言いましたが、どのように取り組まれて、その制度の進み方はどうなっているかという点を説明を求めました。","respondent":"鷹倉庶務課長、青木指導課長","answer":"説明会の開催の人数が少ない、プレス発表された中身をお知らせするですので、役員の方にお知らせしたいという形でお話し申し上げました。これから一般のＰＴＡの方については、内容が固まりつつある部分についてお知らせしたい… １点目の、小学校から中学校に接続がスムーズにいくようなカリキュラムの検討ということで、カリキュラム作成にも入っております。今までの考え方からいけば、これも一つの課題として今後検討してまいりたいと思います。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"一番最後のほうから確認させていただきたいんですけれども、その中でもうちょっと強く出せないのかなと感じるんです。研究の段階だから１科目だけかもしれませんけれども、せっかく連携でやっているんですから、もっと深く突っ込んでいけないのかなという感じがします。","respondent":"青木指導課長、富田教育改革担当課長","answer":"２点目の、それぞれの教科の中での連携というのは、研究するような形で私たちも指導をしてまいりたいと思います。それが近隣の学校への影響に対する教育委員会の支援ということにもなるかというふうに考えております。 今の３点目のご質問への指導課長のお答えの追加ですけれども、近隣校のさまざまな教育活動、特色づくりというものが展開されてくるかと思います。それぞれの方が自分に合った学校を選んでいくように…","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"普遍性をどう考えるのかを、選ばない方も当然出てくると思うので、そこら辺をよく考えておいていただきたいなという意識もあります。それは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"どうしても地域の学校がなくなる、地域の方たちの学校に対する思いがたくさんあるものですから、日野中学校ではなくなるわけですよね。でも、できた学校は小中一貫校ですからという中で、その辺をどう考えているのか。","respondent":"鷹倉庶務課長","answer":"それも説明をしながら、ご理解を得ていきたいなと考えています。こちらに移転するだけだという理解を懇切丁寧にしていきたなと考えています。","id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"そこから同窓会が始まっていくわけですから、今までの日野中学校の同窓会、第二日野小学校の同窓会そのものの居場所がなくなってしまいますよね。その辺の考え方は、小中一貫校準備委員会の中で検討の対象になるのかどうか、その辺をお聞きしたいと思います。","respondent":"指田教育次長","answer":"平成１８年４月１日になったからといって、日野中学校の今までの伝統の良さというものががらっと変わるということはゆめゆめ考えていません。新しいものができ上がってくるだろうというふうにお考えいただいたほうがごく自然の考え方でないかというふうに思いますが…","id":"exchange-015"},{"speaker":"松澤委員","kind":"質問","question":"そういう人たちはどういうところを根拠に、どういうところを居場所にしているのかなと思ったものですから、今度小中一貫校につくる。ということなんです。","respondent":"指田教育次長","answer":"決してそういうふうな居場所的なものをつくらないという考え方は全く持っておりません。学校の安全はもちろん配慮いたしますけれども、そういうふうな居場所的なものというものは十分心していきたい、このように考えております。","id":"exchange-016"},{"speaker":"高星委員","kind":"質問","question":"全体を通じてどういうイメージを持つのか、一人ずつにご理解をいただいているという中身でないんだろうというふうに思うんだけれども、その辺をまずお聞きしたいと思います。","respondent":"鷹倉庶務課長","answer":"しかし、我々とすれば、こういう検討組織を経て、あるいは教育委員会、議会等に報告する中でお話ししていくのが筋だと。検討をこういう形でしていくのが筋だと考えていますし、それを地域に入っていく、これしか我々はできないんじゃないか。","id":"exchange-017"},{"speaker":"高星委員","kind":"質問・要望","question":"そのことだけは確認させてもらうというか、どういうふうにやっていくかということを、もう一度そのところをきちっと話をお聞きしたい。保護者も含めて、こうするということを求めていくということだけ、確認したいと思います。","respondent":"指田教育次長","answer":"２月９日から４月１６日までの説明会というのは、小中一貫校のプレス発表資料の域までしか出ていない中での説明でございましたので、我々としても。特に有楽街などについてのご不信的なものというものがあれば、説明を精いっぱいやらさせていただきたい、このように考えておりま…","id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"あそこに行きなさいというわけではないんですから、中学校のときに中学校を選択していただければいいのであって、それは全く誤解ではないんですか。そういう点はどうなんか尋ねました。","respondent":"指田教育次長","answer":"今、第三日野小学校にいる子どもが第二日野小学校に行きたくなければ、それは別段選択する必要はないというのが前提になっております。そういうふうな形できちっと対応はしていきます、選択制は別にしても、そういう形でやっていきますよという意味合いでのご説明ですので。","id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"質問","question":"質問のところには、「文教施設を設置することで、これがまちづくりの核となっていってほしいと考えている」と書かれてありますけれども。二つお伺いします。","respondent":"鷹倉庶務課長、青木指導課長","answer":"やはり我々は、説明会に行ったときも、どちらかというと、ニュートラルな発言を心がけるようにしております。こういうことを願っておられると思いますし、私たちもそれにお応えできるのではないか、そのように考えてあります。 指導法の研究が今まで別々で行っていた小中連携教育の学校や、そうした意味での成果を生かして改善を進めていくというふうに考えております。一貫校の成果の分け方といいますか…","id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問","question":"運動の施設はどうなるのかなという、ともにまちづくりを進めていってほしいなと思うんので、その点。こういうところで意見がどう反映されるのかなというところで、ＯＢの意見を聞く工夫ということをどう考えていらっしゃるのかお伺いしたいと思います。","respondent":"鷹倉庶務課長、青木指導課長","answer":"１点目の、学校づくりの進め方という形でのお話かと思います。品川区全体をとってみても、建物が高くなってきている中でどういうふうにつくっていくのか、こういうふうに考えているところです。 要するに、子どもにいろいろ相談をして、子どもが先生方に相談をする。教師のほうも子どもの声に耳を傾けていくという、やはり子どもの声を十分に聞くという体制はできていくのではないかなというふうに考えております。","id":"exchange-021"},{"speaker":"桜井委員","kind":"意見","question":"小中一貫校準備委員会で検討する課題の案の中に、「実現に向けて考えられる課題」とありますね。教育課程、施設計画、学校経営、その他とありますけれども、もう一度整理して言っていただけますかとの意見を述べました。","respondent":"富田教育改革担当課長","answer":"課題検討を進めていく中で、準備委員会の委員の中から出てきた課題がございましたらば、その辺も加えながら検討をしてまいりたい。プラン２１の推進委員会のほうに上げていくというような構成で考えているところです。","id":"exchange-022"},{"speaker":"桜井委員","kind":"質問","question":"中学校各学年四クラスとか、募集というのはどういうふうにするかという、これは大変なことではないですよね。小・中学校はどういう目的を持って、どういう学校をつくっていくのかという、そうではないんか尋ねました。","respondent":"富田教育改革担当課長、藤田委員長、上川内生涯学習課長","answer":"個別の検討課題ということでございまして、それぞれの課題検討の前提といたしまして、準備委員会の場で課題検討の前提として検討をしている最中です。 ほかにございませんでしたら、以上で、本件を終了いたします。 続きまして、報告事項の２番、平成１４年度情報通信技術（ＩＴ）講習事業の実施について、ご説明をお願いします。 予定回数２０回。補正予算を計上する予定ですが、６月３日から実施する予定ですので、当面規定予算の範囲内で実施するです。","id":"exchange-023"},{"speaker":"山路委員","kind":"質問・要望","question":"それに関連して品川区はどういうふうな支援をしていくのか、その辺も決まっていたら教えていただきたい。こういう時代ですから、そういう形のものを利用していただいたらと思うんですが、その２点をお聞きいたします。","respondent":"上川内生涯学習課長","answer":"個別の、このほかにも心障会館のほうでもともとの計画があったようですので、そういう対応をしているという話は伺っております。地元の本屋から、前回もそうでしたように、今回もそのような形で入れることになっております。","id":"exchange-024"},{"speaker":"山路委員","kind":"質問","question":"もう１点は、クラスを変えてやるという計画がありますね。それはどういう形でやるんか尋ねました。","respondent":"上川内生涯学習課長","answer":"平成１３年度の延長事業なので、平成１３年度と同じもので、レベルアップ分ではないんです。平成１４年度新たに組まれていると思いますが、通常の講座の中で、ほかの講座と同じような形で入れてはあります。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の関連でお聞きしたかったんですけれども、レベルアップ講座を、前回の委員会で説明があったと思うんですが、これとはまた別個だということは分かりますけれども、そちらに対してはどのような形をとっているのか、もう一度お願いいたします。","respondent":"上川内生涯学習課長","answer":"平成１４年度はレベルアップ講座を一講座入れておりまして、もう少し上級の、レベルアップ分の学習もしていく講座を組んでおります。〔「いつですか」と呼ぶ者あり〕秋頃です。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"秋で、まだ決まっていないという状況かもしれないですけれども、もう少しレベルアップも予算を組めないのかなと。あまり強調したところは言わないですけれども、一講座というのは少ないんじゃないかなという思いでお聞きしました。","respondent":"上川内生涯学習課長","answer":"４００人分の講座を、平成１３年度の基礎講座を引き継いで復習の講座として設けました。いつやるかという細かいことはまだです。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"確認","question":"確認ですけれども、２０人で２０回、４００人は受けられるということか尋ねました。","respondent":"上川内生涯学習課長","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"高星委員","kind":"意見","question":"３０回ということで、平成１３年度と同様の内容ということですが、随分金をかけてやるのかなと思ったら、「違うんですよ。規模は５００人ですよ」という話で、講習の内容が、成人（２０歳以上の都民）になっているけれども、その辺はどういう内容なのかとの意見を述べました。","respondent":"上川内生涯学習課長","answer":"それを１,０００円のテキストでという話は、そこまでの話なんです。その後に、ほかに講座、レベルアップとか、基礎よりも違う種類のパソコンの講座はないのですかということで、次のお話をしたわけです。","id":"exchange-029"},{"speaker":"飯沼副委員長","kind":"意見","question":"議会の役割の重要性と、議員の力量がすごく問われると痛感をした１年でありました。どうもありがとうございましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/547087?Template=document&Id=4436#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":34724,"voices":86}},{"id":"h14-20020508-5","meetingId":"h14-cm05","date":"2002年5月8日","dateIso":"2002-05-08","committee":"総務委員会","time":"午後１時０５分～午後２時５２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"の財団法人品川文化振興事業団の財産運用","agenda":"の財団法人品川文化振興事業団の財産運用","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"安全性と効率を同時に求められてきたが、今後は安全性の確認を最優先し、効率性も求めるというような。そこら辺の見解というか、どういうふうに変わるのか、まずお聞きしたい。","respondent":"中尾根企画部長","answer":"私がご説明しました区に準じたというところは、第２条の中の金融機関等の情勢分析だとか社会経済状況をよく適確にとらえなさい、それとは違います。財団を財団として今委員のほうから言いましたように、まず安全性を重視をし、その点については誤解のないようにお願いします。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そこで今までの、例えば前回の品川区の公金管理運用の方針、ここで言いますと、今までは安全性と効率を同時に求める。前提が安全確実という品川区の公金管理運用方針とはちょっと考え方が違うというふうに思うんですけれども、どうか尋ねました。","respondent":"中尾根企画部長","answer":"したがいまして、運用益がなくてもいいんだという、そういう運用はもともと考えておりません。今回少なくとも品川文化振興事業団についてはそういう運用方針はとらないということで、ここは大きな変更点です。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと私が聞いたのは、品川区の公金管理運用方針の考え方と、この品川文化振興事業団の資産管理運用規程、ここのところの考え方というのはちょっと違うんじゃないですかということを聞いているんです。","respondent":"中尾根企画部長","answer":"そういうさまざまな広い視点からでの財産の考え方、運用の考え方というもの、それは財団固有のものです。それは何回もそのようにご説明しているつもりですので、よろしくお願いします。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"意見","question":"私が言っているのは、一番の反省点がここにどういうふうに生かされているかというところが、やっぱり問題だと思うんですね。前提が確実ですという言葉にならないでしょうということを言っているわけですとの意見を述べました。","respondent":"濱野助役","answer":"図にしますと、Ａという丸とＢという丸が重なっている部分がＡかつＢです。したがって、安全かつ確実なんです。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"私はそれは当然だと思うんですよ。私はそのことを言っているんじゃなくて、考え方が違うんじゃないですかと。","respondent":"濱野助役","answer":"考え方は同じ。ＡかつＢは、Ａでなければならないし、ということは当然含まれていることだということをご理解いただきたいと思います。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"意見","question":"なんだけれども、これは規程ということになると、この文言で、表現でちょっと不十分だ。ちゃんと文言のところもきちっと安全、確実がまず大前提という表現にしておく必要があるというふうに意見で言っておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"規程のほうの１ページの第５条の１の「ただし」というところから、理事会を開催する暇がないとき」、こういう書き方って。だけど、決め事にこういう表現はあるんか尋ねました。","respondent":"中尾根企画部長","answer":"私どもは、ほかのところの参考等もしていますので、こういう表現をとられてあります。暇がないときに専決処分する、こういう表現です。","id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問","question":"じゃあ、文言としては例えばどういうことですか。専従じゃないからこういうことが起きるということなんか尋ねました。","respondent":"中尾根企画部長","answer":"今日はまだ報告しませんでしたけれども、そういうことを考えまして、いろいろ突発的なことは考えられる。これは規程としてはそういう規程の仕方をするということです。","id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問","question":"こういうふうに抜け道をつくっておくと、理事会は年２回でいい。だから僕は理事会の機能をもう少し持たすほうがいいような気がするんだけど、そうじゃないか尋ねました。","respondent":"濱野助役","answer":"したがって、寄附行為そのものを変えることはできないんでしょうかということを東京都の間でしました。東京都と、実態に合わせた資金運用をする場合の許容される文言としてはこういうものだったということで、ご理解いただきたい。","id":"exchange-009"},{"speaker":"林（宏）委員","kind":"質問","question":"個々の人は能力があり、１人の判断でどうしても突っ走っちゃうときって、これに限らずいろんなところであるんじゃないですか。その辺はやっぱりきちんと今回のミスを繰り返さないような体制というか、運営をやっていくべきだと思います。","respondent":"濱野助役","answer":"今、林委員が言われたことを規制しようということで、こういう規程をつくりましたので、そのご意見については十分に体して運用していくということをやってまいります。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"理事会の開会を求めるときのある種の内規みたいなものを考えておかなきゃいけないと思うんですけれども。向こうさんの言うものが見えてくるのかどうかちょっと教えてほしいんですけれども。","respondent":"濱野助役","answer":"たまたま今回保有しているものが比較的長期のものですから、今のところ、その満期が来るまで理事会を開く予定はありません。ただ、この債券に何かの異変があれば、当然それをつけかえる必要が出てくれば、理事会を開いて対応していく必要があるということです。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"こう判断すべきだなというふうに自然にそういう文化ができてくる、要は善意の団体でできていて、もうそうではないわけです。事故に遭うのは当たり前という時代に入ってきたわけですから、そういうことを踏まえて、これは要望を伝えておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"三上委員","kind":"質問・要望","question":"先ほど一応４億円と１億円とかという、基本財産というのはこのすべての財産の中の何割とか、そういう決め方というのはあるんでしょうか。私はこう思ったんですけれども、そこらあたりのご意見を聞かせてください。","respondent":"濱野助役","answer":"今後またそれぞれの理事の任期満了の機会には、承ったような意見を踏まえて対応していきたいと考えています。たしか変更することはできませんので、そういう性質の財産ですので、その点のことは確実だです。","id":"exchange-013"},{"speaker":"三上委員","kind":"質問・要望","question":"そういう意味で、私も考えた話をちょっとしたまでであって、そういう基本財産の割合的な部分が動かせない、それはそれで結構だと思います。これは外部の方が知ろうとしても十分知れるような形の表現というものを使って、ある意味では公表していっていただきたい、こうお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"林（宏）委員","kind":"確認","question":"ちょっと一つだけ確認させてくれますか。この一言だけ読むと、すべて理事長の判断が要るというふうにとれるんだけれども、そう理解していいか尋ねました。","respondent":"中尾根企画部長","answer":"ただ、最後の責任はやっぱり理事長であるのは、もうこれは間違いのないことです。そういうことです。","id":"exchange-015"},{"speaker":"中島委員","kind":"質問","question":"直近というのは、先ほど年に２回ではないと言いながらも、ちょっと期間があってもそれは直近の理事会だというふうにとられてしまう。ですから、考えというか、ただちに理事会を開催するという義務づけを私はここに入れておいたほうがいいんじゃないかなと思うんですけれども。","respondent":"中尾根企画部長","answer":"監督官庁に、もしここを４回にしろということになるとオーケーをとらなくちゃいけないので、今の中ではどうしてもできていません。定款上は２回ということになっていますが、そのように持っていきたいという意向を示されたんですので、そのようにご理解いただきたいと思います。","id":"exchange-016"},{"speaker":"北野委員","kind":"質問","question":"ちょっと細かいことでお伺いしたいんですが、運用指針の部分で、理事長や理事の皆さんは専従じゃないですよね。それで、こういうことの情報把握とか、帳簿とか、常に管理するという方は、常駐として品川文化振興事業団の中でいらっしゃるのか尋ねました。","respondent":"中尾根企画部長","answer":"情報の提供そのものについては、財団自身がどのように外部からの情報を得ていくのかという問題はありますので、そこは財団の考え方があります。ないしは基本財産を出している区でありますから、そういう関係で持っていきたい、そういう具体的な運用を考えているです。","id":"exchange-017"},{"speaker":"北野委員","kind":"質問","question":"理事長には月１回いろいろな帳簿の面から報告はされますけれども、理事会の年２回だけになるのか、定期的に情報として資料が送られるのか。そういうところをちょっとお伺いしたいんです。","respondent":"濱野助役","answer":"次に何か理事会にかけて変更するまでは、当然変更するということを実態上考えていませんので、その点については考えておりません。ただ、何年か先まで変更する予定はありませんので、そういう意味では毎月毎月お送りする必要はないのかなというふうには考えております。","id":"exchange-018"},{"speaker":"北野委員","kind":"質問・要望","question":"いろいろ理事長には報告されるけれども、やはりほかの理事の方にどこまでの情報公開がされるのかなというのが一つあると思うんですね。ある程度のそういう形にされて、そういうところでは、やはり新たにつくった運用規程をしっかり有意義な形で実践していただきたいなと思います。","respondent":"中尾根企画部長","answer":"今、委員のほうからの意見につきましては、これは定款上で雑則というのが最後についていまして、ここで備えつけるべき帳簿等が載っております。いつでも提供するという、その点については、情報等については過不足なく十分理事のほうにも提供できるというふうに考えております。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"確認","question":"(3)の都市計画決定の手続は、江東区が行うことで再確認というふうに書かれているんだけれども、やるということですか。それとも確認をしたということなんか尋ねました。","respondent":"小野（孝）政策担当課長、中尾根企画部長","answer":"江東区が都市計画決定の手続を進めるということについては、１月１７日の区長会の中で確認をされております。それで、今回その件についても部長会の中でやるということで確認をしておりますので… 前提が崩れたら話し合いができないじゃないかということになる。そのニュアンスのところだけ、ちょっとお酌み取りいただければと思います。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"これが今年中に都市計画決定されなかったら、一部事務組合の附則の１７年度末というのは完全に消えるんです。その帰属はちょっと時間がかかっても別だけれども、施設建設については、非常に逼迫した時期に来ているというのを認識しておいていただきたい。","respondent":"中尾根企画部長","answer":"善意に考えれば、そこのところの１点、やっぱり一番大きい論点はそこのところが一つあります。認識は、そういうことに使ってはならないはずだ、そういうふうには主張しております。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"どういうふうに決着に集めるかというのはあると思いますけれども、２３区合併論、再分割論みたいなものもあるわけですよね。このまま行くと、領土が来るという可能性は薄いわけですから、そういうもっとフレキシブルな考え方もとれるのかどうかということを聞きたいんですが。","respondent":"中尾根企画部長","answer":"今委員がおっしゃったようなことは、実は品川区としてどう主張するかという点のときの検討の材料でもありましたし、検討もしてはきております。おかしいと思うこと、そういう中で…","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"地方公共団体がどういう状況に統制されるか詳しくないのでわかりませんけれども、ある意味ではペンディングのままで、考えられないわけじゃないです。これは必ず灰溶融炉の方に属していなきゃいけないという縛りがほんとうにきついのかどうかというようなことだって考えられるわけですから、大田区だ。","respondent":"中尾根企画部長","answer":"意見だけと言いましたけれども、そういったことに十分配慮して今後検討しろということが議会の総意の意見ということであれば。大所高所からのそういうことについては私もいろいろ検討もしておりますし、そういう背景がありますので、その点だけ。","id":"exchange-023"},{"speaker":"三上委員","kind":"質問・要望","question":"そういう情報があった場合には、向こうがこうだったらば、こっちもそれで対抗するぐらいのものをやっぱり今後やっていくことも必要かなと。ちょっと。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"林（宏）委員","kind":"意見","question":"モニターの方々の品川区に住んでいる年数とか、そういう情報等はつかんでいらっしゃいますか。例えば昨年度のモニターの人たちが品川区にどのくらい住んでいるだとか、そういうような在籍というのかな、そういうものはわかりますかとの意見を述べました。","respondent":"山田広報広聴課長","answer":"実を言いますと、そちらの年数について入れてあるんですけれども、今回の資料の中ではお出しできておりませんけれども、応募していただく段階で在住何年というところを記入をしていただく欄がありますので、把握はしています。","id":"exchange-025"},{"speaker":"林（宏）委員","kind":"意見","question":"ちなみに平均で何年ぐらいで、古い人は何十年という人はいる、例えば比較的新しい人だと１年とか２年とかいう人がいらっしゃるのかどうか、その辺、簡単でいいですけれどもとの意見を述べました。","respondent":"山田広報広聴課長","answer":"退職をして、やっぱり品川区をもう１回見つめ直したい、平均すると大体４０年近い年数が出てくるというふうに考えております。若いモニターからは、いわゆる退職をなさってから改めて地域を見直すというような形での参加が多くなるという傾向かなというふうに思っております。","id":"exchange-026"},{"speaker":"林（宏）委員","kind":"意見","question":"それから、自主的にそういういろいろなところに参加をしてくれる。品川区のそういうサービスというか、そういう人たちとモニターの人たちとのつながりというのはどういうところに、何かありますかとの意見を述べました。","respondent":"山田広報広聴課長","answer":"お子さんを生んでみて、初めて自分がいろいろなサービスを受ける段階になってみて、少し今フリーであるからやりたいと。いつも託児をやっているんですけれども、そういう方々が初めて区政にかかわってくるというような感じの、ある意味では二極分化しているのかなです。","id":"exchange-027"},{"speaker":"林（宏）委員","kind":"質問","question":"品川区としては、こういうところに関心を持ってくれる人がある意味では大事な人的財産だと思うんですよね。そういう人たちを原則として１年でかわっていかれるということだから、散らばってもらって、いろんなかかわってもらうということは考えないんか尋ねました。","respondent":"山田広報広聴課長","answer":"ただ、現実的には１年やってみて、それを継続してできないかというのが昨年の離任式のときにお話がありました。一定のここの部分として参加していただくところを十分に生かしていくところが今私のほうの課題かなというふうに思っております。","id":"exchange-028"},{"speaker":"林（宏）委員","kind":"質問","question":"そういうものに関心を持っている人たちですから、お忙しいでしょうけれども、広報広聴のこういう仕事を通してやっていただければ。関心の高い人だから、ぜひそういうことで、街の中に出てきてほしいなというふうに思うので、ひとつ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"北野委員","kind":"質問","question":"モニターのＥメールのほうなんですけれども、お願いするものというのは、Ｅメールの方もモニターの方も同じようなことをお願いするんでしょうか。まだ、ホームページについて聞いてもらいたいんですけれども。","respondent":"山田広報広聴課長","answer":"全く知らない方が５名ということで、いわゆるアンケート形式をとりながら、Ｅメールモニターについては生かしています。どこが見やすいか、見にくいかというのを見ていらっしゃるわけなので、その辺は私どもはご意見として参考にさせていただいているところです。","id":"exchange-030"},{"speaker":"北野委員","kind":"質問・要望","question":"区政モニターの結果としてではなく、やはりこういうように利用勝手がよくなったよというような情報はどのような返され方をしているんでしょうか。窓口に行かなくてはわからないとかというのではなく、やはりきちんとした情報が提供されると今後いいと思うんですけれども。","respondent":"山田広報広聴課長、本多委員長、西島経理課長","answer":"これは出産一時保育という制度ですから、そこが変更になるわけですので、その辺の変更については塗り直しということで。いろんな意見もいただいて… 本件を終了いたします。 入札予定価格の事前公表につきましては、平成１０年１２月から３,０００万円以上の建設工事について実施をしてまいったところです。実施期日ですけれども…","id":"exchange-031"},{"speaker":"林（宏）委員","kind":"確認","question":"ちょっと確認だけ。試行がされていて、高どまりではなかったよということなんだけれども、ちなみに、パーセントを説明を求めました。","respondent":"西島経理課長","answer":"１２年、１３年の平均落札率が９６.０％で０.３％ほど増えていますけれども、おおむね同じ水準で推移したかなというふうに思っております。正直なところ、所管課としては思ってありますが…","id":"exchange-032"},{"speaker":"林（宏）委員","kind":"意見","question":"できれば９２％、９３％ぐらいのパーセンテージに行ってほしいなというのが、予定の価格に対してなんだから。１,０００万円まで下げてどういう数字がまた出てくるかというのもありますので、そのときにまた聞かせてくださいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"塚本委員","kind":"意見","question":"各区が事前公表をどの程度導入しているのかということと、今のパーセンテージ、他区がもっと低くなっているよという、制度がみんな同じかどうかわかりませんので難しいところですけれども、そういう声が聞こえてくるんですが、その辺のところはとの意見を述べました。","respondent":"西島経理課長","answer":"品川区が一番先に事前公表を開始いたしまして、始めたときは他区は事後公表でしたので、それが現在見ますと１１区が事前公表に移ってきております。９７.９％、９８.６％とかという区もありますので、それを考慮してのことだというふうにご理解いただければと思います。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201900?Template=document&Id=1578#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":34558,"voices":82}},{"id":"h14-20020515-13","meetingId":"h14-cm05","date":"2002年5月15日","dateIso":"2002-05-15","committee":"清掃・リサイクル特別委員会","time":"午後１時０９分～午後３時２７分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須藤委員","kind":"意見","question":"このリサイクル率というのが仮の定義という説明で、これはどのあたりまで使われているのか、品川区だけの考え方か、一般に他の自治体でもこういう数値でカウントすることができるのかどうかとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"今回、これを分母に加えるのかどうかでもちょっと考えたんですが、この辺を品川区の分はどうなっているかというのはなかなか把握しにくい。可燃、どれぐらい出されたものからリサイクルされているかというものを客観的にやるために私どもで考えたということで…","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"そこを伺いたいんです。店頭回収も含めて、そういう点で微増ではあっても増えているここのところをどうとらえたらいいのかなという、見解をちょっと伺いたいと思います。","respondent":"中山清掃リサイクル課長","answer":"区としてもそういう認識を持っておったところですが、基本的にはリサイクル１番ではなくて、順位として下がってきている。いずれにしても、総廃棄物を抑制する方向が望ましいという認識は持ってあります。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"それからちょっと委員長にお願いしたいと思うんですけれども、これからやっぱり求められていくテーマだというふうに思うんですよね。今回はできなかったわけですから、ちょっとそのことを思っておりますので、委員長にもしご見解等があったらお聞かせいただきたいと思っています。","respondent":"中山清掃リサイクル課長","answer":"いろんな広報でも例示をしたり、それから区民の方からいただいたアイデアというようなものを紹介するようなことをやっていきたいとは思っております。事業者、２３区で一体であったり…","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"これと比較して、私がちょっと質問したかったところもはっきり受け取れないのかなと思うので、もしわかったら説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"実は、区内のほんとうの事業系のごみはどうなっているかが明確に把握できないというのが一つの区の清掃事業の課題だという認識は持っております。２３区の中で今考えておるところなんですけれども、そういう持ち込みごみの増傾向は確かに増えてあります。","id":"exchange-004"},{"speaker":"北野委員","kind":"質問","question":"２３区全体の量的な割合になってしまうと思うんですけれども、不燃ごみの中から資源ですとかそれぞれの量というんですか、大体２３区全体で。そういう割合というのは出ているんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"そのほか、瓶も機械的に色によって選別できるようになっていますから、これもリサイクルに回るようにやっております。ちょっと量は申しわけございません、別途お示ししたいと思います。","id":"exchange-005"},{"speaker":"北野委員","kind":"質問","question":"ほんとうにもっとリサイクルを進めるというんですか、という三つのＲしかなくて、そういうものはもう公にあるんですよ。もう一つの四つもあるんですよということをどこかで知らせていくべきじゃないかなと思うんですけれども、そういう考えはいかがか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"まだ行政の中では、これは確固たるものとしてリフューズということは言っていない。具体的な取り組みの中で、この辺は広報のありようの中で、例示しながら周知していきたいと思います。","id":"exchange-006"},{"speaker":"北野委員","kind":"意見","question":"いつも四つ目のＲということで、この中で発言させていただいていますけれども、ほんとうにそれが行政もそうですし、私たち自身も考えていかなくちゃいけないことだというのは重々わかっていますので、ぜひよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その中で、そういう資源回収のものが実際にどれくらい回収されているかという回収率みたいなものは区としては出せるんでしょうか。どれくらいまでが回収されているという、そういう新聞であれば、どれくらいの中で何％ぐらいまで回収されているというのはわかるのかどうか。","respondent":"中山清掃リサイクル課長","answer":"いろいろと今検討している中で、そういうシミュレーション、どれぐらいと思われるという幾つかの数値を検討したことはあります。ただ、もちろんこれは１％でも上げ、ごみにしないのが原則だという認識は持っております。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"去年、そういうところに、あそこのところはすごい徹底したごみの分別をやっていたというふうなのがすごい参考になったなというふうに思うんです。製造者責任というふうなところも自治体としても求めていくというふうなところをはっきりと打ち出しているというふうなのが印象的だったんですけれど…","respondent":"中山清掃リサイクル課長","answer":"この辺は２３区の中でやはり議論かなと思っておりまして、当然そういう認識は持ってありますが、品川区の着地点を考えていきたいと考えています。品目については、そういった意味で検討は、今後どういうことができるかということは考えてまいります。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひそれは検討していただいて、ごみを減らすというふうなところで前進させていただきたいというふうに思います。１人当たりのごみの量ということで、この８００グラムの中なんですけれども、どういう状況なのかをお聞かせいただきたいんですけれども。","respondent":"中山清掃リサイクル課長","answer":"区で収集しているものからしか把握ができませんものですから、基本的には家庭系のものだというふうにお考えいただいて結構です。そういうものはありますが、基本的にはこれは１家庭当たり、お年寄りからお子さんまで全部加えたものというふうにお考えいただければと思います。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、家庭と小規模の事業者の合計を人口で割ったというようなことでとらえていいかと思うんですね。そうすると、それが８００グラムということで、あとは事業系としてはどれぐらいかというのは数字として出ているんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"例えば２３区の人口割でやれば出せるかと思いますが、ちょっと計算することの意味合いが、これは地域によって全然違いますから。その辺の意味合いもあるので、とりあえず家庭でとっていくのが基本というように私どもは思ってあります。","id":"exchange-011"},{"speaker":"堺委員","kind":"質問","question":"２番目の資源の回収量の中の拠点の回収等については年々回収量が減っていますが、こういう理解ですか。この辺の関連を参考までに教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"これもちょっと拠点回収等の等のところに幾つかあるということが説明が抜けておるんですが、空き瓶ポストというものを従来設置しておりまして、あるいは八潮地区等に設置しておったんですが。","id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"その背景を品川区段階の問題だけでなくて、全体的にそういうことで計算もしてきたよという、そういうことなんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"従来、東京都清掃局で一体的に実施しているときから、例えばいわゆる広報紙的なものにも示しておりました。これは２３区の中で、実施自体がコストも含めて各区の執行になりますから、集約するのに約１年トータルでかかってきたという経過です。","id":"exchange-013"},{"speaker":"土井委員","kind":"質問・要望","question":"それも個別の車を使って別なルートで集めるというようなやり方ですから、コストが当然かかっているだろうと思えますね。当然それらも含めてこれは２３区ですから平均値という形で出てきたんだと、トータルの形で出てきたんだろうな、こういうふうに理解しました。","respondent":"中山清掃リサイクル課長、松本環境清掃事業部長","answer":"今回のコスト計算は、基本的にその歳出ベース、ただし、そこに歳入が入るようなもの、例えば清掃工場の運営で持ち込みの手数料が入ってまいります。… 投資的経費のうち、減価償却と利子、これについては別途算定の形で入っています。土地については、これは控除をしています。","id":"exchange-014"},{"speaker":"土井委員","kind":"意見","question":"要するに、先に工場を建てるということは、これから使っていくのに建てるわけですね。その年にだけどかーんと経費が乗っかっちゃうというスタイルになるわけでして、今の状態がそうなっているということで理解してよろしいんですねとの意見を述べました。","respondent":"松本環境清掃事業部長","answer":"別途算入するというのは、年割に減価償却がきちんと計算をし直して、その年に算入をさせていただこうと。ですから、いわゆる民間と同じような減価償却の計算方法を用いて、実際のコストを策定をしているです。","id":"exchange-015"},{"speaker":"土井委員","kind":"質問・要望","question":"そういう中で、それから、それに新しい工場をどこにどう建てるのかという問題がまだ若干残っている部分もこれはありというふうに思うわけですね。これからいろんな分析等も進めていただきたいな、あるいは啓蒙等を進めていただきたいな、こんなふうに思って発言をさせていただきました。","respondent":"中山清掃リサイクル課長","answer":"例えば新しい工場の建設等がまた平成１３年度等出てきますと、より効率的な収集、運搬体制というものを事務所と連携をとってつくっていきたいと考えています。","id":"exchange-016"},{"speaker":"須藤委員","kind":"質問","question":"単純なあれで。処理経費、ごみが少なくなってきているんだけれども、トータルとすると少し上がっていますよということはどういうことなんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"いわゆる清掃工場とかが典型ですが、設備的なもの、簡単に量が減ったから比例して減らせられないものもあります。し尿は、冒頭申し上げたように、逆に処理量の減を経費の減が上回ったために単価が落ちたです。","id":"exchange-017"},{"speaker":"須藤委員","kind":"意見","question":"これはもう落とし切れないことなのかどうなのかということです。こっちは落っこってきて、それでごみ量の減ったぐあいに対して落ちてこないということは、何なんだろうと言っているとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"今後もう１回来年度も同様の資料をつくっていくことになるかと思うんですが、この分のコストというものが純増で処理処分経費に入ってまいります。というのは、施設ができているものですから、完全にその施設を廃止できないとかということがあると、時差で上がるときがある。","id":"exchange-018"},{"speaker":"須藤委員","kind":"意見","question":"これはあくまでも２３区の平均だけを見て、一つの参考だよというふうに見ておくだけだね。そう理解していいねとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"北野委員","kind":"提案","question":"これは個人的な資料、委員会に出せる資料でもあり、何か品川区としてはどうなんでしょうか。見れば、リサイクルよというのはわかるんですけれども、単価については、やっぱり出すべきじゃないかなと思うんですけれどもとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"ペットボトルに至っては１キロ２１３円かかっていますと、また場面を見て当委員会等でもこういった品目ごとの単価というものは出していきたい。そういう形で、各区の中で…","id":"exchange-020"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"さっきの須藤委員のほうの話の続きになってしまうんですが、この資料をつくったのは、清掃一部事務組合のどこでつくっている資料の一部なんか尋ねました。","respondent":"松本環境清掃事業部長","answer":"清掃協議会のほうで作成をしたものです。","id":"exchange-021"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"その逆の意味で、収集運搬事業が変わっているはずなのに、これが上がっているのでは何かおかしな資料になってしまう。ですから、収集運搬したことにこれだけコストが下がったというのを出すのが区としての考え方じゃないかなと思うんですけれども、どうか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"１２年を、こういう考え方にとりますと、収集運搬経費は単価として２,０００円以上落ちるという計算になります。したがって、収集運搬については２３区に移って相当経費は落ちているということになります。","id":"exchange-022"},{"speaker":"土井委員","kind":"質問・要望","question":"なぜこういうものが選ばれたのか、そこら辺について、わかることがあったらお聞かせをいただきたいというふうに思います。だから、その辺の発想が、だれがどんな形でいつやってこう決まったのというところを少しとりあえず聞かせていただきたい。","respondent":"中山清掃リサイクル課長、松本環境清掃事業部長","answer":"入れかえであるということを踏まえてストーカ炉であるという形になったというふうに認識していますが、その２番目に、そういった中では。これはまた区民の方の収集の現場との問題、意思の問題という部分にもかかわってまいりますけれど… 協議会、あるいは組合議会に諮って決めていった、こういうことです。それから、プラスチックですけれども、基本的に、現在の性能基準から言えば、混焼については何ら支障はございません。","id":"exchange-023"},{"speaker":"土井委員","kind":"質問","question":"新しくプラントが更新をされるということですから、これがほんとうに生ごみばっかりになったときにはどうするんだということもあり得るわけですね。これは前の説明の中で経緯を含めてこの程度というスタイルに決まったということを伺っていますので、特段問題ないんだろうと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"１点だけ伺います。この改修は３４０億ぐらい見込んでいたと思うんですけれども、これは今の状況、時点で金額的な変更はどのくらいか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"実施計画の中では、一切コスト的なものは、この資料にありますように示されておりません。この中では、最低入札価格等をもちろん示していくと思うんですけれども、あえてそこの実施計画でコストを変えるということは示されておりませんので。","id":"exchange-025"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"別はわかったんですけれども、契約自体は品川区ではないということにはなっているんですけれども、金額的なものとか、この実施計画、何かこれから品川区として物申すことができるのかどうか、その辺の状況はどうなんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"今いろいろと地域処理の検討等しておるわけですが、これは清掃一部事務組合は当然認識していることかと思いますけれども、適切な申し入れはしていきたいと考えています。","id":"exchange-026"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"重ねて申しわけないんですが、やっぱり品川区として、これはもう区の施設になっていくわけですから、いいものをつくってもらって負担を軽くするという考え方もあるかもしれないですけれども、ある意味品川区としてきちんとしたものを残していくといういただき方にもよろしくお願いしたいと要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"１項目から８項目ありますけれども、この調査の時点とか拠点とか、その辺について説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"今回の実施計画というのは、従来環境影響評価においていろんな手順を踏んでご説明あるいはお示しした部分については。今回とりわけ新たな実施設計段階で盛り込んでおくべきものを、これ以外についても当然のことだというふうには思っております。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"環境調査を行う、このあたりの、いつなのか、どこの拠点で行うのかというのは決まっているんでしょうか。一番最後のところです。","respondent":"金井環境課長","answer":"前にご説明があったと思いますけれども、環境影響調査表というのが出ております。こちらを見ていないと、この中には実際には具体的には入ってこない、こういうことでご理解いただきたいと思います。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"以前それもあったんですけれども、具体的に区内で拠点は何カ所ぐらいあるんでしょうか。特にダイオキシンの心配が強いんですが。","respondent":"金井環境課長、松本環境清掃事業部長","answer":"１.５キロぐらい離れた、西側のところで１.５キロぐらい離れたところで、そのほかは区内ではやっておりません。大井清掃工場はやっております。 おそらく、この調査というのは継続的にやられている調査だろうと思います。工場は一般的に基準を設けて、基準点を設けて年１回必ず調査を継続的にやっていますので、その辺の変化はとらえております。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"後でゆっくりそれは読むんですが、１.５キロメートルぐらいのところで１カ所、ほかには区内はないわけですか。その点を説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"この更新事業の実施計画に基づいての地元説明等はございません。基本的な環境影響評価であるとか工事説明というのは別途行います。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"すみません、区内の土壌調査の場所を知りたいんですけれども。後でもいいので、どこの場所でどう行われているのか説明を求めました。","respondent":"金井環境課長","answer":"土壌調査をやっているかどうかということですけれども、実際には土壌調査というのはやっておりません。特別に公共の施設を、直接やるとすれば公共の施設になりますけれども、定期的にそういうことはやっておりません。","id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"そういう点で、例えばどこか処理した堆肥として利用できる、そういうものについて流れをつくっていくということは考えられないのですか。そこをちょっと伺いたいんです。","respondent":"中山清掃リサイクル課長","answer":"当初、そういった声が出てきた場合にはどうするかということは検討はいたしましたが、その地域の中で利用できるようにしていただきたい。それなりに利用、処理されているということで、一義的なまずごみの減量という意味での目的は一定達しているというふうに認識しています。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"この間モデルでやった、そういうあれをきちんとリサイクルのルートに乗せていくことを私も求めたいと思っているのと同時に、せっかくやっている。ぜひ具体的な対応でできるように、ほんとうにそこはちょっとぜひとも検討材料としてお願いしたいということで、意見を言って終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問","question":"この辺の助成金額の基準というんですか、あと８０台、ちょっと根拠を説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"片や８０台ということからいって、これが平成１２年度から３年目になりますので、今後考えていきたいとは思っております。今年度はこのままの状況で、３年やった上で、いろいろとその後の対応について考えていきたいと思います。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なかなか困難が多くてできないので、とにかく参加者が増えるということと意識が高まる方向性を求めて考えていってほしいなと思います。３年間を経過して見てみるということなんですけれども、あと検証していくという方法が大事かと思うので、その辺についてもお考えを説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"ただ、このコンポスト化容器の助成についてもどうしていくかということはトータルで考えなきゃいけないのかなというふうにむしろ思っております。利用者の方にアンケート等をとることは考えておりますので…","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひアンケートなどで広く意見を求めていってほしいなと思いますけれども、やっぱりその辺、普及のためのご努力も必要かなと思います。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"中島委員","kind":"質問・要望","question":"それからでき上がったコンポストをどうするかということ、これを考えると、自分ではもう対処し切れないなというのが現状なんですね。そういった点では、コンポストをもっと皆さんが利用できるように工夫していただきたいなと思っているんですが、いかがか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"徐々にそういうエネルギー的な視点、環境的な視点も入れながら、こういう制度がどうかというようなことは考えていく必要は認識しています。減傾向の中で再検討の余地というのは私ども認識は持っておるんですけれども、今回設置場所だとか使い方について、いつでも我々のほうに。","id":"exchange-038"},{"speaker":"北野委員","kind":"質問","question":"そういうところの基準ですか、結局８０台以上多ければ、わざわざ５番にこういうふうに入れたのかどうか。ちょっと細かいことですみませんけれどもお伺いします。","respondent":"中山清掃リサイクル課長","answer":"既に購入した方がここで申し込んで助成するというのはできない制度ですので予定価格となっておるんですが、いや、やめましたと。別に予定価格とずれたからといって、その辺も、これはあくまでも事業者用の方ではないですよということも確認をする意味で書いていただいているです。","id":"exchange-039"},{"speaker":"北野委員","kind":"質問","question":"たしかそういうこともあったと以前報告で伺ったこともあります。だからそういう機会もとらえて、日程が合うので、そういう機会もとらえて参考にいかがですかという言葉も入れていただけたらよかったなということを。","respondent":"中山清掃リサイクル課長","answer":"チラシには入らなかったことは申しわけございません。それで、後ほどご説明しようかと思ったので、環境・リサイクルフェアの中でもこの辺のご案内をして、目に見える形でご案内したいと考えています。","id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"それは、配付は４年生ですから、今年は４、５、６年生ですが、配付は当然学校で配るわけですよね。これは一番最初ですから、声が出れば受けとめていただけるのかどうか、その辺でお伺いします。","respondent":"中山清掃リサイクル課長","answer":"ちょうど４年生が社会科の授業のプログラムの中で、品川区のこういう事情を踏まえてやっていただきたいということでおつくりしたものです。既に学校の先生方の勉強会の場面等でもご説明したところですが、そこの中で…","id":"exchange-041"},{"speaker":"中島委員","kind":"質問","question":"地方に行くと、これは非常に好評だというのをこの間も伺ったところなんですが、子供たちにもちろんこれを教えていくのは大事なんですけれども。カレンダーはとてもいいんですけれども、あれはもう一つ、ちょっと工夫を次回していただければ。","respondent":"中山清掃リサイクル課長","answer":"よく見るとなんですけれども、そんなふうな考えで、その好評を生かして子供たちに考えてもらおうというふうに考えておる次第です。今お配りしている分け方、出し方を新たにつくる際には、そういうガイドを配る際の折り込み等をあわせて周知を図っていきたいと考えています。","id":"exchange-042"},{"speaker":"中島委員","kind":"質問","question":"私は今でも認識が弱いのかもわかりませんが、これを燃やしていいのかな、どうなのかなというのを迷う場合があるんですね。明確に何か区民の方が覚えられるように、そういうものをある程度していただければありがたいなと思ったものですから、意見にしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"土井委員","kind":"質問・要望","question":"区内的なＰＲもさることながら、こういう逆効果もありますので、ぜひ進めていただきたいなというふうに思いました。ちょっとそういう中で、このコストは幾らでしたか。","respondent":"中山清掃リサイクル課長","answer":"端的に言いまして、約９５万円で１万２,０００部ということですから、税込みで約１部８０円弱の、単価になっております。","id":"exchange-044"},{"speaker":"北野委員","kind":"確認","question":"副読本があればいいなと私は思ったんですけれども、やはり小学校対象で、中学校は考えていないでしょうか。取り組みはないんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"とりわけ先ほど申し上げたように社会科の中で、具体的に４年生にそういうごみについて考える単元がありますから、４年生に絞ったです。ただ、非常に効果があるということになれば、また次のステップとして今回のこういったものの反響も踏まえて研究はしていきたいと思います。","id":"exchange-045"},{"speaker":"北野委員","kind":"意見","question":"中学生のほうでは、ある程度リサイクルというのは小学校の部分では出てくることですし、小学校の間に清掃工場の見学も入っていますよね。冊子ではなくても、何か使えるような資料としても提供があればいいんじゃないかなと思いますので、ぜひ研究をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"南委員","kind":"確認","question":"１４ページ、これは表現が正しいかどうかということなんですけれども、あちらから温水が来るわけではないんですよね。訂正しておいたほうがいいのかなとちょっと思ったので確認をしていただいて、八潮で学ぶ４年生は気がついて、あえてちょっと。","respondent":"中山清掃リサイクル課長","answer":"いわゆる高圧水蒸気というんでしょうか、これを高温水と言っているんですけれども、これを団地に送って熱源にしているわけですね。ワンクッションかむにしても、基本的にはこの高温水という形で送っているということは工場の見解でもありますので、間違いではないと思うんですが。","id":"exchange-047"},{"speaker":"南委員","kind":"質問","question":"熱で来ているわけですから。それでいいということであれば別にいいと思いますけれども、ちょっと気になったので言いました。","respondent":"中山清掃リサイクル課長","answer":"小学生に、若干この辺はわかるような説明ができるように、若干その辺は八潮団地の該当する学校等にはそういう説明をしたいと思いますが。高温水という言葉自体が難しいということは、確かにそういう面はあろうなとは、今伺って認識しました。","id":"exchange-048"},{"speaker":"南委員","kind":"意見","question":"仕組みはこれでいいんだろうと思うんですけれども、そういうふうな誤解というのをちょっと与えるという危惧があったので、全然問題ないよということであれば、それはそれで別にいいんですけれども、また改めてちょっと説明を要するということであれば、そういうふうに対応してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"これが継続的に使うのではなく、その中で、例えば授業の中で１時間なら１時間で終わってしまうと思うんですよね。前の部長もいらっしゃいますし、その辺どうか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"いろいろ環境清掃事業部等で用意している環境への取り組みについて、教育委員会からも活用についての文章を入れていただく予定になっておりますが、教育委員会を通じて各学校のほうにもあわせて申し添えていただくようにお願いしたいと思います。","id":"exchange-050"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"ぜひそれは利用していただきたいと思って。要望しておきます。","respondent":"高木委員長、中山清掃リサイクル課長","answer":"なければ、５番目の項は終了します。２ その他 １ 環境・リサイクルフェアの実施について その他に移りまして二つほどご報告がありますので、１環境・リサイクルフェアの実施について、ご説明をお願いいたします。 チラシにありますように、６月２日、西大井広場におきまして環境・リサイクルフェアを開催いたします。それから事業者による説明も行いますし… ご説明をいただきました。〔「なし」と呼ぶ者あり〕 なければ、環境・リサイクルフェアの実施についてのご報告を終わらせていただきます。…","id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"私がちょっと伺いたかったことが出ていなかったので伺うんですけれども、ガスが抜けていなくて、やっぱり分別のときにきちんとした。ですからそういう点も、ちょっと安易な意識がなくもないわけですから、考えていただきたいということをちょっと改めて。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"土井委員","kind":"質問・要望","question":"そんなのはいろいろあるわけですから、うちのごみをやってもらわなきゃいけないところですから、やっぱり変な形でちゅうちょしないようにしておいていただきたいなというふうに思っておりますので。","respondent":"松本環境清掃事業部長","answer":"それと、先ほど５億ないし６億の被害総額を申し上げましたけれども、当然これは消防庁のほうから改善命令が出るだろうと考えています。やはり改善命令に従った対処の仕方をするというふうに言っておりましたので、その辺は申し伝えております。","id":"exchange-053"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"この改修に対して費用がかかってくる、これは火災保険みたいなものに入っていて、その分というのは負担はできるんですか。それを１点説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"この保険が現状復帰するという条件になってありますので、基本的にはその現状復帰においては保険の中で賄われるであろうというふうに思われます。この経費はまた別途清掃一部事務組合として出てくる可能性はありますが…","id":"exchange-054"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"今そこが使えないと、中央防波堤に持っていくというのは、東品川の中継所から持っていっているんですか。それはどうなんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"そのほか、２２７トンが東品川清掃作業所から船で運ぶごみで、この２２７トンが品川、世田谷、目黒、渋谷の４区の不燃ごみです。その申し入れは結局必要ないというふうにかえられましたので、実際の搬入は通常どおり行われて、船の行き先が中央防波堤に行っているという実情です。","id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"９月か１０月かぐらいから実施するというような方向だと思うんですが、その後、ここの所管かどうかちょっとはっきり。〔「これは区民委員会ですか」と呼ぶ者あり〕。","respondent":"金井環境課長","answer":"今お話がございましたように、これは所管が区民委員会ですので、まだそういう段階に至っておりませんが、区民委員会のほうに先に報告した後に、こちらがごみの減量という形で報告のようなつながりになってくるかと思います。","id":"exchange-056"},{"speaker":"鈴木（真）副委員長","kind":"提案","question":"一言、最後に１回委員会を追加させてしまったというのが、自分のほうで提案させていただいて、２月に１回入れさせてもらっちゃいました。ありがとうございましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=5662#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":46145,"voices":146}},{"id":"h14-20020515-14","meetingId":"h14-cm05","date":"2002年5月15日","dateIso":"2002-05-15","committee":"行財政改革特別委員会","time":"午後１時０８分～午後３時１２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"情報を本来は区民が供用すべき情報だというふうに思うんですけど、その点は改善の余地があるのかどうか、この１点。こうした情報がいろいろ入るわけですから、そういう点なんかはどういうふうに考えられているのか、お伺いします。","respondent":"田中情報システム課長","answer":"基本的に検討に当たりまして、情報公開の個々の件名の文書等を公開するわけではありませんので、ほぼそれで従来と同じような形になります。個々に情報公開の請求があった際に、プライバシーの保護等を考えますと、やっていかざるを得ないだろうというふうに考えています。","id":"exchange-001"},{"speaker":"桜井委員","kind":"質問・要望","question":"私たちはすぐ窓口に行くんですけど、例えば一般の区民が求めるときというのは、これはどこの窓口だと行くわけでしょう。３００円払うという、すごくアンバランスというんですか、もっとより情報の公開を求めたいというふうに思うんですけど。","respondent":"田中情報システム課長","answer":"ちょっとここのところでご説明させていただきたいんですが、それぞれ部長の決定を得て出していく、審査した上で出していくというふうになります。先ほどの労働安全衛生上のこともありますので…","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問・要望","question":"そういう住民へのサービスの一環として、これはもっと改善の余地が私はあると思いますし、検討をお願いしたいというふうに要望しておきます。直接やっぱり住民への意見を聞くというんでしょうかね、ある面では住民システムということからも出発しているんではないかというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"嶋委員","kind":"質問・要望","question":"全部、庁内ＬＡＮは富士通ですか。役所に来て、そういう申し込みができる場所をこれから考えていらっしゃるのか、ちょっとお聞きをしたいと思います。","respondent":"田中情報システム課長","answer":"それから３点目ですが、保養所等ありまして、今後の中で検討していきたいというふうに思います。家にインターネットやパソコンを持っていない方たちに対する対応を含めまして、置くところを十分検討していきたいというふうに思っております。","id":"exchange-004"},{"speaker":"嶋委員","kind":"質問","question":"さっきのだれがというのがまだわからないことと、それと、役所の中でどこのほうに、いわゆる自由に使える場所が設置されていくのか説明を求めました。","respondent":"田中情報システム課長","answer":"何時何分このファイルにアクセスして、プリントアウトしまして、これをコピーしましたよとかという形で記録が残る形になります。それから、どこに公開端末を置くんですかというところは、いろいろな施設予約等を含めまして対応できるように十分検討していきたいと考えています。","id":"exchange-005"},{"speaker":"嶋委員","kind":"質問","question":"このＩＤ・パスワードを持っている人というのは、限定をされているということか尋ねました。","respondent":"田中情報システム課長","answer":"今区役所ですと、２,２５０人程度ＩＤ・パスワードが配布されております。そういう方は技能長とか、そこで入った方は当然それでそこの中の情報にアクセスしますと、記録が残るというふうになっております。","id":"exchange-006"},{"speaker":"嶋委員","kind":"確認","question":"じゃあ、これは人のパスワードを知らないということを前提としているということで了解をしてよろしいんでしょうか。そういうことがあるのかないのかだけ、ちょっと確認をしておきたいと思います。","respondent":"田中情報システム課長","answer":"基本的にＩＤ・パスワードは個人を認識するものですから、個人を識別する手段になりますので、それはそういうことでぜひご理解いただきたいと思います。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"この金額はまずどういう形ではじき出されたのか、その分を人件費に換算するとこういうふうになるという考え方でいいのかどうか、まず説明を求めました。","respondent":"田中情報システム課長","answer":"年間稼働日数がそれぞれ職員の２２４日として、１人当たり年間稼働時間１,５６８時間ということで計算しております。こういう転記作業がなくなりますというようなところがありまして、そういう効果を含めてとっております。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"そうすると、投資の部分は投資で経費として別にかかっているということで、トータルでの効果ということではないということですか。いずれ数字を出される予定とか。","respondent":"田中情報システム課長","answer":"それから帳票等がなくなるとかというところを含めまして、最低限これぐらいが事業を実施した場合、最低限の効果はこれぐらい出るということです。効果の部分については累積されていくという形になっております。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"ですから、経費としては１億２,０００万円毎年かかるけれど、全くこれぐらいの金額がという理解でよろしいんでしょうか。ぜひ研修は、当初の研修だけではなくて、継続的にぜひしていただきたいという思いがあるのが一つ要望として挙げさせてほしいと求めました。","respondent":"田中情報システム課長","answer":"これは電子調達の関係、それから電子申請、電子届出の関係、それから統合型ＧＩＳの関係を開発課題とした検討を進めるということでやっております。その点を含めまして、都ですとか、各市町村と共同で標準的なものをつくるということで取り組みたいと考えています。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"そういう意味では難しい。再構築するに当たっては、富士通のシステムに拘束されてしまうというんですか、そこをお聞きしたい。","respondent":"田中情報システム課長","answer":"データベース等もできるだけ文書的なものを入れるということで、おそらく過渡期は既存のものを多少引きずらざるを得ないかなというふうに考えます。ただ、今後のことを考えますと…","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"両輪である議会側の考え方というんでしょうか、それはぜひ再考し得るような構築を将来的には考えていきたいなと考えています。その辺の考え方だけちょっと説明を求めました。","respondent":"福田区議会事務局長","answer":"事務局として、どのような対抗が考えられるか、それは十分検討に値するというふうには考えております。ただ、この問題がストレートに事務局を巻き込んだ、議会を巻き込んだシステムかという結論をすぐに出すことはなかなか難しいというふうな現状です。","id":"exchange-012"},{"speaker":"辻副委員長","kind":"質問","question":"最初に、３ページにある勤怠庶務システムというのは専門用語ですか、「怠」って、「勤怠」の「怠」って。これから進む電子自治体という方向へ行くべきだと思うんですけど、その辺の今課題になっているというのはどの辺のことで、今後やっていくんか尋ねました。","respondent":"田中情報システム課長","answer":"ほとんどほかは排除するという考え方もありますし、いろんな業者のランク付等について一切排除して入札するという改革の方向をとるところもあります。そこは各自治体のポリシーの問題だというふうに思いますので、今後の中で十分詰めていくんではないかというふうに思っておりま…","id":"exchange-013"},{"speaker":"辻副委員長","kind":"質問","question":"今は事業部になるんでしょうか、この事業はどうしようかとかというときに、じゃあ修正しましょうやというような。そういう部分でのイントラとか、そういう使い方というのは、踏み込みというのはどうなんか尋ねました。","respondent":"田中情報システム課長","answer":"各課でいろいろ検討する際に共有フォルダというのがありまして、それで係員、課長を含めまして検討した内容を次々に入れていく。そういうことで、あとは、電子会議室等進んでいるということです。","id":"exchange-014"},{"speaker":"辻副委員長","kind":"質問","question":"これを説明しながら、これはこうして文書をひょっと直そうかというのを、そういう会議室というのはあるべきじゃないんだろか。それが、どうなんですかと聞いているわけ。","respondent":"田中情報システム課長","answer":"それから、電子会議室ですとか、そういうものは検討したりとか。この部分を無線ＬＡＮのときに検討したんですが、いろいろ検討した結果、今の時点では。","id":"exchange-015"},{"speaker":"辻副委員長","kind":"質問・要望","question":"今、今日ですか、有楽町でビジネスショーをやっている。何だと言われないようにやっていくだけの、やっぱりそういう感覚というのはぜひ持っていただきたいなと、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"鶴委員","kind":"質問","question":"果たして４０分間で対応できるのかということもあるし、まず、危機管理というのは一体どうなっているんだ。どうなっているんですか、今の段階で。","respondent":"田中情報システム課長","answer":"私ども新しいセキュリティの部分についても今検討しておりまして、入ったからといって、すぐにあそこからデータはとれません。その点で、最大のところでは、２４時間、その部分では入退室管理を続けているということで対応しております。","id":"exchange-017"},{"speaker":"鶴委員","kind":"質問","question":"このパスワードはだれだということがわかるけど、そういう場合は、どういうペナルティーがかかることになるわけですか。今の公務員法、地方公務員じゃなくて、あるいは国家公務員法の言うところの、どこが、何が適用されるわけですか、その人は。","respondent":"田中情報システム課長","answer":"例えば、契約の予定価格があります。見る必要もないわけですので、当然所属ですとか、その人の職ですとかに必要に応じてアクセス制限をするということで対応していきたい。","id":"exchange-018"},{"speaker":"金高委員","kind":"意見","question":"先ほどの設定の中で、ウイルスのチェックをざっと言われましたけども、これは今までそういうウイルスが侵入したということがあったのかどうか。見通しを説明を求めました。","respondent":"田中情報システム課長","answer":"一たん侵されて広がるようなことは今までありませんでした。まだわからないものが、どういうものが出てくるのかわからないですが、最善の努力をしていくつもりです。","id":"exchange-019"},{"speaker":"辻副委員長","kind":"質問・要望","question":"どうも、この１年間ありがとうございました。ほんとうに１年間ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/373656?Template=document&Id=5706#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":25541,"voices":47}},{"id":"h14-20020515-16","meetingId":"h14-cm05","date":"2002年5月15日","dateIso":"2002-05-15","committee":"街づくり特別委員会","time":"午後１時０４分～午後３時３８分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"最初に基本的なことをお尋ねしたいんですけれども、前回もちょっと伺ったかと思うんですが、いろいろな言葉が錯綜しているようなんです。こういう違いがあるんだとか、決めていく上で、基本的なことで違いがあるんか尋ねました。","respondent":"南雲都市開発課長","answer":"再開発の地区計画というのは２段階になっておりまして、土地利用の方針ということで、こういう方針をまずある程度の広い範囲で定めます。今回は３段階になっておりまして、整備計画を詰めていくという西口南地区ということで、３段階に分かれております。","id":"exchange-001"},{"speaker":"上山委員","kind":"質問","question":"遠いところに一番最初に網をかけるというんですか、整合性というんですか、そこら辺はどうなんでしょうか。ちょっと２点、お願いしたいんですが。","respondent":"南雲都市開発課長","answer":"１６３号線の奥まったところにありますので、中地区だけでは整備が進められないということで、これまで時間がかかってきたということがあります。ということで、工事につきましては、中地区と明電舎地区がほぼ同じ時期に完成するという予定になっております。","id":"exchange-002"},{"speaker":"上山委員","kind":"質問","question":"これも一度伺ったことがあるんですが、再開発を進めていく上では、課長がどこかでのあいさつの中で一度触れたことがあるかと思うんです。これで質問を終わりにいたします。","respondent":"南雲都市開発課長","answer":"それから、同意の状況ですが、この地区は、権利者が全部で８４名おりまして、そのうち１件は消防庁ですので、それを除きますと８３権利者。そのうち、未加入が８権利者ということで、約９割の権利者が準備組合に加入しているという状況です。","id":"exchange-003"},{"speaker":"藤田委員","kind":"質問","question":"その辺を、まずちょっとお伺いしたい。交通広場の機能について、ご説明ほしいと求めました。","respondent":"南雲都市開発課長","answer":"明電舎とソニーについては、これまで以上に高い建物で、超高層的なタワーが２本できます。機能としましては、バス、タクシーを対象にした施設を考えているです。","id":"exchange-004"},{"speaker":"藤田委員","kind":"質問","question":"だた単なる広場をつくって、人を集めて何かイベントをやるということだけはなくて、そういうのがあるかどうかという質問なんです。周辺に彫刻の小道にして、いろいろところから大崎に集まってくるというような、そういう人の集まり方の計画があるのかとお聞きしているんです。","respondent":"南雲都市開発課長","answer":"ほかの地区、都市に比べますと、そういうＩＴ関係の機能というものを中心に集積していこうというのが大崎地区です。人を呼ぶような施設ということも考えられるのではないかということで、今後、各事業者と協議していきたいと考えております。","id":"exchange-005"},{"speaker":"藤田委員","kind":"質問","question":"そうしますと、あれは１階、２階ですか、店舗がちょこっとあるだけで、あとは全部業務用といいますか、一般の方々は利用できなくなっていますね。ですから、今のうちからそういう検討、話し合いをぜひお願いしたいなと思っているんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"上山委員","kind":"質問・要望","question":"１ページを見ると、進めるべきお願い、要望みたいなものがあるんです。そこら辺の思いといいましょうか、一言あれば、何かお返事していただければありがたいんですけれども。","respondent":"南雲都市開発課長","answer":"操業を継続するという方法があれば、それぞれの権利者の事情を細かく聞きまして、いろいろな対応をしていくという作業にこれから入っていきます。十分な対応をしていくように、区のほうから、今後も十分な指導をしていきたいと考えております。","id":"exchange-007"},{"speaker":"本田委員","kind":"質問・要望","question":"２００４年には完成ということなんですけれども、そういう話し合いはどういう形で進んで、地域の中でどういう調和が図られていくのかというのが１点。近隣との調和がどういうふうに検討され、進められようとしているのか、もしわかれば教えてほしいと求めました。","respondent":"南雲都市開発課長","answer":"共存共栄という考え方で、これまで話し合いが進められておりまして、施設の整備なども行われたという状況です。既存の道路で、この開発後も交通については十分さばけていけるということが、開発に伴う事前の調査の中では出ていると聞いております。","id":"exchange-008"},{"speaker":"本田委員","kind":"質問・要望","question":"もしそういう調査をやっているのであれば、教えていただきたいと思うんです。ですから、人の流れがどう変化するのか、具体的にそういう数字を示していただきたいと思うんですが、出ているのか、出ていないのか。","respondent":"南雲都市開発課長","answer":"この開発に先立ちまして、車、それから人、それぞれ開発に伴ってどのような発生、集中の増があるのかにつきましては、調査をいたしておりますが、ちょっと整理させていただきたいと思いますので、次回、ご説明します。","id":"exchange-009"},{"speaker":"本田委員","kind":"質問・要望","question":"個別といいますか、今回、委員になっている皆さんにも、個別に示していただきたいということを、とりあえず要望しておきたいと思います。調和がとれたまちがこの一帯にできるかということを、行政サイドとしても、相当努力していただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"築舘委員","kind":"質問","question":"交通広場があるわけですから、それは一たん交通広場のバスの停留場にとまって、そして行くということだと思うんです。その辺の都のバス路線の計画というのは、いつごろ、どういうふうな形で、またどういう連絡が来ているかどうか、そこがわかれば説明を求めました。","respondent":"伊佐都市計画課長","answer":"交通局はその方向で検討しているですが、流れについては、ちょっと詳しい情報は来ておりません。都市計画サイドからも要望はしていますので、また動きがございましたら、ぜひ所管の委員会にご報告させていただきたいと思っています。","id":"exchange-011"},{"speaker":"築舘委員","kind":"質問・要望","question":"駅が今度、１２月にできるわけですから、そうしますと、やっぱり乗り降りの乗客が増えるということですので、当然、需要が増えてくるわけです。バス路線も増やすということも可能になってくるわけですから、品川区としての要望といいますか、要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"上山委員","kind":"質問","question":"最初に、ちょっとお尋ねしたいんですけれども、この図面によりますと、駅ができるということもありますし、交通広場がありますよね。最初にこちらを伺いたいんですけれども、例えば駐輪場などを含めてどんな感じなのか、わかれば教えていただければと思ったんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"上山委員","kind":"意見","question":"ちょっとお尋ねなんですけれども、そういうことも現状から見ればぐっと増えて、大丈夫なのかなと思ったりするんです。この辺はどんなふうに、経験というか、ちょっとわかりますかとの意見を述べました。","respondent":"南雲都市開発課長、岩田管理工事課長","answer":"その推計値でいきますと、周辺の隣接する小学校、中学校で十分に対応できるであろうという推計をしていると聞いてあります。それからまた、都心に近いエリアでは、郊外に比べると子どもの数が少ないという傾向があると聞いています。 四角く点線で囲ってあるのが品川シーサイド駅になるんですが、このちょうど真下の部分の交通広場部分に、約７００台の規模の駐輪施設を持つ。再開発事業で生み出す計画になって、現在、工事中です。","id":"exchange-014"},{"speaker":"上山委員","kind":"質問・要望","question":"先ほどの大崎東口第３地区などに５００戸近い住宅ができる、分譲ですか、かなりお金もかかる。何か要望だとか、変えるような話も伺いましたけれども、これは要望して終わりにいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"石田委員","kind":"質問・要望","question":"開発業者でもどこでもいいけれども、そういうところにどういう対応を求めるのか、どこまで事情説明を求めるのか。こういうことが起きたときに、区としてどういう対応をするのかというのがまるっきりわからないので、それを教えていただきたい。","respondent":"南雲都市開発課長","answer":"計画的なまちづくりを進めていくということで、それから工事の請負者についても、行政としても要請はしていきたいと考えております。遅れるということは聞いておりませんので、そのような場合については、個別の状況に応じてご相談に乗っていきたいと考えております。","id":"exchange-016"},{"speaker":"石田委員","kind":"質問","question":"そうすると、個別の契約はもちろんわかりますけれども、こういう場合についての説明というのは、必ず来ることになっているんでしょうか。そこら辺のところはあるのか、ないのか、ちょっと明解に説明を求めました。","respondent":"南雲都市開発課長","answer":"これまでも都市計画に係わります事業につきましては、労働災害が起きた場合には、事業者のほうから報告を受けております。提携にもよりまして、生命にかかわるようなこういう大きな事故の場合には、その都度、事業者から報告は受けております。","id":"exchange-017"},{"speaker":"石田委員","kind":"質問・要望","question":"申し合わせ事項みたいな形の中で要望ができれば、もし何かお考えがあれば、ぜひお答えをいただきたい。","respondent":"南雲都市開発課長","answer":"現場の管理体制をさらに向上させるように、行政としても、各事業者にその辺の要請を行っていきたいと考えております。事故の内容によりましては、委員会でも報告をさせていただきたいと考えております。","id":"exchange-018"},{"speaker":"川西委員","kind":"質問・要望","question":"さっきのご質問の中でいただいた答弁では、もう少し調整をしてみて働きかけるようなことですから、要望にとどめます。さっき、路線については細かいものを示されるということなんでしょうから、それでも結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"横山委員","kind":"質問・要望","question":"そういった整備の中で、８ｍだとか、１０ｍ、１２ｍと、いろいろと幅員の求め方が違ってくる。そして１２ｍを求めるときには、片側２車線、４車線を取ろうとして求めているのか。","respondent":"岩田管理工事課長","answer":"ですから、委員のおっしゃるような、ほんとうに望ましい道路というのは、東品川四丁目の中央に走っている区画街路がいわゆる１５ｍ。当時は、最低幅員１５ｍが都市計画の定めでありましたので、１５ｍ取っているのが一番望ましいものです。","id":"exchange-020"},{"speaker":"横山委員","kind":"質問","question":"それだったら、３本走っている、Ａ、Ｂ、Ｃ、Ｄだったか、何度も聞くけど、１２ｍ取っているんだけれども、これは全部車道ですか。それでいいですから。","respondent":"南雲都市開発課長","answer":"西口の道路でいきすと、１２ｍの道路というのは、歩道も含めたものでございまして、車の通る車道部分は８ｍございまして、両側に２ｍずつの歩道です。この地区の場合、実際の法律上の道路の歩道の幅よりは広く見えるというか…","id":"exchange-021"},{"speaker":"横山委員","kind":"質問","question":"それに平行して、歩行者通路２号というのが、８ｍの１８０ｍ走っていますよね。前に戻っちゃって悪いんだけれども、これも、今言うように、そういう考え方でよろしいんですかね。","respondent":"南雲都市開発課長","answer":"歩行者通路２号といいますのは、これはペデストリアンデッキでございまして。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問","question":"直接関係ないんで、結構です。道路の定義をちょっとお聞きしました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"石田委員","kind":"確認","question":"私もこういう数字のことはわからないので、今の横山委員のお話の中で、確認だけしたいんですが、公開空地を利用するというお話があったですよね。例えば東五反田で、これは完全にお願いをしていく話になると、できるできないという場合が出てくる可能性もあるのか尋ねました。","respondent":"南雲都市開発課長","answer":"将来にわたって確保できる担保ということを考えておりますが、計画的に開発されるもの以外に、個別に建て替えが行われる場合もあります。最大限、地元のほうと協議を行いまして、多くのスペースが生み出されるように協議を行っていきたいと考えております。","id":"exchange-024"},{"speaker":"本田委員","kind":"質問","question":"協議の中で、それが減歩率に合っているのかどうなのかというようなことが、根拠としてあるんじゃないですか。そこはどうなんか尋ねました。","respondent":"岩田管理工事課長","answer":"大崎の乗降客数が１日当たりこれだけあれば、こういった再開発という手法を用いて、まず道路基盤をぴしっとつくっていくということでやったものです。こういった貢献度に対して、先ほど言ったような容積の見直しのみのボーナスで…","id":"exchange-025"},{"speaker":"本田委員","kind":"質問","question":"補助２６号線があり、２８号線があり、道路でないほうが案外経済的には深くなるかもしれませんよね。１２ｍとか、１５ｍとか、私は聞いているわけなんです。","respondent":"南雲都市開発課長","answer":"考え方としては同じようなものでございまして、公園をどれだけ出したかに応じて、容積率をアップさせるということでバランスを取るということです。道路、駅前広場、公園などの整備量をそれぞれ細かく計算して積み上げていきまして、それとの見合いで、容積をアップするです。","id":"exchange-026"},{"speaker":"本田委員","kind":"質問","question":"では、減歩率何％というのは、区画整理でやるような決まり事とは違って、開発については、ものの考え方としては、道路確保をするについても、減歩的な考えはあるけれども、状況に応じてボーナスをどういうふうにつけるかを含めて、空地…","respondent":"南雲都市開発課長","answer":"東京都のほうで、道路はどういうふうにカウントするか、駅前広場はどうカウントするかというような計算の仕方が定まっております。それに基づいて計算して、容積を上積みしていくというやり方をとっております。","id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問","question":"先ほどの上山委員の質問に関連して、ちょっと聞きたいんです。公共施設への影響がどうなのかという質問だったんですけれども、どういう感じの内容だったのか、ちょっと教えてほしいと求めました。","respondent":"岩田管理工事課長、南雲都市開発課長","answer":"１ＬＤＫがどれぐらい占めるかといういわゆる間取りの規模によっても大きく左右されてまいりますので、小学校、幼稚園等への影響はないと。その結果については出ていると思いますので、答えていただきます。 １戸当たり、小学生が０.０４人というような数字がそれぞれ細かく出ておりまして、中学生でした何人発生するというような想定をしております。このようなことで、何人発生するかというのを、似たような過去の例から統計的に推計をして…","id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"今、想定するに当たって、例えば小学生だと、２ＤＫで０.０４人とか、そういう係数があるということなんですけれども、先ほど、学校、保育園等で聞いたんですけれども、小学生、中学生、保育園児、ここら辺で具体的何人というのは出ているんか尋ねました。","respondent":"南雲都市開発課長","answer":"これは、二丁目第１地区でどのぐらい生徒数が発生するかというときのデータです。例として二丁目第１地区の場合、賃貸を合わせまして２８人ということを推計して、事前に計画の中に盛り込んでおります。","id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今のご答弁で、小学生２８人ですか。８００戸で２８人か尋ねました。","respondent":"南雲都市開発課長","answer":"おおむね公団の推計した数字ぐらいの生徒が発生するということで、周辺の学校の規模で対応が可能かどうかを事前に確認するという作業をしております。そういう点では、事前に教育委員会でも協議するです。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"それから、住宅のことで、先ほど、２ＤＫの例が言われましたけれども、今の時点で、どういう内容で住宅が計画されているのか。広さとか、家賃とか、ポイントをちょっと教えてほしいと求めました。","respondent":"岩田管理工事課長","answer":"申しわけございません。ちょっと手元に資料がすぐに出てきませんので、今、取りにまいりますので、後ほどご報告します。","id":"exchange-031"},{"speaker":"伊藤副委員長","kind":"質問","question":"二つお伺いします。二つほど、お願いします。","respondent":"南雲都市開発課長","answer":"片側２車線以上ある道路が相当あるということで、交通をさばける容量としては、相当深い能力を持っている地域です。既存の道路の中で十分カバーできるといいますか、今回の開発の量が乗っても、交差点および各道路の容量の範囲内で収まると推計されております。","id":"exchange-032"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"いろいろなことに対して非常に快適なものを求めていくわけですし、小さなまちができるわけですから、私はちょっと違うような気がするんです。できれば、部長に答弁をいただきます。","respondent":"中谷まちづくり事業部長","answer":"周辺のソフト対応、あるいは臨時看板みたいなものを出すとか、そういうものによって過渡的な集中については対応していくです。その場合に車が徐行いたしますので渋滞が起きるおそれがあるということで、交通の流れを、ご理解をいただきたい思います。","id":"exchange-033"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"お金をかけない対策ができるわけですから、誘導の工夫をするとか、簡単な発想でいろいろな効果ができるはずなんですよ。そういうことを含めて、ぜひ、このまちづくりに関しては進めていっていただきますように要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"宮崎委員","kind":"意見","question":"問題なんで、そうなると、ほんとうにまちづくりと教育は違うというわけにはいかない問題ですよね。教育とか、そういうものを含めてのまちづくりだと思っていますので、ちょっとそこのところだけ一言言っておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"三上委員","kind":"質問","question":"２月１２、１３日に出席された方は、どれぐらいいらっしゃるんでしょうか。そういったことについてはどういうふうに考えていらっしゃるのか、このあたりを聞かせてほしい。","respondent":"浜脇住環境整備課長","answer":"計４日間、やらせていただきました。こういうご意見があったというようなことも含めて、１,７００部ですけれども、ニュースを全戸配布しています。","id":"exchange-036"},{"speaker":"三上委員","kind":"質問・要望","question":"こういった防火不燃に対してのまちづくりの考え方ですから、いろいろな状況を利用して徹底していっていただきたいなと思います。よろしくお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"宮崎委員","kind":"意見","question":"そこで、教育委員会の発想が、ブロックとしてキャパシティがあるということなのか、どうなのか。そこら辺のところは、街づくり事業部としては、どういうふうに受けとめておられるのかとの意見を述べました。","respondent":"岩野まちづくり事業部次長","answer":"この計画協議をしていたときには、ブロック以前でございまして、ここの学区の学校の余裕人員と発生の人員ということでやって、大丈夫という結論を出したと考えています。","id":"exchange-038"},{"speaker":"上山委員","kind":"質問・要望","question":"一つ要望というか、何か一覧か何かにして、少しわかるように。もうちょっとわかりよくまとめていただけないかと、要望しております。","respondent":"南雲都市開発課長","answer":"まちづくりマップということで、実際の地図上でどの場所をというのがありますので、そちらの資料をごらんいただきたいと思います。必要でしたら、お持ちいたします。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/690912?Template=document&Id=6230#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":43483,"voices":118}},{"id":"h14-20020521-5","meetingId":"h14-cm05","date":"2002年5月21日","dateIso":"2002-05-21","committee":"総務委員会","time":"午前１１時０３分～午後 ３時２５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"今の説明を、非常にさっぱりした感じを受けながらききました。実際に品川区として移転問題にどういうふうに思いをはせているのか、その辺の品川区としての気持ち、考え方をお聞かせ願いたいとの意見を述べました。","respondent":"小野（孝）政策担当課長","answer":"説明が事実経過だけに限らせていただきましたけれども、首都機能の非常に重要な位置を占めているというふうに考えております。各交通、当然私どもとしても品川区が首都の非常に重要な一角を占めているということで、断固反対をしていきたいというふうに考えているところです。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"意見","question":"片や自治体がやることだから、品川区としてはもっと打ち出していくべき態度が必要というのか、勇気が必要というのがあっていいような気がするんです。パンフレットをつくったらどうのというわけではないんだけれども、、ぜひお願いしたいんですとの意見を述べました。","respondent":"中尾根企画部長","answer":"思った以上に進展してきておりましたので、それは何とかの形でフォローしなければならないんじゃないかという認識は同じようには持ってあります。もう一方で２３区の統合の問題も合わせて、今後は厚く運動を展開していきたいと思いますきで…","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"意見","question":"でき上がったときの使い勝手、いろいろ思い描いているんでしょうけれども、やっぱり不便さが出るんだろうなというような気がしてならないんです。その辺まであまり踏み込むのはどんなものかというのがあるのかな、その辺を聞かせてくださいとの意見を述べました。","respondent":"濱野助役","answer":"この時点に来て、実際にそうなったらどうなるのかということを考えると、これは本気になって取り組まなければいけない事項だと考えております。そういう意味では東京も本当に本気になって反対しなければいけない時期に来ているということを痛切に感じております。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"非常に危険も多いわけだし、バックアップの部分でも機能が果たせるということであれば、十分当初の首都機能移転という目的が達せられるわけです。移転しなくても危機回避みたいな部分があるわけですから、連携を強く望んでおきますので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"土井副委員長","kind":"提案","question":"よその区市町村も含めた方々ですから、そこに「品川区は反対です」という場面が流れてくるようなものを早速始めていただきたいと思うんです。ぜひ、それぐらいから始めましょうということで提案をするんですが、お考えをお伺いしますとの意見を述べました。","respondent":"中尾根企画部長","answer":"はホームページから、今度きちんとした主張を載せる必要があるし、庁舎の垂れ幕もやればそれなりの効果があるだろうとかいろいろ考えております。実際上、できるところから始めたいということで考えておりましたので、そのことは十分受け止めさせていただきたいと思います。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"確認","question":"確認しておきたいんですけれども、資料１の最初に経過があって、国が主張する移転の意義があってその次に新都市の規模、４番として移転反対の理由とあるんですけれども、移転反対の理由というのはどこが言っている理由なのかよくわからないので、資料の説明をお願いしたいと思います。","respondent":"小野（孝）政策担当課長","answer":"これは東京都が全体の事務局になっているということもありますけれども、東京都、２３区を含めて、こういう視点で反対をしているです。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"いろいろな関係のよさというのも、そういうことをきちっと言っている学者もいるわけですから、それに対する対抗力というのが果たしてあるのかなと。それがないと何だか感情論に、あるいは既得権益を守るだけの話になってしまうというような気がするんですけれども、どうか尋ねました。","respondent":"濱野助役","answer":"今の時期のあれからすれば、なおさらそれを崖から突き落とすようなことをするのが得策というような、幾つかの論点があるかと思います。補強しながら構築していくべきかなということで、政経の場所一致だけでは論点としては弱いのかなという感じは持っております。","id":"exchange-007"},{"speaker":"塚本委員","kind":"意見","question":"ここのところをはしょちゃって、ただお祭り騒ぎになると、何のことだったなのかな。だれを後始末をしなかったというだけの話になってしまうという気がしますので、そこのところを私のほうは留意したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"あるいはいろいろな形での部分を論理的に組み立てて反対運動を展開するということなんですが、ぜひそれをお願いしたいと思うんです。行政の立場に立ったときの質問なんですが、マイナスがいっぱいあるというのは認識していますが、どういうふうに認識をされていらっしゃいますか。","respondent":"中尾根企画部長","answer":"日本の国全体、ないしは世界と対抗していく上でマイナスかどうかというのは、非常に難しい議論かなと思っています。少なくとも、そういうことはやった結果としてどういうふうになるかということを迎えていきたいというのが、私どもの考え方かなと考えています。","id":"exchange-009"},{"speaker":"林（宏）委員","kind":"意見","question":"一連のみずほの混乱がどうにかおさまっているというふうに聞いていますけれども、品川区としてはみずほに対して何をするべきかというか、何かするという考えがあるのかどうか聞かせてくださいとの意見を述べました。","respondent":"小野（弘）副収入役","answer":"契約上では７日にそのデータが入るという予定でしたが、結果的に１５日にデータをいただきまして処理を行ったという経過があります。支店のほうでは、それから今回のトラブルについての具体的な原因がわかった時点で把握、それから対応策について把握したいと考えています。","id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"実質的にはこのメンバーの総務委員会は今日で終わっちゃうわけです。だったら、委員会に何を報告していくことが行政としての役目かというのを考えながら報告を尽くしていってほしいなと思うので、お願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"土井副委員長","kind":"意見","question":"この１年間、総務委員会の副委員長を務めさせていただきました。そんな意味で、あいさつに代えしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201900?Template=document&Id=1580#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":12805,"voices":31}},{"id":"h14-20020527-8","meetingId":"h14-cm05","date":"2002年5月27日","dateIso":"2002-05-27","committee":"建設委員会","time":"午前１０時０４分～午後３時３７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"それから全体の地下化が４年ほど延びるという話があったんですが、そっちだけとりあえず生かすだとかという話はあるのかないのか。あくまでも連立で開通するということなのか、ご説明願いたいのですがとの意見を述べました。","respondent":"中島街路事業担当課長","answer":"説明不足で申しわけありません。この計画、先ほどの駐輪場とか、放置自転車のほうが先行して動いているです。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"全体として駐輪場だとか何だとかでとっていますから、東急が新たにそこに店を入れることについては一応オーケーになっているのかどうなのか。それはもうらち外で、これぐらいの規模ならいいよという話なら話でいいんですけれども、いかがなんか尋ねました。","respondent":"中島街路事業担当課長","answer":"具体的にどこまで話をして、正式に商店街がじゃあこれでいいよと言ったかどうかということまでは、私どもとしては把握してございません。","id":"exchange-002"},{"speaker":"辻委員","kind":"質問","question":"この放置自転車の保管されることについて伺いますが、大体予定としてはいつごろ考えているのか。設立というんですか、要するに業務のことですね。","respondent":"中島街路事業担当課長","answer":"放置自転車の今後の予定ですけれども、１４年度につきまして設計いたしまして、１５年度に整備着手ということで、１５年度中には完成させていきたい。１５年度には完成させる予定です。","id":"exchange-003"},{"speaker":"辻委員","kind":"質問","question":"今現在目黒駅がスタートしたんですけれども、状況としてはいかがですか。目黒駅周辺。","respondent":"中島街路事業担当課長、奈良交通安全担当課長","answer":"線引きして、今後２カ所になるわけですから、放置自転車を保管するかということは検討していきたいというふうに考えてあります。目黒のほうは……。 いわゆるＪＲ東急ビルができて以降、ほとんど今いわゆる放置自転車がないような状態でスムーズにいっております。今、定期的に巡回をしておりますけれども、あった場合には八潮のほうに撤去しております。","id":"exchange-004"},{"speaker":"辻委員","kind":"質問・要望","question":"これは要望で言っておきますけれども、歩どまりが悪いというか、要するに最終的には処分せざるを得ないという。ですから、その辺で１,０００台も置くという場所もあるわけですので、それだったらとりに行ってこようという。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"横山副委員長","kind":"質問・要望","question":"もう要するに地元割り当ての１５％緑地で手当てされちゃっているんで、そこら辺の開発というか、品川区独自の敷地は求められないんでしょうか。そこら辺のところを一つ教えてほしいと求めました。","respondent":"中島街路事業担当課長","answer":"Ｍ－１１、Ｎ－４、すべてのところを有料で借りなきゃいけないです。今後東急とも調整しながら、あるいは４事業間を、ほかの３事業者とも引き続き協議検討をさせていただきたいです。","id":"exchange-006"},{"speaker":"横山副委員長","kind":"質問","question":"地元利用というか、それの１５％というのがこの緑地ですべて手当てされているということで、そういった中に区が対応できるかできないか。保管場も品川区が一応２層式で管理しているところと、武蔵小山についても当然なされるべきだと思うんだけれども、現状はどんなものなのか尋ねました。","respondent":"中島街路事業担当課長","answer":"活用していくかという主体性を持った形で計画は進めていきたいというふうに考えてありますけれども、これから引き続き協議をさせていただきたいです。基本的には東急が設置して管理するという方向で、ただ、今東急と協議しています。","id":"exchange-007"},{"speaker":"辻委員","kind":"質問","question":"この印刷でいくと、この自転車の保管場所、これは高架下になるんだけれども、これは無料で借りるんですか。何かやっぱりこれは出すの。","respondent":"中島街路事業担当課長","answer":"有料です。こちらにつきましても現在、使用料について東急と協議をしています。","id":"exchange-008"},{"speaker":"辻委員","kind":"質問","question":"あの辺から見ると、やはり割高ですか。この１５％というのも先ほども話が出たけれども、その考え方について、値段的に高い。","respondent":"中島街路事業担当課長","answer":"私ども例えば使用料についても上部の３分の１ぐらいになるべきものというふうな考え方に立っていまして、そういったことも含めて調整しています。もう１点、そのはみ出る部分につきましては、鋭意交渉をさせていただいているところです。","id":"exchange-009"},{"speaker":"辻委員","kind":"意見","question":"本来には駅舎、公共輸送のほうがやらなきゃいけないような部分を、何かいかにもやってやったほうがなんていう部分もあったりする。１５％以外のところについては、もうちょっと、より詳しくとの意見を述べました。","respondent":"中島街路事業担当課長","answer":"駐輪場を駅周辺に設置するのは、この間検討会の中でもいろいろ話をさせていただきまして、東急としても設置をすると。ただ、この有料という形にはなりますけれども、鉄道事業者の責務という考え方の一つとして設置していくという、その点に立ってもらっているです。","id":"exchange-010"},{"speaker":"辻委員","kind":"質問・要望","question":"要するにオープンスペースとしてあるわけですから、どういう利用を示したって、やはり地元住民から見ればプラスになる方向。まちづくりについても進めていただきたいなというふうに思うのと、要するにその観点というのを忘れないでやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"横山副委員長","kind":"質問","question":"多分ここに設置されるのは２層式で、１,１００平米で何台ぐらいやっていこうというのと、ちょっと考え方だけを。せっかくの機会ですから。","respondent":"中島街路事業担当課長、佐藤委員長、田平建築課長","answer":"台数ですけれども、１,０００平米でで１,０００台を予定しています。区内に２カ所設置場所ができるわけですので、その辺… ほかになければ、本件を終了します。３ 建設リサイクル法の実施について あるいは書面による説明をする。品川区としては分別解体の届け出という部分で、早速５月３０日よりこの手順でいきます。","id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"このコンクリートの分別解体というのは何となくわかるんですけれども、再資源化にはなるんですか。ちょっと教えてもらえませんか。","respondent":"田平建築課長","answer":"国民の動機づけから始まって、その認識度が高まっていかないと、なかなか軌道に乗っていかないなという面もあります。木材につきましても、やはり再利用ということがこれから国民自身が認識しなければならないことだなというふうに思っております。","id":"exchange-013"},{"speaker":"辻委員","kind":"意見","question":"その中の受注者の中の6)のところで現場における標識の掲示とかというのは、よく建築で解体するときにどうしているんだというのがあったわけですね。ここの部分で何とか指導なりあるいはアドバイスというか、交渉とかというのができるのかどうか、ちょっとその辺をとの意見を述べました。","respondent":"田平建築課長","answer":"私どもは陳情、通報を受けまして、無届けで解体している業者がいれば、その現場でもって指示していって、また標識も掲示するように催告する。そういうことが、委員がおっしゃる紛争の未然の解決というか、防止にも…","id":"exchange-014"},{"speaker":"辻委員","kind":"質問・要望","question":"これは、それが法的にどうだということは別問題で、ぜひこれはやっていただきたい。今日はそういう機会でございましたので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"横山副委員長","kind":"質問・要望","question":"この字句の解釈がちょっとわからないので教えてほしいんですけれども、これは５０キロどうのこうのというのが裏面には出ていますけれども。ちょっと教えていただきたい。","respondent":"田平建築課長","answer":"縮減で足りるというのは、実際には燃やしてエネルギーとして変更するという意味なんですけれども、そういうことでも足りる。必ずしもリサイクルしなくてもいいということが書いてあります。","id":"exchange-016"},{"speaker":"横山副委員長","kind":"意見","question":"各委員が所属委員会を変わろうかと思いますけれども、どうぞ今委員会での提言等を来期に生かしていただければと、そのように思っております。はともあれ１年大変お世話になりまして、ほんとうにお礼を申し上げて終わらしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/807981?Template=document&Id=3720#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":16390,"voices":51}},{"id":"h14-20020531-6","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"区民委員会","time":"午後１時２１分～午後１時２９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/345074?Template=document&Id=2328#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":457,"voices":5}},{"id":"h14-20020531-7","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"厚生委員会","time":"午後１時２１分～午後１時２９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/534819?Template=document&Id=3018#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":463,"voices":5}},{"id":"h14-20020531-8","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"建設委員会","time":"午後１時２１分～午後１時２８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/807981?Template=document&Id=3722#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":463,"voices":5}},{"id":"h14-20020531-9","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"文教委員会","time":"午後１時２１分～午後１時３５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/547087?Template=document&Id=4438#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":460,"voices":5}},{"id":"h14-20020531-13","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"清掃・リサイクル特別委員会","time":"午後１時４５分～午後１時５０分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=5664#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":491,"voices":6}},{"id":"h14-20020531-5","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"総務委員会","time":"午後１時２２分～午後１時２８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201900?Template=document&Id=1582#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":459,"voices":5}},{"id":"h14-20020531-14","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"行財政改革特別委員会","time":"午後１時４２分～午後１時５０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/373656?Template=document&Id=5708#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":557,"voices":7}},{"id":"h14-20020531-16","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"街づくり特別委員会","time":"午後１時４３分～午後１時５２分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/690912?Template=document&Id=6232#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":555,"voices":7}},{"id":"h14-20020607-6","meetingId":"h14-cm06","date":"2002年6月7日","dateIso":"2002-06-07","committee":"区民委員会","time":"午後１時０５分～午後３時５８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その安全のつどいというのがどういう形でされていたのかがよくわからないんですが、ここら辺のところのかかわりというか、内容についてをちょっと教えていただきたいんですが。","respondent":"長田地域活動課長","answer":"その前に少しでも事故を減らしていこうというようなことから安全のつどいというような名称で実施をしています。３者で共催をして実施をしていまして、区としても一定の負担をしている、こういう形で実施をしてきたものです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今回のは安全条例の周知ということで１回限りで行われるものであって、安全のつどいについては予算額６０万円とここには書いてありますけれども、今回の区民のつどいの予算というのはどれくらいなのかについてもちょっと説明を求めました。","respondent":"長田地域活動課長","answer":"その経費の一部、特にきゅりあんの使用料等々、こういった部分の負担金という形で毎年６０万円を支出をしています。そのほか若干防犯協会のほうの負担が出てくるというような部分です。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"前の議事録では５月ぐらいに第１回をやる予定というふうなことで書いてあったと思うんですが、協議会の中身とあわせてぜひご報告をお願いしたいというふうに思いますけれども、いかがか尋ねました。","respondent":"長田地域活動課長、南委員長、久保田防災課長","answer":"５月から６月ごろということで想定はしていたわけですけれども、第１回が今度の月曜日、６月１０日に開催をする予定です。… 協議会が１０日に開かれるということですから、それが終わった後、報告も含めてよろしくお願いしたいと思います。ないようでしたら… 次に、報告事項の２番目、平成１４年度風水害初動活動態勢訓練の実施結果についての説明をお願いいたします。 訓練参加者ですが、１４７人予定しておりましたが、１４５人が参集しました。６番目、土木事務所が中心になって現地対応訓練ということで…","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"７番目のところで土のう製造・補充訓練ということで書かれているんですけれども、そういうのを書かれているような地図とかそういうものというのはつくられているのかどうか、ちょっとお聞きしたいんですが。","respondent":"久保田防災課長","answer":"左岸、その周辺、それから立会川の周辺には必ず土のう置き場を設置しているという状況です。その辺の場所等については、折に触れて地域の町会の皆さんとかには周知しているというふうには聞いております。","id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"時間的にはどうなんですか。指令を発するところ以外は知らなくて慌てて参集したというリアルな実態があるのかどうか、その辺ちょっと聞かせていただければと思うんですが。","respondent":"久保田防災課長","answer":"これは第１の目的でありますけれども、そのほかに、やはりこの水防関係に従事する職員の意識向上を図るというのを大きな目的にしております。の訓練の一つでもあるんだ、そういう意味でやっておりますので、その辺についてはご理解をいただければというふうに思っております。","id":"exchange-005"},{"speaker":"本田委員","kind":"質問","question":"立会川は危ないなということをあらかじめ大体予想もつくわけですから、こういう参集率で時間前に１４５名の方々が参集して所定の訓練をやったということについて、頑張るようにお願いしたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"本田委員","kind":"意見","question":"この立会川浄化に伴う放水との連動、今言ったような意味で連動、連携というのはどうなっていますか。それは連携はないのかどうかとの意見を述べました。","respondent":"久保田防災課長","answer":"今の件については私も深く説明をちょっと受けていなかったので、一つは当然そこの連携というのはやっていくというふうに考えております。ちょっと説明が言い足りなかったんですが、この水位計の使い方についてはまだまだ安定したものにはなっておりません。","id":"exchange-007"},{"speaker":"本田委員","kind":"質問","question":"東京都の下水道局と建設局ですか、これが違うからこういうふうにしないのかなと思ったりして、今報告を聞いていたんですけれどもね。それはどうなんか尋ねました。","respondent":"久保田防災課長","answer":"今のところにつきましてはかなり専門的な部分もありますので、後ほど私どものほうも所管のほうとよく聞いて、また再度お話しできる機会があればお話ししたいというふうに思っております。","id":"exchange-008"},{"speaker":"本田委員","kind":"質問","question":"１日５,０００ｔというんですからかなりの量です。ですから、そういう状況に対応すべきだというふうに意見だけ申し上げておきますので、それぞれの所管にご意見を申し上げたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"本田委員","kind":"質問","question":"１人、２人多くなっても、よりそういうふうに区民の方のご意見を伺うというのがこの種の計画をつくっていく上では非常に大事だと思うんですね。その辺はいかがか尋ねました。","respondent":"金井環境課長","answer":"１名、増やしても２名程度が、それ以上はなかなか難しいかなというような気がいたしております。１週間ぐらい２名程度しか応募がございませんでしたので、５日を過ぎてから３名ぐらい、そんな状況です。","id":"exchange-010"},{"speaker":"本田委員","kind":"意見","question":"オーバーしたからといって、この種の問題については、それをあれする人もいないと思うんですよね。ぜひいい基本計画がつくられるように、多方面の見識ある区民公募の方もぜひ増やしていただけるようにお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、ここの中で地域団体で消費者というふうに書いてあるところでは、どういう団体が入るのかを一つ教えてほしいと求めました。２３区の中、その環境基本条例についての区としての考え方がどういうふうになっているのかについて、説明を求めました。","respondent":"金井環境課長","answer":"条例ではなく基本計画とか行動計画できちっとやっていったほうがいいだろうということで、条例は現在のところ、区としてはつくる予定はない。つくり上げていこう、条例については現在のところ考えていないということで、ずっと従来ご答弁させていただいているところです。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"出ているかと思って、数字は違うかなと思って。もし出ていれば説明を求めました。","respondent":"宍戸ＩＳＯ担当課長","answer":"細かい部分はいろいろあるんですけれども、４,０００万円は超えるのではないかというふうに考えております。コピーにつきましては、コピーの契約しているのも含めた金額ということで、全部合計して４,０００万円というふうになってあります。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"このようにせっかく皆さんから集めた税金から運用していたので、４,０００万円というのはかなり大きな金額であって、それだけ使える。区の中の、皆さんの調整とご協力がかなりあるからこそできると思うので、これからも頑張っていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは清掃・リサイクルのところですけれども、生ごみについてはぜひ全体のところでもご検討いただきたいなというふうに改めて思ったところです。これはどういうふうに庁内の不燃廃棄物を減らしていくというふうなところで、具体策は出ているかどうかについてちょっとお聞きしたいと思います。","respondent":"宍戸ＩＳＯ担当課長","answer":"何とかお持ち帰りいただけないだろうかというような交渉をしていきたいなというふうに思っております。その手始めといたしまして、ヤクルトの容器につきましては、今年の２月、３月ぐらいから集めていただいて回収しているというふうなことがあります。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはりごみになるようなものを使わない工夫というのが本当に必要だなというふうに思います。そういうところでは、対策そのものをいろいろなところから検討して、ぜひこの問題でも検討できるように頑張っていただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問","question":"講師の方がお見えになったとき、やはりそういう背広の格好で来て、区の方たちはそういうときにどういう対応をするのかなと。ちょっとまずそれを説明を求めました。","respondent":"宍戸ＩＳＯ担当課長","answer":"そういったケースは多々あると思います。各所管を通じて、そういった主要メンバーの方に区の取り組みの趣旨等を説明してもらいまして、まずは働きかけていただきたいというふうなことです。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問","question":"背広着て営業しているというのは、それだから、役所に入ったときにどう思うかなとちょっとそこら辺が。それともワイシャツ的な襟つきなのか、ポロシャツまで含んじゃうのか、そこら辺を説明を求めました。","respondent":"宍戸ＩＳＯ担当課長","answer":"職場の中で仕事をするぞというふうに見えるかどうかという点で、そういうふうな職務に臨むような形のきちっとした形のポロシャツであればいいと。区民の方が１０人中７人ぐらいまでが…","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これはやっぱり職員の方は中だけの問題で、例えばよく都のほうに行くとか、そういうときにはやはり普通の背広の姿になっちゃうんですか。その辺を説明を求めました。","respondent":"宍戸ＩＳＯ担当課長","answer":"徐々に、広めていくということを胸に置きながら適切な対応をそれぞれとっていただくというようなことになるのかなというふうに思っております。どうもあいまいな答弁で恐縮ですけれども、以上です。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/345074?Template=document&Id=2330#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":52818,"voices":127}},{"id":"h14-20020607-9","meetingId":"h14-cm06","date":"2002年6月7日","dateIso":"2002-06-07","committee":"文教委員会","time":"午後１時０４分～午後５時０９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"高星委員","kind":"意見","question":"民主党区民連合の高星です。よろしくどうぞお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"何というんですか、全体の分布というんでしょうか、ちょっと全体像をもう少し詳しく教えてもらいたい。","respondent":"鷹倉庶務課長","answer":"この辺がどれぐらいボリューム的にあるかというのを一つの基準に学校改築の順番を決める指針にしていきたいなというふうに思ってあります。５０年が一つの目安なわけですけども、それ等を踏まえつつ、そういうものをいろいろ見ていきたいなというふうに思ってあります。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"１７ページの「学校施設の改築に関する意識調査集計」、10)の冷房のところで、この中身を教えてもらえますか。これは校長先生に聞いたものですよね。","respondent":"鷹倉庶務課長","answer":"我々もその意識を調査するという形で、いろいろご見解を伺った上で、さらに先ほどの学校改築検討委員会の中で先生方の意見を伺ってあります。本文のところは、おわかりのとおり、こういうものを考慮しながら、配慮しながら検討していくという形でのまとめをさせていただいた。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"私が今聞いたのは、この集計調査表はどういう意味なんですか。ないということなのか、だから、そこをちょっと聞いた。","respondent":"鷹倉庶務課長","answer":"この設問の出し方そのものも、この検討委員会、校長先生、教頭先生が入った中で、設問を一つ一つ丹念につくり上げていきました。それで、十分検討した結果、こういう聞き方で聞こうと、こういう形になったものです。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"そしたら去年、別の、学校が３９度になったと記録しているんだなんていう状況ですから。何か聞くところによると、そこらをあわせてお尋ねしたいんですが。","respondent":"鷹倉庶務課長","answer":"台場小学校と、それから荏原第五中学校については、学校改築検討委員会の準備会といったものをやってあります。ただ、今の段階でクーラー云々という話は、全然どこでも利用されてございませんので、それは少し違うのかなというふうに思います。","id":"exchange-005"},{"speaker":"原委員","kind":"質問","question":"この指針が出る中間のところでもおそらくそういう質問が出たのかもわからないんですけれども、それから学校関係の中でつくられた委員会ですよね。地域におろしていこうというお考えなのか、この指針をつくり上げていくという発想にはならなかったんか尋ねました。","respondent":"鷹倉庶務課長","answer":"予備的にちょっと行って説明している部分があるんですけども、やはり自分たち、ちょっとよくわかりにくいということがあります。その場で意見をいただくのが適切じゃないか、こう判断して、こういう形でやってきたものです。","id":"exchange-006"},{"speaker":"原委員","kind":"質問・要望","question":"地域の方々なり、介護型施設としてはどういうものが適切なのかという意見もここに組み入れていっていただきたいなというふうに思うんですけれども。もう一回、ちょっとその辺の考え方、今後の中での形を踏まえてちょっと考えを。","respondent":"鷹倉庶務課長","answer":"ただ、実際この検討委員会、かなり回数を重ねていっております。我々が、そして区民の方々が意見を述べやすいような状況をつくるということがまず急がば回れではないかなと、こういうふうに考えた次第です。","id":"exchange-007"},{"speaker":"中島委員","kind":"質問","question":"１６ページにほかの市区に学校の視察が５校取り上げてあるんですが、これは各学校それぞれ特徴があると思うんですが、どういったところが特徴なのか説明を求めました。","respondent":"鷹倉庶務課長","answer":"これはバリアフリー化に対応した学校でございまして、スロープがかなり壁側といいますか、沿った形でとってございました。都心部ではちょっと考えられないようなつくりなんですけれども、とてもおもしろい、建物的にはおもしろい建物です。","id":"exchange-008"},{"speaker":"中島委員","kind":"質問","question":"例えば今意識調査の質問事項も十分考えられたということでお話を伺ったんですけど、10)の冷房の件ですけども、ただこれだけの質問だと。ですけど、これにかわるような対策というのも検討するべきではないかと思うんですが、その辺はお考えか尋ねました。","respondent":"鷹倉庶務課長","answer":"ちょっとグリーンぽいものなんですけども。そういうようなものをしていけば、一つの温度対策になるのかなと、こういうふうに考えてあります。","id":"exchange-009"},{"speaker":"中島委員","kind":"質問・要望","question":"それから、例えば教室のそばに木が１本あっただけでも随分温度が違うと思うんですね。そのほかの対策とか、そういったものもこれから十分検討していただきたいなと、これは要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"石田委員","kind":"確認","question":"確認なんですが、今検討委員会が１０回まで開かれて、一度解散するということなのかということが第１点。続けてお聞きするとしたら、校長先生を含めて、どういう形でこれが使われていくのかということをあわせてお聞きします。","respondent":"鷹倉庶務課長","answer":"学校改築検討委員会が１０回持たれて、その後どうなっているのかという話ですが、結論的に言いますと、これは休会状態ということを考えてあります。したがって、１０年ぐらいたったときに、もう一度学校改築検討委員会というものを一つの今までの流れを踏まえながら。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問・要望","question":"これは計画的にやっていかれるわけでしょうから、休会ですから、そういうお考えがあるのかということ。パソコンからぱっと引っ張ったのか、どういう形でこれができたのか、ちょっと教えていただきたい。","respondent":"鷹倉庶務課長","answer":"その間に１０年を待たずして、それは休会ですので、新たに検討して改訂版をつくっていくということが求められるのかなと思います。この茶色のところは木材の色彩ではなくて、ただたまたま茶色だったです。","id":"exchange-012"},{"speaker":"佐藤委員","kind":"質問・要望","question":"質問ではないんですが、委員会のメンバーも改まりましたので、これに関連した視察を委員長のほうでできるだけ早い機会にひとつ設けていただきたいということをお願いしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"鶴委員長","kind":"質問・要望","question":"私のほうからちょっと確認の意味で言っておきたいんですが、指針であって、憲法ではないというふうに思います。どういうスパンをお考えなんですが、実際に。","respondent":"鷹倉庶務課長","answer":"通常、一番嫌われていた絵というのは業者が決まって、かいて、はい、説明会。これを昼間だとか、夜もするとか、時間を割きながらやっていきたいなと、このように考えてあります。","id":"exchange-014"},{"speaker":"高星委員","kind":"質問・要望","question":"新たに主幹という組織を設けるということは、まず一つに新たな主幹というのは、役職としてはどういう役職になるのか。入れない人なんですかという、任務というのか、そういったところをちょっとわかりやすく教えていただきたいなというふうに思います。","respondent":"青木指導課長","answer":"１点目のリーダーですけれども、というか、そういうふうな形で受けとめて皆さんいらっしゃるかと思います。これは東京都が行うものですので、そういう全国的なレベルの法的なものに位置づいたものではございません。","id":"exchange-015"},{"speaker":"高星委員","kind":"質問","question":"そうすると、今の説明の中であった指導主任とか、教務主任という、主任制度がなくなっちゃうわけじゃないんか尋ねました。","respondent":"青木指導課長","answer":"これは主任制度の見直しですので、主任制度そのものを変えるわけではございません。教務主任や生活指導主任をこの主幹が兼務できるということになっております。","id":"exchange-016"},{"speaker":"高星委員","kind":"質問","question":"何かよくわからないんですけど、主任制度の見直しで主任が残って兼務もできるとか、わかりにくいなというふうに思います。主任の先生方とはうまくいっていないということで、現状どうなっているのか、ついでにその辺をちょっと説明を求めました。","respondent":"青木指導課長","answer":"現在の主任制度がどういうところに問題があるのかというようなところからこの検討は始まっておりますので、幾つか問題点が上がっております。それとか、主任が職として設置されていないというようなこととか、その主任が年によって変わっていくというようなことも含めて。","id":"exchange-017"},{"speaker":"高星委員","kind":"質問・要望","question":"いずれにしても、１０月から１１月くらいに面接を行うということになるんですか。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"原委員","kind":"意見","question":"今の話にちょっとつながるんですが、この主幹制度で、教員の配置は各学校人数によっていろいろあるんでしょうけど、どういう形になりますかとの意見を述べました。","respondent":"青木指導課長","answer":"現在の教員の中から主幹を希望する者を位置づけますので、教員の人数というのは現在のところは変わるものではございません。主幹は授業を行うという立場にもありますので、人数的には今変わるということはございません。","id":"exchange-019"},{"speaker":"原委員","kind":"質問","question":"そうすると、主幹という名前はそこに来ますけど、全体的な組織の中では何ら変わりはない。ただ、主幹という責任上、いろいろな立場上のものの責任は負わさない、あるいは、それだけのものは持つということになるわけか尋ねました。","respondent":"青木指導課長","answer":"今、委員がおっしゃられた責任、権限というようなところが大きく変わってきますので、要するに仕事の中とか、教職員の中での位置づけというのは当然変わってきます。","id":"exchange-020"},{"speaker":"原委員","kind":"質問","question":"もう少しやわらかい言葉で、それに補うとか、そういうことができるんですか。何となく主幹という感じが、どうもそぐわないかなというふうに思うんですがね。","respondent":"青木指導課長","answer":"今のところは主幹という名称で考えております。","id":"exchange-021"},{"speaker":"沢田委員","kind":"質問・要望","question":"どうも監督責任というのは具体的にどういうことなのか、もう少し説明していただきたいのと、そんなにたくさんの先生がいるわけじゃないですよね。何か偉いのばっかり、何かそんな役職をたくさんつくってどうするのかなという気がするんですけれども、その辺はどうなんか尋ねました。","respondent":"青木指導課長","answer":"偉いとか、偉くないとかということまでは表現するものではないというふうに考えております。それから組織の活性化だとか、スピーディーな課題解決だとか、そういうものができるというふうに考えております。","id":"exchange-022"},{"speaker":"沢田委員","kind":"意見","question":"主幹２人を新たに置くというのはどうも現実的じゃないんじゃないかなという気がするんですが、主幹になると給料が上がるような仕組みとして位置づけられているのかどうか、そこらをちょっとご説明願いたいとの意見を述べました。","respondent":"青木指導課長","answer":"ですから、その規模に合わせてその主幹の活用というのは考えられるかと思います。それから２点目ですけれども、給料がほかの教員よりもアップするということは先ほど言ったとおりです。","id":"exchange-023"},{"speaker":"沢田委員","kind":"意見","question":"やっぱり冒頭でいわゆる管理強化ではありませんというふうに書かれているんですけれども、私はどうもそっちのほうが心配になるというふうに思います。一応意見として、それは述べておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"中島委員","kind":"質問","question":"主幹というのは面接とか書類調査されるんですが、これはあくまでもその先生のされている、希望されている方ですね、推選か尋ねました。","respondent":"青木指導課長","answer":"これは当然希望されている方です。","id":"exchange-025"},{"speaker":"中島委員","kind":"質問・要望","question":"人格者というんでしょうか、そういう人格者の中でも、管理職を望まない方っていらっしゃいますよね。そういう方たちにぜひこういう立場に立っていただきたいなという思いがあるわけなんですが、あくまでも希望となるとまた違う……。","respondent":"青木指導課長","answer":"今委員おっしゃったように、そういう方になっていただきたいということで、管理職のほうからまたいろいろと働きかけがあるかと思います。なおかつこうした校内の組織の中核になって働けると…","id":"exchange-026"},{"speaker":"中島委員","kind":"質問・要望","question":"外から見て感じているんですけども、そういった意味では、やはりこういった立場に立ってほしい人を推薦できるようなご配慮を要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"石田委員","kind":"質問・要望","question":"すみません。ちょっと私もわからないんで教えていただきたいんですが、面接で先ほど選任すると言ったんですが、これはだれが選任するんか尋ねました。","respondent":"青木指導課長","answer":"当然書類審査だったり、それから抱負などを論文として書いてもらったりして、それを審査しながら面接をして行います。これは東京都教育委員会のほうで行いますので、東京都教育委員会が認めたということになります。","id":"exchange-028"},{"speaker":"石田委員","kind":"質問","question":"お２人なのか、３人なのかわかりませんが、主幹という資格を与えることについては係われないということで理解していいんか尋ねました。","respondent":"青木指導課長","answer":"東京都教育委員会に本区の事情とか、一人一人の主幹を希望された方に対しての内申というのは当然行いますので、区の事情、学校の事情を踏まえた形で、東京都教育委員会が主幹を選んでいくと、そういうシステムになるというふうに考えてよいかと思います。","id":"exchange-029"},{"speaker":"石田委員","kind":"質問","question":"いろんなところで皆さんに、先生方にもご協力をいただいて、教育改革をやっているわけですよね。そういう方を品川区もどうしても採らなくてはならないというのが、２回やられたと、そこら辺のことをちょっとお聞きしたいと思います。","respondent":"青木指導課長","answer":"ですから、今度は主幹対象の異動要綱というのが出てきますので、またその段階で東京都教育委員会とさまざまな話し合いが出てくるかと思います。それから、それからこれは６年…","id":"exchange-030"},{"speaker":"石田委員","kind":"質問・要望","question":"要望なんですが、いろいろ要望を出したりして、ぜひぜひそういうことを言っていただきたいなと思います。これは要望にしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"沢田委員","kind":"意見","question":"西五反田とあるのに、７００から８００メートルぐらい遠くなるのかな、１キロぐらいになるかな。やっぱり明確に方向を示してほしいというふうに思うんですけれども、言えないのか、そこらをまずわかりやすく説明してほしいんですとの意見を述べました。","respondent":"富田教育改革担当課長","answer":"学校規模をどうするのか、また募集方法をどうするのかといった、そういった全体的な問題につきまして検討を進めてまいりたい。そういった意味で、そういったことを踏まえながら今後検討を進めてまいりたいと考えていますので、よろしくお願いいたします。","id":"exchange-032"},{"speaker":"沢田委員","kind":"質問・要望","question":"早くこたえてやらなければ、ますます不安が不安を呼ぶというふうに思うので、もう一度お願いしたい。結論を出す目標があったら教えていただきたいということと、予算特別委員会で質問して、ちょっと教えていただけますか。","respondent":"富田教育改革担当課長、鷹倉庶務課長","answer":"おそらく研究検討が大変なことになるかとは思いますけれども、状況がありますので、鋭意努力をしていきたいというふうに考えております。９月の学校選択前には、最後のリミットがそのときで… 今、日野中学校というお言葉がありましたけれども、第二日野小学校かと思いますが。","id":"exchange-033"},{"speaker":"沢田委員","kind":"質問","question":"家庭が協力を今までして学校をつくってきているわけですから、そういう人たちにも早くやっぱり説明をすべきだと、いずれにせよね。そう思いますけど、そこはいかがか尋ねました。","respondent":"富田教育改革担当課長","answer":"大崎第一地区の町会等の回覧のほうをお願いするなどして、できるだけこれから入るお子さん方についての情報提供というのは、努めてまいりたいというふうに考えております。","id":"exchange-034"},{"speaker":"高星委員","kind":"質問","question":"幾つかお聞きしたいんですけど、これはどの程度柔軟にするのかということでちょっとお聞きしたいなと思った。これからずっと先、柔軟に対応するということであるのかどうなのかということをちょっとお聞きしたいなというふうに思います。","respondent":"富田教育改革担当課長","answer":"小中一貫校にふさわしい学級数というのはどの程度のものなのかということを別に検討はしてまいるわけですけれども、その中で、それに従いました。中学校、それぞれの学級数を決めてまいりますので…","id":"exchange-035"},{"speaker":"高星委員","kind":"提案","question":"実は私、いろいろ途中の経過があるものですから、今の課題は今の課題としてご説明を聞かせていただきたいというふうに思います。その辺のところ、どうなの、もう一度確認の意味で聞きたいなというふうに思いますとの意見を述べました。","respondent":"指田教育次長","answer":"今の段階の中では、学校を統廃合する考えは持っていないということを、学校選択制と同時に認識しておいていただきたいんですよ。学校経営を含めてですけども、小中一貫校のあり方をほかの学校にもカリキュラムとしていろいろともし実施した場合、実施していった場合においては。","id":"exchange-036"},{"speaker":"高星委員","kind":"質問","question":"第一日野小学校でもいいんじゃないですかということになってきちゃうんだけど、そういう考えというのは、どうなんでしょうね。そういうことも、この学校改築計画の中では将来的にも見直すこともあるような話がありましたけれども、今回のものについてはどうなんか尋ねました。","respondent":"鷹倉庶務課長","answer":"さっきも学校改築検討委員会でも言いましたけれども、建物が先じゃないんですね。第二日野小学校でつくりたいんだという形で私どもはご予算を提出して、ご承認いただいたという理解を私どもはしています。","id":"exchange-037"},{"speaker":"高星委員","kind":"確認","question":"学校は決まっていないけど、場所は決まっているということなんですか、ちょっとそこを確認したい。","respondent":"鷹倉庶務課長","answer":"小学校は、中学校はどうするのか。いろいろ検討した結果、学区域、第四日野小学校を包含する日野中学校を持ってくるのが適切だと、こういう判断のもとに提案を申し上げたです。","id":"exchange-038"},{"speaker":"高星委員","kind":"質問・要望","question":"個別なことを言っても、私は構わないというふうに踏んで、あえてここで申し上げますけれども、来る９日に第一日野小学校の同窓会総会が開かれる。正しい情報をつかまえていただきたいなというふうに思っていますので、情報とお願いということで、私はこの場では終わっておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"原委員","kind":"質問・要望","question":"ちょっと確認をさせていただきたいんですけども、前回５月にやられたものを踏まえて、基本的な考え方を出してきた一つのコンセプトですよね。その中で、例えば検討委員会をどういう形で立ち上げていくのかわかりませんけれども、そこのところの状況をちょっと教えていただけないか尋ねました。","respondent":"富田教育改革担当課長","answer":"準備委員会で速やかに検討を進めながら、推進委員会は昨年度以上の回数を持ちながら鋭意努めてまいりたいと考えていますので、よろしくお願いいたします。","id":"exchange-040"},{"speaker":"原委員","kind":"質問・要望","question":"そうすると、先ほどの話ではないですが、一応タイムリミットは決められているわけですよ。こういう話ですから、しっかりとした形をちゃんと出していただきたいというのが私たちの要望なんですが、それはできますよね。","respondent":"指田教育次長","answer":"小中一貫校について、議会との関連については、決まったものを出すというものではないというふうに基本的には考えています。準備委員会あるいはプラン２１推進委員会、こういうコンセプトで今検討していますという、このように考えております。","id":"exchange-041"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、その中で今いろいろ審議されていますけれど、あまり突っ込んで話をしても、答えが出てこない部分もたくさんあると思う。このように、議事進行まで言って申しわけないですけど、よろしくお願いをいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"原委員","kind":"意見","question":"しかも今の話だと、時系列的にこれから出てくるものがかなり量的にある。次をどんどん進めていく必要があるし、深めていく必要があるとは思うんですけれども、その辺のところでご配慮いただければなと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"上山副委員長","kind":"質問・要望","question":"２点というか、最初にちょっと基本的なことをお尋ねと確認をさせていただきたいんですけれども、一つはね。そこら辺の基本的なことをちょっと３点ばかり教えていただけませんか尋ねました。","respondent":"富田教育改革担当課長","answer":"これも現在教育課程の部会の事務局のほうで検討している問題ですので、もうしばらくお待ちいただきたいというふうに考えております。新一年生の募集方法につきましては、これからの課題です。","id":"exchange-044"},{"speaker":"上山副委員長","kind":"質問・要望","question":"かなりいろんな住民の皆さんからの要望だとか、かなりそういう声というんですか、かなりそういう要望がありましたよね。なければないで構わないんですけど、そこら辺はどうだったんか尋ねました。","respondent":"指田教育次長","answer":"どうすれば、いろんな意味が加わって整理ができるかということを考えているわけですから、その点だけはぜひともご理解のほどお願いしたい。こういうふうに考えております。","id":"exchange-045"},{"speaker":"中島委員","kind":"質問","question":"これまでいろんな学校で説明をされていたと思うんです、この小中一貫校に対してのね。その説明に当たって、最初にどのようなお話をされて、ちょっと唐突な質問なんですが、どのようなお話をされて説明会に入られているんか尋ねました。","respondent":"指田教育次長","answer":"最初には、やはり学校の、今品川区というのはプラン２１でもって学校を変えていきたい、こういうふうな形でもって進めてお話をしてきました。これからそういうふうに学校規模をどうするんだということやなんかについても、いろいろ細かく検討してまいりたい。","id":"exchange-046"},{"speaker":"中島委員","kind":"質問・要望","question":"じゃあスタート時はどうするんですかというような、何を持ってくるんだ、こういった声になっていくんじゃないかなと思うんです。最初にご説明されちゃうと、そのいろんなことが決まっているのかなという誤解を生んでしまうんではないかなと思うんですが、いかがか尋ねました。","respondent":"指田教育次長","answer":"１８年、やはり文部科学省のある程度の教育改革校という形のものがないと、いろんな形ができません。したがって、皆さんのご意見や何かだとか、いろんなことを聞きながら整理をしていきますよというのはもちろん言ってきているつもりでおります。","id":"exchange-047"},{"speaker":"中島委員","kind":"質問・要望","question":"これと私は分けて考えるべきではないかなと思うんですね。これは街づくりとか、そういうところとのタイアップというのが必要だと思うんですが、いかがか尋ねました。","respondent":"指田教育次長","answer":"先ほど高星委員からもお話がありましたような、そういうお考えを持つ方もいらっしゃいますし、いろいろ考え方がいっぱいあるかもわかりません。そういうことも踏まえて１８年のときにということを、一体となって今回は考えさせていただいたという内容ですので…","id":"exchange-048"},{"speaker":"中島委員","kind":"質問・要望","question":"今の質問は２点にわたって質問させていただいたわけですが、いろんな項目を決めて、次の委員会でやっていきたいなと思います。これは要望にとどめておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"高星委員","kind":"質問","question":"研究開発校の指定を受けたというような説明があったと思うんだけど、富田教育担当課長、そこのところをちょっと説明してください。私は文教委員を１年やったけど、決定を受けたのなら、その日程的なことを教えて。","respondent":"青木指導課長","answer":"その指定を受けることは確実になっていることは間違いない。まだ指定書は届いておりませんけれども、指定書が間もなく届くであろうというところまでは確実になっております。","id":"exchange-050"},{"speaker":"高星委員","kind":"質問","question":"指定書というのは、これは場所の特定まで含むんですか、どうなんか尋ねました。","respondent":"青木指導課長","answer":"これは学校に対して指定があるわけです。学校と、それから東京都教育委員会、その所管の教育委員会ということで、東京都教育委員会とそれぞれの学校に対しての指定ということになります。","id":"exchange-051"},{"speaker":"高星委員","kind":"意見","question":"今中島委員のところで違うような話がありましたけど、それとはまた違う、場所的にはコンクリートされちゃう話になっちゃうのかどうなのか。その辺の流れのところ、ちょっといろいろ出てくると思うんですが、その辺のところとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"高星委員","kind":"質問","question":"今までの流れからしても、第二日野小学校のところに日野中学校が一緒にされるということがある種の大前提になってきちゃうということになっちゃう。当然具体的な第二日野小学校の土地を取得するというような話も予算委員会の中で出ているわけですから、ちょっとそこだけ聞いて終わりたいと思います。","respondent":"鷹倉庶務課長","answer":"敷地の問題、その辺のところを勘案しながら、いろいろ支度補償金などをやっていかなきゃいけないのかなということです。来年実施設計ですので、開校は平成１８年度ということになってありますので、このように考えてあります。","id":"exchange-053"},{"speaker":"高星委員","kind":"質問","question":"まとめますと言っているわけですから。その辺の動きはどうなの。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"石田委員","kind":"確認","question":"再度確認をしたいんだけれども、各学校、いろいろなところで特色があるわけですよね。スポーツをやったり、そこのところをまずスタートで、これだけちょっと確認をしたい。","respondent":"指田教育次長","answer":"今、石田委員から言われましたように、特色ある学校づくりのメニューの一貫であるということは明確であります。","id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/547087?Template=document&Id=4440#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":77612,"voices":171}},{"id":"h14-20020610-7","meetingId":"h14-cm06","date":"2002年6月10日","dateIso":"2002-06-10","committee":"厚生委員会","time":"午後１時０４分～午後４時５０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"築舘委員","kind":"意見","question":"それから、１１２ページの、社会福祉協議会ですけれども、理事会が１５名でなっているということで、これはどういうメンバーがなっているのか。ほかの方で常勤職員というふうに出ていますけれども、区からの職員の派遣の方がいるのかどうか、その辺のことをご説明くださいとの意見を述べました。","respondent":"高橋福祉事業部副参事、金子保育課長","answer":"私のほうから、理事会のメンバーと、派遣職員のことで説明をします。成年後見センターに一般職員１名、成年後見センターの係長に１名で、全部で４名です。 家庭福祉員についてのお尋ねですけれども、単価は、このほか運営費補助等々若干の金額を補助しています。年度の後半で３人入っていましたので、１年間で２０人程度の実績というふうに考えているところです。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと伺いたいんですけれども、先ほど未認可保育園の件で説明があったんですけれども、未認可保育園が数としてはちょっと減ってきているようです。その関係と、認証保育所との関係というのがどういうふうになっているのかお伺いしたいと思います。","respondent":"金子保育課長","answer":"ただ、いつの時点でそれを実施するかというところが、東京都も明らかにしていないところです。あるいはスペースにしても、保育の中身にしても、認証保育所への移行というのができれば支援していきたいというふうに考えております。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"今の未認可は認証保育所への移行を進めていくという基本方針だということでいいんですか。そこのところをもう一回お願いします。","respondent":"金子保育課長","answer":"今後東京都のほうで助成を打ち切るという考え方を聞いておりますので、私どもがすべて東京都の部分もかぶって助成していくという考えは持ってございませんので、できればしていただければというふうに考えているところです。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"そこのところでもう１点伺いたいんですけれども、認証保育所への移行のところで、区がどんな援助をどういうふうにしていくのか。今未認可があるのがＢ型に移行していくということを援助していくのか、そこら辺のところをどういうふうにお考えなのか、お伺いしたいと思います。","respondent":"金子保育課長","answer":"変わる段階で、例えば改修など必要とする施設があるかもしれませんが、それについては改修費についての助成をする考えは今のところございません。そういう意味では今の保育室のレベルというのを認証保育所のレベルに上げていくということに関しては支援をしていくべきだというふ…","id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問・要望","question":"もう１点、入浴券の考え方をどういうふうにしているのか、そこのところがよくわからないところがあるので教えてほしいと求めました。基準からいくと、そこら辺の考え方がどういうふうになっているのか、ちょっとお伺いしたいと思います。","respondent":"黒田生活福祉課長","answer":"２３区の中でもゼロの区も何区か出てきてございまして、その辺のところを見直していくということで、事務事業評価にも載せてあります。２３区並みになってきたですので、今後の法外援護のあり方も含めて検討をしたいということで、事務事業評価に載せてあります。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"さっき質問をした中で、今の基準からいくと、現実問題は風呂なしという感じになってしまうと思うんです。その関係で入浴券がどういうふうな位置付けで考えられているのかというのを聞いたんです。","respondent":"黒田生活福祉課長、横山委員長、新美保健高齢事業部長、田中健康課長、早津高齢福祉課長","answer":"お風呂があるなしに係わらず、都営住宅はあるというのは当然ですけれども、都営住宅でもお風呂がないところもあります。そういう中身になるのか… ほかにないようですので、福祉事業部の事務事業概要を終了いたします。次に、保健高齢事業部について一括説明を受けてまいります。 従来にも増して保健高齢事業部のほうで保健所、保健センターの全体的な連絡調整を行うという体制をとっておりますので、私のほうから説明をします。… ２４ページの真ん中からは、福祉施設等で集団給食を実施しているところに…","id":"exchange-006"},{"speaker":"山路委員","kind":"質問・要望","question":"５４ページ、どういう形で受け入れられているのか、これについてお伺いをいたします。品川区はこの件について検討をされたことがあるかどうか、その３点についてお伺いいたします。","respondent":"早津高齢福祉課長、蓼沼高齢事業課長","answer":"高齢化率ですが、全国ベースになりますと、直近のものがございませんで、平成１１年度で１７.０％です。市町村レベルで言えば、かなり高齢化が進んでいるところがあるかと思うんですが… 品川区の視覚障害者協会に委託をしてございまして、その団体から派遣をしていただいております。東品川シルバーセンターにおきましては毎週火曜日、その他のシルバーセンターにつきましては月１回というペースで実施をしています。","id":"exchange-007"},{"speaker":"山路委員","kind":"質問・要望","question":"３年前に小樽に行きましたら、その当時で２２％から２４％という、あるいは高い自治体ぐらいは研究をしておってほしいと求めました。お金を取るということになったら、どういうふうになるのか、その辺の見解をお聞かせほしいと求めました。","respondent":"新美保健高齢事業部長","answer":"シルバーセンター事業全体をどうするかということに係わってまいりますので、そういう意味では、今直ちに云々というふうな形にはならないかと思います。","id":"exchange-008"},{"speaker":"築舘委員","kind":"質問","question":"そして医師会、そういった形の人たちが出てきているかどうかということも含めて質問をしているわけですけれども、その点をお願いしたいと思います。福祉人材の育成拠点ですから、逆指名じゃないんですけれども、そういう部分があるのかどうかということをお聞きしたいと思います。","respondent":"田中健康課長、早津高齢福祉課長","answer":"２１ページの下にあります推進委員、栄養士会、体育指導員等々も入っていただいてあります。年齢的にも、３０歳からの方で構成して、幅広い層に受け入れていただけるような実践的なものをつくりたいということで考えてあります。 その辺につきましては、聞いた範囲で申しますと、各法人が研修費用というような形でご負担されているというように聞いてあります。それはケアマネージャーコースで、ヘルパーにつきましては、しているところと…","id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"高齢者のほうの２８ページのところで、この表を見ていてもよくわからないので教えてほしいんですけれども、そこのところがまず１点。これは平成１１年度までは措置開始ですけれども、入所開始が２０９人、そこら辺のところを教えてほしいと求めました。","respondent":"早津高齢福祉課長","answer":"入所開始というものは、平成１３年度１年間で入所された方の人数が２０９名です。今時点で何人かというのは、ちょっと承知しておりませんが、大体そういうことです。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"確認","question":"いろいろな事情があって取り下げになったんだけれども、本人のほうの当初申し込んでいたのは４５８人足す１５１人ということになるわけですか。ちょっとそこら辺のところをお伺いしたいのと、それとも３月の調整会議をやったとき、その日にちをお伺いしたい。","respondent":"早津高齢福祉課長","answer":"取り下げの方ですが、説明が混乱していて申し訳ございません。介護する人がいなくなったりしたような場合には、別途緊急の入所措置を行ってありますので、必要な対応はできているというふうに考えてあります。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ここにも、今の説明でもそういうふうな説明だったんですが、そこの基準というのをどういうふうにつくっているのかというのがよくわからないんです。どこで、どういうふうに、どんな基準でやるのかというところを教えてほしいと求めました。","respondent":"早津高齢福祉課長","answer":"在宅がこれ以上難しいということを、本人の状態のほかに、家族の状態も総合的に考えて点数化をして判定をしております。そのほかに在宅での介護期間がどのぐらいあるかというような事柄を総合的に判定しているです。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問・要望","question":"判断の基準がよく見えないというか、そんな感じなので、そこのところをお聞きしたい。もう一つ、推進委員会を５回ぐらいやっていって、いつ頃にどういうふうな内容を決めていくかというのが分かったら教えてほしいと求めました。","respondent":"早津高齢福祉課長、高橋介護保険担当課長","answer":"特別養護老人ホームの施設長の代表者が２人、在宅を承知しております支援センターの代表者が２人というメンバーで構成をしております。私どもの支援センターの職員と、先ほど申し上げました基準に基づいて点数化をして… 今年度は５回ほど予定しているという中で、いろいろな検討で、介護保険料について検討をしていくことになっております。厚生委員会におきまして、随時皆様にご報告しながら進めていきたい部分がありますので…","id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問・要望","question":"確認しておきたいんですけれども、何点になったら入れるとか、そういう考え方というのは何かあるんですか。ケアプランの作成件数が今どうなっていて、そこら辺のところの変化がどういうふうになるのか、ここのところも併せて伺えればと思います。","respondent":"早津高齢福祉課長、新美保健高齢事業部長","answer":"概ね５０件ぐらいということが基準として示されており、私どももそういうような形で運営をしているです。各法人、支援センターの事業者が増員をしておりまして、大体５０件程度というふうに理解しております。 制度推進委員会の今年度の予定ですが、２月で予定しておりますけれども、現在の年間の進め方の予定では。１１月は来期の介護サービス量の見込みもある程度は立てないと予算編成等々できませんので、２月には来期のテーマ、そうしますと。","id":"exchange-014"},{"speaker":"須藤委員","kind":"意見","question":"それから、５１ページの高齢者クラブの指導者研修会が平成１４年度から連合会の主催事業になったということですが、これはどういう理由なのか。費用は出しますけれども、向こうの事業にしたよということなのか、その辺を説明を求めました。","respondent":"早津高齢福祉課長、蓼沼高齢事業課長","answer":"実際に訪問リハビリを受けていらっしゃる方が１４４名、週１回が基本だと思いますので、月４５６人の方が訪問リハビリを受けているです。６０ページの、各鉄道事業者と協議をしながら… 高齢者クラブ指導者研修会につきましては、従来からあります予算額と同額のものを補助する形で品川区高齢者クラブ連合会の主催事業とするというものです。","id":"exchange-015","title":"議員研修会の内容と所要時間"},{"speaker":"宮崎委員","kind":"質問","question":"５８ページの高齢者借上げ住宅のところで、先ほど訂正で、平成１３年、平成１２年、平成１１年の実績が全部０というふうになっていたんですけれども、ずっと０かなと思うんですけれども、最後の実績があったのはいつ頃なのか、そこのところをお伺いしたいと思います。","respondent":"蓼沼高齢事業課長","answer":"平成８年度が実績としては最後になってあります。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問・要望","question":"要望と制度が合っていないのかなという感じがするところがあるんですけれども、住宅マスタープランとの関係で基本的な考え方だけ伺っておきたいんですけれども、そこら辺の考え方というのはどんなものか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"基本的には現在設置しております２２０戸を活用していくということで考えてございまして、もう一つの住宅あっ旋制度がありますけれども、こちらのほうの活性化をして、今後住宅運営を進めていきたいというふうに考えてあります。","id":"exchange-017"},{"speaker":"辻副委員長","kind":"確認","question":"確認しておきたいんですけれども、成人歯科健診で２４６カ所というのは、上のほうで区民健診のほうの病院にも同じことを契約している。輸血などを受けた方に対する、どういう体制で進まれているのか、ちょっと確認しておきたいと思います。","respondent":"田中健康課長、小林品川区保健所保健サービス課長","answer":"今回区民健診の中に取り込んでという厚生労働省のほうの枠組みの指示の中で４月から実施を目指して、現在検討の詰めに入っているところです。老健法の４０歳以上の方ですので、現在も保健所… 感染症予防の定点疾患についてのご説明ですけれども、四類の中で全疾患届出するものと、定点で届出するものと二つに分かれております。２年生で追加のＢＣＧを行っておりますけれども、４歳までに行うＢＣＧは効果があるけれども…","id":"exchange-018"},{"speaker":"辻副委員長","kind":"質問","question":"これも全部ここで言う許可、登録というのが入ってしまうことなんですか。毒・劇物の販売業に関しては、これはどういうものを扱っているのか尋ねました。","respondent":"島袋品川区保健所衛生課長","answer":"砒素とか、こういうものを取り扱っているところにつきましては、届出をしてもらうということです。ドラッグストアの定義ですが、大きいドラッグストアは区のほうの許可に入ります。","id":"exchange-019"}]},{"id":"topic-02","title":"続きまして、報告事項の(1)「品川区地域福祉計画」の策定","agenda":"続きまして、報告事項の(1)「品川区地域福祉計画」の策定","exchanges":[{"speaker":"金高委員","kind":"質問・要望","question":"裏面の構成ですけれども、ＮＰＯ１名となっておりますけれども、実際に品川区内で福祉・医療関係団体のＮＰＯというのはどういう団体が、何団体ぐらいあるか、その辺のところを教えてほしいと求めました。","respondent":"日下部障害者福祉課長","answer":"私ども調べましたところ、ＮＰＯと言っても、かなり幅が広くて、福祉関係で申し上げますと、以前確認しましたところでは２０団体ぐらいあります。私どもは今回計画の策定ですので、当然のことながら、それ相応の実績を持っている団体にご参画をいただくということで考えておりま…","id":"exchange-020"},{"speaker":"金高委員","kind":"質問・要望","question":"なおかつＮＰＯの法人格を取って活動してきているという団体に、１名ということでありますので、ぜひ絞り込んでいただければというふうに考えます。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと伺いたいんですけれども、ここで７団体で１名というのは、ちょっと少ないんじゃないかなという感じがするんです。そうなると、精神障害者の方の意見というのがどういうふうに反映されるのかというところが心配なんですけれども、そこのところはどうなんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"委員会の構成ですけれども、実は私ども事務局ということで、この委員会の構成を具体的に検討するにあたって相当悩みました。この辺のところにつきましては、精神障害者のご意向についても最大限反映できるように、できる限りの努力はしてまいりたいと考えております。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"意見","question":"ここで見ると、精神障害者の方の意見がどうなるかと心配だったんですけれども、そこの選抜方法というのはどういうふうな考え方でやっていくのか。そういうところの委員会の公開はどういうふうに考えているのか、そこのところも併せてお願いしたいと思いますとの意見を述べました。","respondent":"日下部障害者福祉課長","answer":"そういうものを提出していただいて、それに基づいて選考をする、このように考えております。私どもは実際には７月開催ということで考えておりますので、その辺の具体策については、今後詰めてまいりたいと考えております。","id":"exchange-023"},{"speaker":"築舘委員","kind":"質問","question":"社会福祉協議会がやっているふれあいサポート計画ですか、地域福祉区民活動計画というのがありますね。障害者福祉がやっているということですから、そういうことの理解での地域福祉だというふうに解釈しているんですけれども、それでよろしいのかどうか。","respondent":"日下部障害者福祉課長","answer":"国なり東京都が考えておりますのは、これは行政と住民がどうやって一緒になって地域の福祉を進めていくか、行政がつくる計画です。私どもは障害者福祉課ということですが、福祉事業部のいろいろな取りまとめをしておりますセクションということで、事務局の一端を担っているです。","id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問","question":"地域福祉計画は、この支援費制度を受けての計画になるんですか。そこの関係がどうなのか。","respondent":"日下部障害者福祉課長","answer":"相談体制の構築とか、そういうことで、大きな社会福祉の仕組みの転換を反映させた中身になってくるということです。個別障害者福祉の支援費制度について、当然のことながら、その辺の中身もある程度反映した中身になっておるです。","id":"exchange-025"},{"speaker":"宮崎委員","kind":"質問","question":"年４回程度の委員会だというふうになっていますけれども、年４回で、大分大きな変更になるわけですよね。そのところがちょっと心配なんですけれども、どんなものか尋ねました。","respondent":"日下部障害者福祉課長、小沼福祉事業部長","answer":"かなりの実績がありますから、それをベースにして検討していくということで、それはそれ相応に十分な議論を尽くせるんじゃないかと考えております。障害者の福祉に関する具体的な計画… 系列から追ってまいりますと、平成１２年、今回の地域福祉計画というのが出発する中身のものです。７月中ぐらいを目処に何らかのものを国としては出したいというようなことですので、適宜にご報告をさせていただければと考えています。","id":"exchange-026"}]},{"id":"topic-03","title":"報告の２番目、食品香料会社（本社・品川区）への調査","agenda":"報告の２番目、食品香料会社（本社・品川区）への調査","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"保育園のところで、満足度調査というのをやったというふうにちらっと聞いたんですけれども、やっていたのかどうなのか。やっていたら、報告をお願いしたいなと思っているんですけれども、そこら辺のところはどうか尋ねました。","respondent":"金子保育課長","answer":"昨年の１２月に実施しました第三者評価のうちの利用者満足度調査の件だろうと考えておりますが、委員会に提出するように準備作業中ですので、早ければ次回の委員会にはご報告できるのではないかと考えているところです。","id":"exchange-027"},{"speaker":"横山委員長","kind":"質問・要望","question":"委員会運営について、委員会からも報告を求めていくような、今後委員会の終わりにそれぞれからそういったご要望があるかないかお尋ねしていきたいと。○午後４時５０分閉会。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/534819?Template=document&Id=3020#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":59726,"voices":147}},{"id":"h14-20020610-8","meetingId":"h14-cm06","date":"2002年6月10日","dateIso":"2002-06-10","committee":"建設委員会","time":"午後１時０６分～午後４時３０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本間委員","kind":"意見","question":"民主党区民連合の本間隆です。どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]},{"id":"topic-02","title":"２の事務事業概要","agenda":"２の事務事業概要","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"１つに、この文章だと読み取れるんですけども、ちょっとその辺の基本的なところを教えてほしいと求めました。よくある「タイム２４」とか、また別の形なのか、ちょっとここだけ教えてほしいと求めました。","respondent":"岩田管理工事課長、奈良交通安全担当課長","answer":"こういったものについては、順次、交渉しながら払い下げていくという方針です。払い下げを受けない方につきましては、きちっとした占用手続をとっていただいて、適正に利用していただくということを順次進めてまいります。 あるいは駐車台数が２０台以上の、いわゆる１時間お幾らとか、そういった融資の対象になるです。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"ああいう「タイム２４」とか、これ、区のものではないですよね。国の制度なのか都の制度なのかはよくわかりませんけれども、この制度が出てきた背景みたいなのがわかりましたら教えていただければと。","respondent":"岩田管理工事課長","answer":"当時から比べればぐっと減ってまいりまして、今、担当課長会等でも今後十分検討していこうというようになっているところです。残念ながらないということです。","id":"exchange-003"},{"speaker":"堺委員","kind":"質問・要望","question":"ちょっと２点ほど確認をさせていただきたいんですけども、６月に完成ですか、今度１１月ごろまでには現状復旧というんですかね。順調に工事が進んでいるやにご説明いただいたかと思うんですが、その辺のことを確認しておきます。","respondent":"中谷まちづくり事業部長、田村住宅課長","answer":"私のほうから、１点目の、西品川雨水調整池工事につきまして、状況をご説明申し上げます。当初の予定ですと、平成１４年度に公園の復旧工事という予定でございましたが、工事が遅延しております。 宅建側のほうも検討していまして、今年の４月から、現実的には品川宅建管理センターという新会社を昨年の１１月につくりました。今年の４月から、新たな宅建センターが委託を受けて、今年の４月から実施していると。","id":"exchange-004"},{"speaker":"堺委員","kind":"質問","question":"戸越センターですか、募集の要項の下のほうに、相談や何かも受け付けますというふうに書いてありますよね。そこのところですか、これは。","respondent":"田村住宅課長","answer":"申し込みのしおりに、問い合わせ先にも株式会社品川宅建管理センターということで、これが、先ほど申し上げた新会社です。","id":"exchange-005"},{"speaker":"堺委員","kind":"質問","question":"行くんですか、行っているんですか、行っていないんですか。その辺のことはどうなっているんか尋ねました。","respondent":"田村住宅課長","answer":"ただし、その団体の設立のための出資金だとか、そういうものは、一切区のほうからは出しておりません。独自に宅建品川支部のほうで、株式会社にする資本金で、そちらの独自の財源で会社を設立したというふうに聞いております。","id":"exchange-006"},{"speaker":"堺委員","kind":"質問","question":"直接今までやってきた管理業務というのはなくなってしまって、あるいは区とその宅建業者、新しくつくった会社との契約というのはないんですか。その辺の関係説明はどういうふうになってくるんか尋ねました。","respondent":"田村住宅課長","answer":"あるいは滞納の強制執行だとか、自治体が必ずやらなきゃならない業務というのは委託はできませんので、それは当然区のほうに残ります。品川区と品川都市整備公社が契約して、それで品川都市整備公社が宅建センターと契約して、実際に宅建センターが動くという形になっていくです。","id":"exchange-007"},{"speaker":"堺委員","kind":"質問","question":"そうすると、そうすると、区営住宅は委託しないんですか。区営住宅は従来どおり住宅課のほうでやっていくということになるんか尋ねました。","respondent":"田村住宅課長","answer":"区民住宅のほうを先行してやらせてほしいということで、実際に区営住宅については、直営で今までどおり実施するという形になります。それは現行と変わらないです。","id":"exchange-008"},{"speaker":"堺委員","kind":"意見","question":"だけど、まだそれはいかないので区営住宅はこちらでやるんだという、さっき「当面」と言っていた。こうおっしゃったのでとの意見を述べました。","respondent":"田村住宅課長","answer":"区民住宅と区営住宅とは同じ扱いになりますので、区民住宅が委託できて区営住宅ができないというような法律的な解釈ではないということで……。当面、区民住宅について民間活用を図りたいということで今交渉している最中です。","id":"exchange-009"},{"speaker":"堺委員","kind":"確認","question":"こういうことについては、やはりそういう民間活力というんですかね、そちらのほうに形づけれるようになっていけばいいなと。それを確認の意味でお尋ねいたしました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここに載っている予算は用地買収の予算なんでしょうか。今後の予定とか地元の説明会だとか、わかっていたら教えてほしいと求めました。","respondent":"中谷まちづくり事業部長、岩田管理工事課長","answer":"品川公園の調整池関係の工事の今後の予定ですが、道路公園課長からご説明しましたとおり、舗装の全面復旧という形になります。よくこの辺、調整をしながら工事を進めまして… まだ完全に話がついているわけではございませんので、確定した段階で、地域の方に説明会等の形で入っていきたいと思います。一部近隣マンションから、区としては…","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"町会の皆さんは本当に場所があったら公園にしてほしいと、騒音の問題は伺っていなかったんですが、すごい緑豊かですよね。その辺の点検とか、安全の管理はどうされているのか、その２つ。","respondent":"松代道路公園課長","answer":"主に桜等は非常に、下へ根が張れないというような場合は、どうしても横へ伸びてまいります。日々成長していますので、陳情等があれば、その陳情等に合わせて対応してまいるというようなこともとってあります。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問","question":"ちょっと済みません、忘れていました。いつごろからやるとかというのは、ある程度固まっているのかと思うんですけども、その辺を少し教えてほしいと求めました。","respondent":"田村住宅課長","answer":"既に予算特別委員会でもお答えしたんですけど、一定の聞かなきゃならない項目という、必要項目は決まっています。７月早々に内容等調査し、年度内にまとめるということでやっていきたいと思います。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"予算特別委員会のときにちょっと質問させていただいたんですが、その後の進捗状況は今委員会で報告して検討できるのかどうか、資料とかもここでいただけるのかどうかということを。","respondent":"中島街路事業担当課長","answer":"まちづくり特別委員会の調査項目につきましては、３２５号線ですので、目黒線の連続立体事業につきましては本委員会で調査ということになってありますので、この事業に関する内容につきましては当委員会でということになります。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"意見","question":"ということは、この間の予算特別委員会で聞いた以降の、例えば駅前広場の、ここに地図が載っていますけども、今後の建設委員会の中で、あと線路が地下化になった上部の利用とか、高架の下の利用とか、そういう部分で出ている図面とかはいただけますかとの意見を述べました。","respondent":"中島街路事業担当課長","answer":"補助３２０号線の整備事業ということになってありますので、ちょっと、連立事業につきましては建設委員会ということで分かれております。ただ、お互いにふくそうしているものもありますので、状況に応じてその辺はご報告させていただきたいということを考えております。","id":"exchange-015"},{"speaker":"林（和）副委員長","kind":"意見","question":"もう３０年ぐらい前は、２３区の中でも後ろから２、３番目だったように思うんですね。２３区でどの程度のぐらいまで上がっているのか、この比率の中に入ってくるのかどうか、その点をちょっと説明を求めました。","respondent":"松代道路公園課長","answer":"今度１０月１日の施行を見て、今後の助成等の活用をしていただければ、それが具体的な数字となってあらわれてこようかと思います。今まで進めてまいりました地上部での緑化、また屋上緑化も含めて努力をしてまいりたいと、このように考えておるところです。","id":"exchange-016"},{"speaker":"船波委員","kind":"質問","question":"利用料金の当日利用が１５０円ということになっていますけれども、この開設時間を見ると、午前０時を挟んで３０分間開かれているわけですけど、その０時を超えてしまった３０分間の間に取り出したりした場合でも、この５時１５分から２４時３０分までの間なら１日という換算なんか尋ねました。","respondent":"奈良交通安全担当課長","answer":"いわゆる駐輪してから２４時間１５０円ですので、それ以降になりますと、また別料金になりますけども、駐輪してから２４時間が１５０円です。","id":"exchange-017"},{"speaker":"船波委員","kind":"質問","question":"学割を設定してほしいとか、あるいはもっと防犯に気をつけてほしいというような項目が含まれた請願が出されたと思いますけれども、利用する人の種類によって料金の設定を割り引くというようなことはあるんか尋ねました。","respondent":"奈良交通安全担当課長","answer":"ことし１０月にオープンする予定の５駅９カ所につきましても、おおむね歩いて１０分ぐらいで最寄りの駅に行ける、いわゆる学割についての制度については考えておりません。","id":"exchange-018"},{"speaker":"田中委員","kind":"確認","question":"将来５２０台ということですが、構造上埋め戻しした場所ですから、既存のスペースでこの５２０台まで対応できるのかどうかということの確認をお聞きします。","respondent":"岩田管理工事課長、奈良交通安全担当課長","answer":"これは、私どもの駐輪場で初めて地下式の駐輪場になりますので、これに引き続いて１２月にはシーサイド駅にも同じような地下駐輪場ができる予定です。ご指摘の不測の火災とか、警備会社がすぐ… これを１６０台分確保しておりまして、５２０台に増やす分には、現在の４７３平米の中で５２０台分確保できるです。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"目黒駅のＪＲと東急のところですか、バイクは２００円ということで、これはまずいんではないかなと。この辺の５駅９カ所の、１０月１日までどう進むのか教えてほしいのと、説明会をしていただきたいなと思うんですけど。","respondent":"奈良交通安全担当課長","answer":"１点目の、３０分とめても２４時間とめても１５０円ということで、決して１５０円は高くないというふうには考えております。いわゆる利用者に対する説明というご指摘ですけども、６月２１日号で一応ご案内はしますけども、８月２１日号で詳しく区民に周知徹底を図る予定です。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"当日で１００円なんですけれども、１時間未満は無料とか、その辺は十分検討をしていただきたいなと思います。区民にかかわることなんでね、いつからどう駐輪場に入るのかということもぜひ知りたいと思うので、その辺もぜひ確認してほしいと求めました。","respondent":"奈良交通安全担当課長","answer":"１０月１日からスタートをする予定です。それぞれ利用者につきましては、いわゆるチラシの配布、あるいは地域センター等で説明をいたします。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"説明会はぜひ実現をしてほしいと求めました。７月から工事ということなんで、ぜひこの９カ所の図面をいただきたいんですけれども。","respondent":"中谷まちづくり事業部長","answer":"店の利用との兼用のところについてはそういうような形で進めますが、百貨店等に１０月１日から設置義務を課しまして、ご理解いただきたいと思います。説明会ですが、ＰＲする予定ですので…","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"なかなか理解できないことなんですが、利用料につきましては。特にお知らせの方法というか、一般的なことだけじゃなくて、駐輪場にわかりやすく表示をしていただくというのはいかがか尋ねました。","respondent":"岩田管理工事課長","answer":"１カ月前にやりますので、若干前から現地の予定地には看板をつけまして、これこれこういうふうになりますと。と同時に、２週間ぐらいやるんですかね、コンピューターのホームページでもそういうお知らせをできるだけ早く行うような形で周知を図ってまいります。","id":"exchange-023"},{"speaker":"堺委員","kind":"質問・要望","question":"２回にかけて掲載ということですが、聞く人が納得するような形での周知方法というんですかね、できれば周知したいなという気がするんです。今までそこを使っていた人たちはそこが使えないわけですから、戸越銀座を含めまして、そのところはどういうふうにお考えになっているのかですね。","respondent":"奈良交通安全担当課長","answer":"区としてはその代替地については今のところは考えておりませんけども、夏休み期間中に合わせて実施工事を行いますので、そういうふうには現在思っております。","id":"exchange-024"},{"speaker":"堺委員","kind":"質問","question":"あの山手線の線路に沿ったところですかね、心配な点ですので、ちょっとその辺もお願いしておきたいなと。だから、チラシ、看板等でやるということですから、そのところに触れておいたほうが僕はいいような気がするんですがね、その辺いかがか尋ねました。","respondent":"奈良交通安全担当課長","answer":"今、自転車駐輪場の工事の関係ですけども、これは、先ほど私の説明が不十分でございました。いわゆる１カ所の駐輪場につきまして一気に工事をするわけではございませんので、徐々に工事をやっていきますので、十分それで対応できるだろうです。","id":"exchange-025"},{"speaker":"堺委員","kind":"質問・要望","question":"それから完成の暁には、その点で申し上げているわけで、ぜひひとつそういう方向で取り組んでいただきたいということを申し上げて終わりにします。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"菊地委員","kind":"質問・要望","question":"どういう基準でこれが決まっていくのかをちょっと教えていただきたいのと、先ほど部長、管理費が１億円近くかかるという話でしたよね。先ほど、自分のところのお客さんが主体的に利用するところに対する事業者の実質的な援助というのはどういう形で、その辺のところをお聞かせ願えれば。","respondent":"岩田管理工事課長、中谷まちづくり事業部長","answer":"区が設置をお願いした中に、鉄道事業者みずからが駐輪施設を設置する方向を、今東急側は考えてくれるようになりました。それは、もう強固な問題ですが… 共同で設置して、まず共同で設置して、荏原町等の駐輪場につきましては区のほうに移管されるというはずです。そういうことで、これ、なっておりまして、あと区営につきましては、それら設置できないところにつきましては、区が…","id":"exchange-027"},{"speaker":"本間委員","kind":"質問・要望","question":"７月７日からそういう事業をやるんだから待ってくれと言うわけにいかず、どうも東京都が、品川区の管理責任だという言い方を繰り返しています。この件につきまして、ご見解と今後の対策について、大変大きな問題といいますか、難しい問題かもしれませんが、ご意見をほしいと求めました。","respondent":"中谷まちづくり事業部長","answer":"これができますと、３倍までの対応ができ、なおかつ放流した水が５０ミリまでは立会川から出て来ないということになります。いろんなパターンを検討いたしまして、できるだけ早く整備をしてくれ、占用許可をしてこの放流を許可しているということがあるんじゃないですか。","id":"exchange-028"},{"speaker":"本間委員","kind":"質問・要望","question":"対応が早いねというふうなことがあったものですから、区民の要望、あるいは対応されるようにお願いします。私たちも、私たちの立場で一生懸命やってみたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"林（和）副委員長","kind":"質問・要望","question":"ということは、これがあってから急遽これをやるということに決めたんですか。せっかくある施設でございましたのに、なぜ５月３１日からやったのか、その前からなぜやらなかったのか。","respondent":"中谷まちづくり事業部長","answer":"それから、今後の対応ですが、先ほど、私、ご説明申し上げましたが、今年についてはいろんなパターンで検討しています。こういうパターンで検討して、恒久的なものにするには、またかなりのお金がかかります。","id":"exchange-030"},{"speaker":"林（和）副委員長","kind":"質問","question":"それから、１１時ごろからＪＲ導水の式典をやるというふうに案が書かれておりますけれども、これはどういうふうなあれなんですか。もう少し具体的に。","respondent":"中谷まちづくり事業部長","answer":"ＪＲ側についても、この時期にできるかどうかわからないと言っておりましたが、これは、１週間ほど前にやっと「７月７日には何とか放水できます。なおかつ強固なものになるんではないかと、こういうことで、今回このようなセッティングをさせていただいたわけです。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"１点だけ質問したいんですが、別の視点で考えているんですが、勝島運河に汚れた水が流れるということになるわけですよね。では水質が汚いということが起き得ますので、その点の確認を、お考えをお聞かせほしいと求めました。","respondent":"中谷まちづくり事業部長","answer":"５,０００立米といえども、あるとき一瞬だけを考えますと、勝島運河の恒久対策にもなるのではないかです。あるいは東品川ポンプ場で勝島運河に直接放流されたのが今度なくなりますので、そういう意味では、かなりきれいになるというふうに考えております。","id":"exchange-032"},{"speaker":"菊地委員","kind":"質問","question":"以前にお聞きしたのは、どこかに機器を設置して常時はかっていくようなものなのかどうかというところをお聞きしたいのと、わかる範囲で教えてほしいと求めました。","respondent":"中谷まちづくり事業部長","answer":"今の計画は、下水道計画がすべて終わりますと、５０ミリの雨以外は月見橋からの越流がなくなります。約１０年かかりますが、水門工事をその後東京都建設局が行い、都と区で一応合意している内容です。","id":"exchange-033"},{"speaker":"菊地委員","kind":"質問","question":"今の計器の測定の話なんですけれども、例えば、この水を流している期間中ずっと設置をしていくという方式というのは考えられないんでしょうかね。そういう中で、区民のどなたか責任者をつくって測定というか、聞いていくというような形というのは考えづらいものなんか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"環境測定の専門業者が行いまして、専門業者がその都度、利用の都度持ってきてやると。５月３１日から委託はもう開始しておりますので、常時設置するだけの費用、そういうものを見込んでおりませんので。","id":"exchange-034"},{"speaker":"堺委員","kind":"質問","question":"どうしてもその道路の拡幅事業に伴って立ち退かざるを得ないとき、公的住宅にあっせんするというんですかね、優先的にお入りいただくというんですか。行き先がないという不安を解消するというんでしょうかね、そういう優先的に入っていただくというんですかね、その辺はいかがなんか尋ねました。","respondent":"田村住宅課長","answer":"まちづくり事業の中で、同じようなまちづくり事業、道路事業の所管課と調整しています。今の時点では、所管と調整して、３戸程度を１３２戸の中で事業用として確保していくという考え方で調整を進めております。","id":"exchange-035"},{"speaker":"堺委員","kind":"質問・要望","question":"なおかつこっちは新たに区営住宅ですから、できれば一本橋通りのそういう方々への移転先の確保の場所というんですかね、それはいかがでしょうか。ぜひそういう方向で取り組んでいただきたいなと、そんな気もするのですが、その辺はいかがなんか尋ねました。","respondent":"田村住宅課長","answer":"平成１６年４月が竣工という形になりますので、まだ若干期間がありますけど、やはりまちづくり事業と連携をとりながら進めていきたいと思います。","id":"exchange-036"},{"speaker":"堺委員","kind":"意見","question":"その可能性があるならばという思いでお尋ねをした中で、今後そういうことがあるのかどうかわかりませんが、こんなふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"菊地委員","kind":"質問・要望","question":"最近の、直近のところでの都営住宅、区営住宅の倍率を教えていただきたいのと、それと、さっきのお話では、都営住宅を区営住宅として新しく建てたということなんですけども、こういう計画がされているところが、ほかには区内にあるのかどうか、ちょっとその辺を教えてほしいと求めました。","respondent":"田村住宅課長","answer":"４２.８倍、八潮が３０.７倍、西五反田が８４.３倍というような募集状況です。それと、２点目の建て替えについては同じような形でということですが、現在、予定は、今協議されました西大井六丁目の区営住宅です。","id":"exchange-038"},{"speaker":"菊地委員","kind":"質問","question":"入居できる安い家賃の住宅というのが建設されるべきだろうというふうに思うんですけれども、できるような条件であるところというのはないんだろうか。１００戸程度のところで、あわせればもう少し戸数を設けられるんじゃないかというような場所というのがあるんであれば教えてほしいと求めました。","respondent":"田村住宅課長","answer":"先ほどもご説明したように、建て替え等の予定で、ちょっと今想定でお話ができないので……。品川区もそれに合わせて、このたびそういう適正管理を現在も進めていますけども、さらに進めていく必要があると思います。","id":"exchange-039"},{"speaker":"北野委員長","kind":"質問・要望","question":"次回７月２日の委員会で、視察先などについて委員の皆様からのご意見をお出しほしいと求めましたので、よろしくお願いいたします。○午後４時３０分閉会。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/807981?Template=document&Id=3724#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":63807,"voices":167}},{"id":"h14-20020610-5","meetingId":"h14-cm06","date":"2002年6月10日","dateIso":"2002-06-10","committee":"総務委員会","time":"午後１時０３分～午後４時２５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件整理しています。","topics":[{"id":"topic-01","title":"番の幹部職員紹介","agenda":"番の幹部職員紹介","exchanges":[{"speaker":"桜井委員","kind":"提案","question":"公債の行き先というんですか、取り決めがあってやるんだと思うんですけれども、それについて質問したいのが１点。区への影響というんでしょうか、どういうふうになっているのか、ご説明ほしいと求めました。","respondent":"市岡企画財政課長、小野（弘）副収入役、南監査委員事務局長","answer":"特にご説明する必要があるのは、いわゆる縁故債、ご指摘のとおりみずほ銀行が引き受けたものです。縁故債であって、公募債でないということは… この２点が、区への影響です。１日の口座引き落とし分については１９万１,９００円ほど、２４万７６８円プラス、準備を進めているところです。 平成１３年度当初から、いわゆる公認会計士が通常監査をする手法を大幅に取り入れた監査を実施いたしまして、そういう詳細な報告をいたしました。…","id":"exchange-001"},{"speaker":"桜井委員","kind":"確認","question":"一たんみずほ銀行に行っているわけですから、そこと品川文化振興事業団との関係で、毎年０.６％ずつ５年間にわたって利益を受けると。そこだけ確認しておきます。","respondent":"南監査委員事務局長、市岡企画財政課長","answer":"２点だと思いますが、監査の結果の公表につきましては、監査委員の合議に基づきまして決定された報告書を公表する。１３年度、場合によっては平成１１年度、３カ年間分ぐらいはさかのぼって見するというようにしております。 法律上の償還をしていくわけであって、相手がだれだからということは、法律では決められておりません。全く知らなかったわけではありませんで、そういう譲り渡しが行われるということで…","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問","question":"概要説明ですから、簡潔にいたします。区と品川文化振興事業団との関係が、今までの経緯がありますから、もう少し何らかの形になるかなと、ちょっと意見を持っているところです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"お一人の方がやれるものなんですか。企画と財政と相談をしながらやっていくというのが熟してきたときに、今の組織で平気なんですかという、そういう聞き方をしたい。","respondent":"市岡企画財政課長","answer":"私は、今、むしろその中で培ったノウハウを政策展開という前向きのほうに使う時代としてはふさわしいのかなと思っています。こんな形で進めておりますので、こういうところに「財政担当と連携して」という言葉が出ておりますが、そういう趣旨です。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"もう１点、財調についての東京都との掛け合いだとか、２３区でのいろいろな話し合いという中でどうなのかなという気がする。東京都と財調調整の交渉の場があるわけですから、企画担当と財政担当が兼ねているということでのメリット、デメリットというのはあるんか尋ねました。","respondent":"市岡企画財政課長","answer":"政策担当課長も含めて、財調が、昔で言う予算とプロパーの仕事ではなくなってきているかなと思います。我々のいき方の一つの選択としては、有効かなと思っています。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"品川区だけでどうこうできない、そういうところにきちんと対応をしてほしいと求めましたので、お願いしておきます。それから、順番でいくと、収入役室のみずほ銀行関係なんですけれども、さっき説明があったんで、一応、確認しておきます。","respondent":"野田口選挙管理委員会事務局長","answer":"ただ、例外が１回だけあります。そういった意味では、年内の暮れぐらいから準備があるということで、そういう点での準備をしています。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"厳密に言えば違反になるようなものについても、今年度に限ってはいろいろ仕事ができそうなもので、ぜひお願いをしておきます。もう１点、電子自治体のランクは、品川区は何位ぐらいだったんか尋ねました。","respondent":"田中情報システム課長","answer":"市政をしいている自治体がたしか６８８で、それに２３区を入れるんですが、そのうち６８位です。５０位近くランクダウンしちゃったわけです。","id":"exchange-007"},{"speaker":"土井委員","kind":"質問","question":"問題はその後なんですけれども、それをどう使い、どうセキュリティを保っていくか。セクションも含めて、どこでどのように考えて進めるのかということが問題だろうと思うんで、ちょっとその辺についてお考えをお聞きしたい。","respondent":"田中情報システム課長","answer":"守らなければいけない方針、ここで今、案が提示されたところです。基本的には自治体の事務ですので、そういう形で、全国の自治体でセキュリティのレベルを守るということで対応していくことになります。","id":"exchange-008"},{"speaker":"土井委員","kind":"質問","question":"そのセキュリティのレベルを、品川区としてどうやって保つのかということでの考え方みたいなものは、どうなのかということ。そのほかの情報システム課はシステムをつくるほうですから、どこが中心になって、どこがやっていくんだろうかなというのも疑問なんです。","respondent":"田中情報システム課長","answer":"２点あったかと思いますが、全国的な市区町村の運営協議会の標準的な案を受けまして、区として規定整備を行う予定です。うちで言いますと、３２万人の区民の住基のデータを使えるのは、国の法律で決めた範囲でだけしか使えないということになっております。","id":"exchange-009"},{"speaker":"土井委員","kind":"質問","question":"あるいは逆の意味で、どこかでは使わなきゃいけないんですから、どう使うのかという問題があるわけですね。防衛庁みたいなことではないはずですから、向こうは使わないということを信じているだけじゃどうしようもないわけですから、その辺を。","respondent":"田中情報システム課長","answer":"通信サーバーというのを通して、全国のデータの集まるサーバーに、この５情報だけが送られます。ということですので、住基ネット上はそういうデータは送られていない、うちのほうも出していないということで、ご理解ください。","id":"exchange-010"},{"speaker":"土井委員","kind":"意見","question":"１回、１回品川区に来て、見ちゃ嫌よということはできないシステムになっちゃうわけですね。どうセキュリティを保つかということがきちんと決められていて、はじめてオーケーとなるはずなんですけれども、その辺との兼ね合いはとの意見を述べました。","respondent":"田中情報システム課長","answer":"データですが、転入、転出、出生、死亡と日々あるものですから、それぞれの市町村の住基のシステムで年中変更されています。それから、各自治体の参加状況ですが、法律で決まった制度ですので、基本的には参加していただくということで、総務省が対応していると思います。","id":"exchange-011"},{"speaker":"土井委員","kind":"意見","question":"そういう状況ですと、ある部門でどこかで１カ所破れちゃうと、ずるずるになっちゃう代物なんですよね。ぜひ、そちらの政策的な問題でのチェックをきちんと進めた上でやっていただかなきゃならないと思いますので、意見として述べておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"桜井委員","kind":"質問・要望","question":"私もよく正確にはつかんでないんですが、これまで、どういうふうな勧奨制度というのがあったんでしょうか。例えば平成１３年度で、それに基づいて考えらる、あるいは希望されている人数とか、そういう数字を教えてほしいと求めました。","respondent":"古川総務課長、桑村人事課長","answer":"平成１３年度は９.５人。おおむね、大体、１日１０人ぐらいお預かりの実態と考えています。 平成１３年度の形ですけれども、一定の勧奨退職をしますと、勧奨退職の手当というものが決められてあります。勧奨退職とは見ることができませんので、それは普通退職でしかないということで、そこで見解が分かれているです。","id":"exchange-013"},{"speaker":"桜井委員","kind":"質問","question":"区としては、今までどういう年齢の勧奨退職というのをされていたんでしょうか。これまでの実績というか、平成１２年度の実績とか、そういうところもちょっと教えていただけませんか尋ねました。","respondent":"桑村人事課長","answer":"いわゆる定年で６０歳で辞めることはありませんので、６２歳ですとか、それによって人事の刷新を図るということを目的としておりました。その意味で、平成１３年度の判断としましては、こういったものを勧奨する必要がないという判断をして、実施しなかったです。","id":"exchange-014"},{"speaker":"桜井委員","kind":"質問・要望","question":"ちょっと思ったよりも人数的に少なかったのか、あるいは一定程度、こういう形で伸びていけば定着をしていくと見るんでしょうか。これはどういうふうな予算の振り分けというのか、１人当たり幾らといくのか、どういうふうな内容か尋ねました。","respondent":"古川総務課長","answer":"現状では７園ですから、予定されるのが７００万円でありまして、予定ではあと３園ほど拡大をということで１,０００万円の予算計上したです。おおむね１００万円を超える中で、各園ともかなり工夫をしながら、預かり保育事業については取り組んでいただいていると考えております。","id":"exchange-015"},{"speaker":"藤田委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、この中身について、ちょっと教えていただきたいということ。いろいろ言いましたけれども、その辺ちょっと教えてほしいと求めました。","respondent":"桑村人事課長、市岡企画財政課長","answer":"何年に１回という形でかえていたんですけれども、事務系の被服については、枚数が非常に少なくなっております。その意味では、ほとんどのものが保育園ですとか、保健婦ですとか、用務という方の被服になってあります。 基本的に、係長以下については私費でつくっております。デザインについては、イメージアップの関係で調整をしておりまして、品川ストライプ、あるいは図案を入れたような統一をしております。","id":"exchange-016"},{"speaker":"藤田委員","kind":"質問","question":"ないしは保健婦の長い白衣ですか、そういうものがそんなに毎年要るものなかどうか、もう少しシビアに。だれもかれもということではなくて、係長でも、いろいろな人が訪ねてきて、「あなたはだれですか」と言われれば、私費でつくっているものを出す。","respondent":"桑村人事課長、市岡企画財政課長","answer":"平成１２年度の決算ですけれども、全体で３,４００万円ぐらいかけておりますが、そのうちの２,３００万円ぐらいは清掃関係の経費です。一定の見直しが必要だと思いまして、これまでも見直しをしてきてありますので… ちょっと説明をはしょっておりましたので、簡単にご説明申し上げます。各職場、各業務に応じて、必要な身分を称するカードはつくっているとご理解をいただきたいと思います。","id":"exchange-017"},{"speaker":"藤田委員","kind":"質問・要望","question":"きのうですか、広報「しながわ」にサマールックの記事が載っていました。ご理解をいただきたいというような文面のものを、ぜひ、つくってもらいたいと要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"土井委員","kind":"質問","question":"研修の関係でお伺いしたいんですけれども、前年と変わったからということでは、派遣研修というスタイルでの研修が行われるようになったんですけれども、この辺については、どんな感じで、どういう流れなのか。","respondent":"桑村人事課長","answer":"それについても、派遣研修を切り替えて、ほんとうの研修の形だけにしていこうというような考え方を持っております。この３団体についても、一般の団体と同じような形の、まさに研修としての派遣をしております。","id":"exchange-019"},{"speaker":"嶋委員","kind":"質問・要望","question":"品川区はいつも１日ということで、いつもあわただしくて予定が立たないという感じで、分科会に出られなかったんです。１日というは大変難しく、今まで、数日間やってほしいとか要望があったのか尋ねました。","respondent":"阿部人権啓発課長","answer":"いわゆる区民の皆様が、自分たちで内容から実施まですべてやっていただいております。それをセットでやりたいというような意見がございまして、今までは土曜日１日で、午前中から午後という形でやらさせていただいているという状況です。","id":"exchange-020"},{"speaker":"嶋委員","kind":"意見","question":"新しい２１世紀になって、そういう方たちが活動する現場とか、展示とかいろいろあると思うんです。ほかの自治体との兼ね合いもあると思いますので、いいところをやっていただけたらと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"川西副委員長","kind":"質問","question":"これについて、変更されてからのメリットと、現況の流れ。それからもう一つは、設計委託などの入札関係のことは、やっぱりこの施設関係の方がおやりなっているんでしょうか、ちょっとお伺いします。","respondent":"片田施設担当課長、西島経理課長","answer":"各事業部、そういう意味では、臨機応変な柔軟な対応ができるんじゃないかなと思います。今の説明と重複しますけれども、事業部長の決裁を取りまして、経理のほうに予定として出していただくという形になります。 今の施設担当課長の説明に続きますけれども、契約の関係です。それ以外のものも民間委託が増えてまいりますが、従来どおり、入札を経理係のほうで実施してまいります。","id":"exchange-022"},{"speaker":"川西副委員長","kind":"質問","question":"そうしますと、具体的に言うと、例えば学校に雨漏りがした場合、もとの組織のままですと、もう少し時間がかかったものが、迅速性が確保されたと理解しておいていいんか尋ねました。","respondent":"片田施設担当課長","answer":"委員おっしゃるとおりです。庶務課の技術担当がすぐに現場に行きまして、施設課のほうで調整をして、起工書を起こすというような体制を考えてあります。","id":"exchange-023"},{"speaker":"川西副委員長","kind":"質問","question":"その場合の、金額の査定というのは、どこかに基準があるんか尋ねました。","respondent":"西島経理課長","answer":"権限の問題ですけれども、学校で言いますと、５０万円以下の工事については、従来から所管の権限で実施していますので、その部分については変更ございません。","id":"exchange-024"},{"speaker":"川西副委員長","kind":"質問","question":"よく出会うんですけれども、そういうときの被服というのは、せっかく与えた被服を着用していらっしゃるんでしょうかね。細かいことを申し上げて悪いんですけれども、その辺について、どういう指示系統というか、組織がどうなっているのか説明を求めました。","respondent":"桑村人事課長","answer":"ただ、実際上、例えばトレーナー等については、同じようなものでご自分でお買いになったものを着ていらっしゃることもあろうかと思います。ほぼ同じ形だろうと思いますけれども、貸与被服を必ず着ているかということについては、例外があるかと思われます。","id":"exchange-025"},{"speaker":"川西副委員長","kind":"意見","question":"今、比較的短時間勤務、それから再雇用職員が現場に入っていますよね。そういう方たちには、同じように被服貸与があるのかどうかということの意見を述べました。","respondent":"桑村人事課長","answer":"今は、短時間の非常勤職員については、同じように考えてあります。","id":"exchange-026"}]},{"id":"topic-02","title":"の聴取をいたします。 お手元に中央防波堤埋立地の帰属についての資料がございますが、これ","agenda":"の聴取をいたします。 お手元に中央防波堤埋立地の帰属についての資料がございますが、これ","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"(3)の、各区の主張に対する疑義についてというところがありますよね。品川区はどういうふうな主張をされているんか尋ねました。","respondent":"小野（孝）政策担当課長","answer":"帰属権が品川区にかかってくるということで、ここについては、品川区に帰属すべきだということを主張しております。","id":"exchange-027"},{"speaker":"桜井委員","kind":"質問","question":"帰属の問題は、そういうふうに地崎の関係で、うちにもあると主張されている。そうすると、灰溶融施設の関係は、どういうふうに主張されているんか尋ねました。","respondent":"小野（孝）政策担当課長","answer":"私ども品川区としては、灰溶融施設の都市計画の決定については、やはり帰属とは別に切り離して考えるべきであって、帰属の決定が決まらなければ都市計画ができないということではなくて、都市計画のほうを進めてほしいと主張しています。","id":"exchange-028"},{"speaker":"土井委員","kind":"質問","question":"江東区長のご見解の4)のところの「それが不可能な場合」というのは、法定の手続を踏んで帰属問題に決着をつけるというのが何か交錯しているんです。それが速やかに決まる法定というのはどういう形なのかわかりませんけれども、どうなのかということを、まず伺わなければなりません。","respondent":"小野（孝）政策担当課長","answer":"５区の合意ができないという形になりますと、地方自治法の９条に、「知事は関係特別区の調停に付することができる」という形になります。調停によって決定したのが、１３号地の埋立地の件です。","id":"exchange-029"},{"speaker":"土井委員","kind":"質問","question":"そういうことだとすると、１３号地の埋立地のときを事例にとるしかしようがないわけですが、そのときはどうだったんでしょうか。１３号地の事例では、いかがだったんでしょうかと聞いたほうがいいんか尋ねました。","respondent":"小野（孝）政策担当課長","answer":"実際に帰属が決まりましたのが、昭和５７年１０月に調停が成立しまして、１１月に境界が確定をしたという流れになっております。ただ、もちろん、調停の申請まで時間がかかるということです。","id":"exchange-030"},{"speaker":"土井委員","kind":"意見","question":"そういう流れでは、いろいろと問題が発生をするということならば、どうするかということになるわけです。少なくとも、申請に至る方向性みたいなものに向かうのか、あくまで領土戦争をやり続けるのかということなんですけれどもとの意見を述べました。","respondent":"小野（孝）政策担当課長","answer":"現在の検討協議会、法的手続、いわゆる調停の手続ということも視野に入れて検討すべきであるというような報告をしております。助役会のほうからの下命で、いわゆる部長が構成しております検討部会のほうが、７月をめどに検討する予定になっておりますので。","id":"exchange-031"},{"speaker":"土井委員","kind":"質問","question":"それには一定の期間がこれまた必要だろうと思うんですけれども、大体、どんなものなんでしょうか。要するに、いろいろやることの手を打つのが、最後の区切りのところにどう間に合うかという逆算方式も含めて考える上での参考にしたい。","respondent":"小野（孝）政策担当課長","answer":"６月中旬までに、平成１４年度中の着工、国の補助金の対象になるだけの事業というものが確保できるという見込みですけれども。東京２３区清掃一部事務組合のほうでも、すぐにそういうものを出して、とにかく直近でやってもらいたいという状況になっています。","id":"exchange-032"},{"speaker":"土井委員","kind":"質問","question":"そちらの政策的なものも含めての影響が大きいわけですから、ここの課のことだろうと思うわけですから、その辺の大ざっぱなところを聞きたいんです。","respondent":"中尾根企画部長","answer":"なぜかというと、５区で話し合いで決まるということはありませんから、各区で主張はしていますから。東京２３区清掃一部事務組合のほうで、それはそれで動き始めているというのが現状だということで、ちょっと伏せられている部分をご説明いたしました。","id":"exchange-033"},{"speaker":"土井委員","kind":"質問","question":"そういうことで、いろいろな準備段階が進められている中で、都市計画申請をしたら、結論が出るまでどれぐらいかかりそうなんか尋ねました。","respondent":"中尾根企画部長","answer":"今のように、ただ、話し合いをしているのでは、ほんとうに手続の次のステップへいつ行くのかという問題を、いろいろ考えられているのではないか。実際にかかる調停期間は相当長期にわたると、私どもは思ってあります。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問・要望","question":"論理的にどうなっているのかよくわからない部分があるわけですから、後でいいですから、教えてほしいと求めました。この辺のところは、今の段階で、理事者の側はどういうふうにお考えか。","respondent":"中尾根企画部長","answer":"必ずしも江東区が考えているように動いているのかというと、複雑に動いてしまって、そう単純にものごとはなかなか解決しない方法にいっている。どのように収めるかということについては、今後、大きな力を発揮していかなきゃいけないんじゃないかと把握しています。","id":"exchange-035"},{"speaker":"林（宏）委員","kind":"確認","question":"確認を一番先にさせてもらいますけれども、(1)の５月２０日に行われた検討部会で、東京都の環境局から説明を受けたということは、どういう意味を持っているんか尋ねました。","respondent":"小野（孝）政策担当課長","answer":"中央防波内側埋立地という１８８haの部分と、外側埋立地その１とその２がありますけれども、関係の部長の協議会の中で問題になっております。年度としては、平成１７年度３月というのが期限になっているけれども、実際、少し……。","id":"exchange-036"},{"speaker":"林（宏）委員","kind":"質問","question":"内側はどうなんですか。説明はされてない。","respondent":"小野（孝）政策担当課長","answer":"内側は既に終了しておりますけれども、処分場として使っておりましたので、そういう意味では、当時の清掃局が関係をしていたです。こちらでいくと、内側埋立地の半分、右上のほうが廃棄物、左下半分が建築残土で埋め立てておりますので、そういう関係になっております。","id":"exchange-037"},{"speaker":"林（宏）委員","kind":"質問","question":"その次の(2)の説明なんですけれども、これについては、この部会は一切、施設建設には関係しません。全部含めて、単純に帰属だけを部会でやっていくだけですよという説明の文書なんですか、これは。","respondent":"中尾根企画部長","answer":"灰溶融施設については、どこの区がこの都市計画決定をやるかという判断は出ています。ただ、灰溶融施設そのものが必要であるのか、大きさがどうであるのかということについては、一切関知をしないという関係にあります。","id":"exchange-038"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、今のは微妙なんですけれども、片方で施設建設は念頭にありながら、帰属をやっていくというのか、施設建設はわかっているんだけれども、この検討部会では、帰属をどこにするのかということの意見集約を持つと考えていいか尋ねました。","respondent":"中尾根企画部長","answer":"一番最初に、江東区は嫌だと、ほかの４区はぜひ江東区でやってくださいと。関係とすれば、今言った経過の中にある関係が、当専門部会の中で検討している事項です。","id":"exchange-039"},{"speaker":"林（宏）委員","kind":"質問","question":"３番目の説明なんですけど、この疑義についてというのは、(3)は、いわゆる帰属問題についての話に限ってのことの説明か尋ねました。","respondent":"中尾根企画部長","answer":"そのとおりです。これについては、灰溶融施設がどうだということではなくて、帰属の手続そのものです。","id":"exchange-040"},{"speaker":"林（宏）委員","kind":"質問","question":"最初に戻るんですけれども、さっき言った、施設建設を江東区がやると決定をしていると言っているんですけれども、どういう形で決定をしているんか尋ねました。","respondent":"中尾根企画部長","answer":"この覚書どおり進めるべきだと、事務レベルでそういう調整がなされて、その部長会の決定を５区の関係区長のところに上げました。これは、関係区長の中での合意で進めている事項ですので、特にその時点での文書はありませんけれども、そういうことです。","id":"exchange-041"},{"speaker":"林（宏）委員","kind":"意見","question":"２番目の1)に、「決定を行うことは暫定的な覚書の範囲を超えている」と言っているから、覚書の中にはないんじゃないか。決定をしていると言いながらも、江東区がやるということはとの意見を述べました。","respondent":"小野（孝）政策担当課長","answer":"昭和４８年１０月２７日に関係区で交わされたものですが、1)といたしまして、暫定的に江東区において処理する」と書かれております。ですから、都市計画決定も特別区の事務ですので、それについては江東区が行う。","id":"exchange-042"},{"speaker":"林（宏）委員","kind":"意見","question":"改めて２３区で、この施設建設をこの埋立地につくることをどうするかというのをやればいい。５区だけの問題に２３区の問題を引きずり込まれちゃうと、僕は思うんですけれども、その辺をはっきり分けていくべきだと思いますよとの意見を述べました。","respondent":"小野（孝）政策担当課長、中尾根企画部長","answer":"権限として、特別区が行うべきものについては、暫定的に江東区がとりあえず行うという形で交わされたものと理解しております。それから、江東区長の見解の送付先ですけれども、これにつきましては、写しという形で… 「４区長が覚書から出発していいということで、結果的には、そういうふうに少しおかしいんではないかということもあります。どこにちゃんと戻して出発するのか、これが大きい議論になってくるのかということで…","id":"exchange-043"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"だからはっきり、もう５区の問題の帰属と２３区の問題の施設建設は分けて、東京２３区清掃一部事務組合がどう判断するのか。そういう問題だということを、企画部長も十分ご承知だと思いますけれども、わきまえてやっていただきたいということをお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"塚本委員","kind":"意見","question":"このことについて２度、３度やられることが大変望ましいことと、私どもも思っておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"藤田委員","kind":"質問","question":"岡山ですか、今回、全国で初めて電子投票をやりますね。将来は、ほとんどそうなってくると思いますね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"桜井委員","kind":"質問","question":"その辺の制度というんですか、その前段が、もしわかれば質問したい。監査事務局長もお残りになっているようですので、積極的に今年度は１２団体ということですので、そのあたりの勉強もしたいなと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"林（宏）委員","kind":"質問","question":"そういう意味で、大きい問題として取り上げていくということですから、何らかの形で、議会が意思表示するのも必要かなという気もしています。ソフト面のことが主となると思うんで、そういう意味では、時期を見て実施をしていただければありがたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"塚本委員","kind":"質問・要望","question":"今の議論の領土問題に隠れているのは、東京２３区清掃一部事務組合の問題ですから、その問題をどこでやるかというのがあると思います。思い出しました、自治体の合併問題について。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"伊藤委員長","kind":"質問・要望","question":"実際には、ここではっきりと約束はできませんということを、ご理解していただきたいと考えています。ほかにテーマはありますか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"桜井委員","kind":"質問","question":"テーマじゃないんですけど、いいですか。どこの委員会の問題なのかわかりませんけれども、あまり詳しく内容が聞かれてないんですけれども、これは議長のほうが詳しいんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"桜井委員","kind":"意見","question":"だから、自民党としては、例えば、議会で決議的なものを考えているのか、どうか。総務委員会で聞くのは、ちょっとおかしいかもしれませんがとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"ぜひ、ご理解をいただきたい」と言うから、僕のほうは、大家さんにきちんと話を通して、理解を得てやることを進めてくださいという話をしてある。僕との話は、そういう段階です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"塚本委員","kind":"意見","question":"どうしましょうかということで、まだ、最終的な決定は見ておりません。そういう状況ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201900?Template=document&Id=1584#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":61208,"voices":169}},{"id":"h14-20020611-13","meetingId":"h14-cm06","date":"2002年6月11日","dateIso":"2002-06-11","committee":"清掃・リサイクル特別委員会","time":"午後１時０５分～午後３時３１分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"横山委員","kind":"質問","question":"建物については１５％以上とか、１５％以上ということですけれども、現時点でどうなのかなと。その残りの部分をこれから調整というか、論議していかなければならない部分だと思うんですけれども、現状としてはどうなのか説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"１５％の焼却余力が確保できるというふうに見込んでおりますが、今の見込みですと、平成１８年度当初において１１６％という見込みですけれども。順次上がっていって…","id":"exchange-001"},{"speaker":"横山委員","kind":"質問・要望","question":"そこら辺のところの内訳は分かるんですか。そういうことを教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"今この検討を行っておる共同処理の廃止に向けては、その間の地域処理という用語を使っておりまして、この地域処理の実現に向けて検討をしておる。それについては工場のない区も織り込んだ形で…","id":"exchange-002"},{"speaker":"横山委員","kind":"意見","question":"大体分かりました。職員の数という部分では、現在の計画されている中で１５％とか１６％という、そういったものが満たされるということで今は考えていていいんですねとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"上山委員","kind":"質問・要望","question":"改めて基礎的なお尋ねをして申し訳ないんですが、１で、どういう意味合いで１５％が出たんですか。もう一度おさらいで申し訳ないんですが、教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"この１５％はなぜなのかというのが、国の補助採択基準の中で、該当地域において一定の焼却余力がないと安定的処理ができない。実は平成１７年度末日をもって共同処理の廃止ということについては、今申し上げたような、ある種の注釈がついて出てきたのが１５％という解釈です。","id":"exchange-004"},{"speaker":"上山委員","kind":"質問","question":"一定の枠があって１５％よりも減ってくるだろうということもあったかと思うんですが、そこら辺の係わりというのはあったんでしょうか。もし何か考え方があれば教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"平成２０年度ぐらいになってくると、今回は平成１８年度の予測が入っているわけですけれども、若干増える。それから１００％引いたものが余力という形になりますから、それを毎年出していくです。","id":"exchange-005"},{"speaker":"上山委員","kind":"質問","question":"平成１７年度以降のことについては、荒川区は平成１８年度以降の建設になるけれども、実質はどんなふうな形で想定されるんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"先ほど地域処理ということでご説明申し上げたんですが、これがどのようなブロック化されていくかということで検討をしておりますが。２３区一体でない処理で運営しながら、その段階で設置したブロックをもう一回見直すとか、これは再検討する余地はあろうかと思いますが。","id":"exchange-006"},{"speaker":"石田副委員長","kind":"質問","question":"全然違うことで１点だけお聞きしたいんですが、２カ所あるところは別として、何か論議がなかったのかなと思ったんです。ほかのところはみんな自区内処理の考え方で区の名前がついているのではないのかなと思いますが、そこら辺のところはどうお考えか尋ねました。","respondent":"松本環境清掃事業部長","answer":"実は中央工場が建ち上がるときに、中央区は中央工場はいやがったんです。中央区は２３区の中央工場なのかと、あと２工場あるところは、その部分は分かるようにしてきた次第です。","id":"exchange-007"},{"speaker":"石田副委員長","kind":"意見","question":"品川区は、そういう考えというのはどうなのかなと思ったんですとの意見を述べました。","respondent":"松本環境清掃事業部長","answer":"今工場名としては「大井工場」になってあります。変えるとなると、やはりそれなりのご意見を伺わなければならないと考えていますので、よろしくお願いします。","id":"exchange-008"},{"speaker":"川西委員","kind":"提案","question":"直営職員かどうかわからないぐらいの感じですが、これを伺っておきたいと思います。その辺について、これは提案ですけれども、いかがか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"例年よりも倍ぐらいかかってしまったという時期が、４月には特にございまして、今は利用率も上がっております。それから、びん類の口金の部分ですけれども、ご提案ということで、いろいろと研究します。","id":"exchange-009"},{"speaker":"川西委員","kind":"質問","question":"２.５とか４.８とか書いてあって、値段が違うわけですから、店舗に手数料というのはいくようになっているんですか。その辺で、現金と券をいったりきたり、毎月集約するときに、トラブルの原因になっていないのかどうか、伺っておきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"事業系の有料ごみ処理券は４種類ありまして、大体１０枚単位になっておりますが、毎年何件かは扱いはやめたいという声もあるのは事実です。","id":"exchange-010"},{"speaker":"横山委員","kind":"質問・要望","question":"確認というか、教えてほしいんですけれども、隣接区からの受け入れもやっていますよね。これは各区から持ち込まれるわけですから、品川区としてもうかっているものなのか、そこら辺のところを数字的にも教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"その他２０％弱が渋谷区、移管時に分担金方式の検討もしたんですけれども、これを全額運営分を品川区が受けるという形になりました。過去２年間においては十分財政措置されているという形が確認されておりますので、分担金は徴収しておりません。","id":"exchange-011"},{"speaker":"横山委員","kind":"質問","question":"それは永久的というか、東品川清掃作業所で地域の部分は今後も、平成１７年度に係わらず続けていかなければいけない。品川区がその場を提供していかなければいけない、こういう考え方ですかね。","respondent":"中山清掃リサイクル課長","answer":"したがって、不燃ごみという概念がある限り、不燃ごみ処理施設に向けて搬入中継作業というのは今後も継続していく形になってまいります。先ほどの財政調整との関係は、説明が分かりにくかったようで、恐縮ですけれども、要するに…","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"３５ページの、今後地域をもっと広げていくという方向性についてどういうふうに考えていらっしゃるのかお伺いいたします。同じ５番目の、ほかのところは外れていますが、その辺はどういうことなのかを伺いたいと思います。","respondent":"中山清掃リサイクル課長","answer":"次の段階で詳しくご説明したいと思いますけれども、当面、当面のカラス対策としては併用していくということがあろうかなというふうに思っております。現行の中でさらに６世帯ほどやってほしいという形になると、世帯数としてはほぼ似たような数ですけれども…","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"効果も含めて伺いたいし、非常に困っていらっしゃる区民が多いわけですから、どのように対応したらいいのかということを改めて伺いたいと思います。ですから、さらに最終的にどうこうというのであれば、改めてその辺を伺います。","respondent":"山口品川清掃事務所長","answer":"そういう意味では行政の継続性から考えますと、平たく言えば、そんなに大幅な手間をかけずに済むだろうということも１点考えられます。それから、こういう考え方がもう１点ございましたので、地域性を考えながら拡大していく中では検討の枠の中に入るというふうに考えてあります。","id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"そういう目で見ていただいて、効果のほどを、そういう角度からも捉えていただければと考えています。そのことをお願いして、終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"嶋委員","kind":"質問","question":"４８ページのペットボトルの店頭回収のことでお聞きしたいんですが、スーパーマーケットの数というのは掌握されていらっしゃるんでしょうか。現在１８６店舗ということですが、うちでやろうとかという数が申し込みされてくるのかどうかわからないんですが、お聞きしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"すべての方にご認識いただいて、不燃ごみの中に、身近に出しやすいということでペットボトルが入ってしまうという実態があります。区でも認識していますので、区としてもいろいろな手段がありますので、折を見て丁寧にやっていきたいと考えています。","id":"exchange-016"},{"speaker":"嶋委員","kind":"質問","question":"これから助成していく、私が見てきたのは壁面緑化ですけれども、そういう中でペットボトルの有効利用ということを区として考えていらっしゃるか。業者のほうからそういう声があるのかどうか、お聞きをしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"他区において、ペットボトルを使って、子どものアイデアでやってみようというところから始まったというのが報道であったのは認識しています。ペットボトルの活用、これに緑化を加えるというのも非常に興味深いことだと思うので、今後考えさせていただきたいと思います。","id":"exchange-017"}]},{"id":"topic-02","title":"続きまして、３番の報告事項、(1)各戸収集事業","agenda":"続きまして、３番の報告事項、(1)各戸収集事業","exchanges":[{"speaker":"川西委員","kind":"意見","question":"収集時間にかかる１.７倍、１.９倍の手間暇の問題を、どうやって解決していくのかなと今から心配でならないです。確かにモデル実施の段階で各地域を一回りしてからのことになりますから、いいお答えは出ないと思っていますが、そこのところをお願いいたしますとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"１点目の袋の配布ですけれども、３カ月で終了する関係上、この期間モデル事業用ですよという表示をした特別の袋をお配りして実施をいたしました。つまり１日の作業の中で、１回の作業が延びても、当然今後の拡大には対応できないというふうに認識しております。","id":"exchange-018"},{"speaker":"川西委員","kind":"質問・要望","question":"ごみの有料化につながらないような対策をぜひ要望しておきます。可燃、不燃の関係なく、そうなのかどうか、ちょっと伺っておきたいんです。","respondent":"山口品川清掃事務所長","answer":"１２月に実施いたします今回のごみ収集につきましては、現在出されている集積所の時間帯につきましては変えない予定で実施をいたすつもりでおります。先ほど申し上げましたように、大体その辺の時間以後で収集にお伺いできるというふうに予定を組んで…","id":"exchange-019"},{"speaker":"川西委員","kind":"質問","question":"一般収集についても、地区ごとに、集積所ごとに時間を決めていますよね。可燃と不燃は両方適用なのかどうか、１時間半も来なかったら電話をすべきなのかどうか、この辺も伺っておきたいと思います。","respondent":"山口品川清掃事務所長","answer":"その集積所の時間帯は８時、１０時、１２時と３段階になっているかと思います。その地域の方については、今出されている時間帯で可燃も不燃も、各ご家庭の前に出していただければ、その時間に収集に伺いますと、こういうことです。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ほかの地域の回収の時間帯が変わるというか、そういう影響が出てくるのかどうか、その点を１点伺いたいと思います。各戸の説明で済ませていますというお話が多いんですけれども、ぜひ説明会を開いていただきたいなと思うんですけれども、いかがか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"最小限にとどまる努力を清掃事務所のほうもする予定ではありますが、今後影響が出てくる地域がないとは言えないと思います。動かせないという地域が出れば、あえて説明会全体をやるというよりは、どこにお出しいただくかを１軒ずつ説明するというのが基本になるかと思います。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"集める場所で、場所によっては、そのほうがいい部分もありますよね。その辺は細かく、各戸を訪ねてやっていくということか尋ねました。","respondent":"山口品川清掃事務所長","answer":"基本的には前回のモデル実施と同じ形態をとらせていただきますが、こだわる方もありますので、同じ方策をとらざるを得ないかなと考えています。説明会についてはやる予定はございませんという話はどういうことかと言いますと、各戸にご説明する際に、そちらへ取りに伺いますと。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どっちがどっちというのでなくて、地域全体でごみ問題を考えていくという啓発の部分も含めて、また一つ一つ取り組んでいってほしいと求めました。これは意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"辻委員","kind":"質問","question":"それのときに、今秋葉原などに行くと、ヒュッと持って引いて行くのがあるじゃないですか。でも、これは先行きずっと続いていく事業であり、品川区の事業としてやる以上は、どんな考えで広めていく、あるいは取り組もうとしているのか。","respondent":"中山清掃リサイクル課長","answer":"一定の見込みはあるんですけれども、最終的なものはまだ実施しながら確認をしていかなければいけないです。モデル実施をやったときにアンケートをとらせていただいたんですけれども、ある種の発生抑制までお考えになった方もいらっしゃったのか。","id":"exchange-024"},{"speaker":"辻委員","kind":"質問","question":"そのうしろが限られてしまうというのは、中でどういう時間の動きがあるのか。モデル事業のときも、待っている時間というのはどういう形になっているんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"これが１日で吸収できない場合は、車なり、体制を増強しなければいけない。１台の車が行っている間に、もう１台の車を一つの清掃班につけて、１日の中でおさまるようにしていく工夫も併せてやっております。","id":"exchange-025"},{"speaker":"辻委員","kind":"質問・要望","question":"いっときの場所がなければ、外国なんかだと、大きい真四角のがあるじゃないですか。人員増やせというほうに安易にはね返ってこないように、ぜひ検討してほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"自分たちが効率的にやれる工夫というのは考えていっていると思いますけれども、前半言われたのは、すでにやっているようなところがあります。用具、あるいは場合によっては住民の方との連携という意味で…","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"ですから、今の議論をずっと伺っていて、ちょっとわからなくなってしまったんですね。だから、伺いたいと思って、質問をしました。","respondent":"中山清掃リサイクル課長","answer":"比較的順次毎年着々と実施可能な部分だということで、これは実施可能である、あるいはそれに見合った効果があるということでやっていく。ただし、繰り返し申し上げているように、できるだけ新たな増がないような工夫は最大限やった上でやっていくというふうに考えております。","id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"どうしても全域拡大するには、これは共通して、この委員会でもそういう認識を持たざるを得ないんじゃないかというふうに思うわけです。今日は事務事業概要の部分ですから、これから継続して質問もさせていただきたいと考えていますので、以上で結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"南委員","kind":"提案","question":"今、委員長の提案したのをちょっと聞き漏らしたので、正確に確認したいと思うんですけれども。清掃・リサイクル特別委員会ですから、東村山で市営団地でやっておりまして、そういうところもちょっと検討をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=5666#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":46575,"voices":103}},{"id":"h14-20020611-16","meetingId":"h14-cm06","date":"2002年6月11日","dateIso":"2002-06-11","committee":"街づくり特別委員会","time":"午後１時０８分～午後３時１２分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"それとして従わなければならないというものなのか、あくまでも品川区独自に判断する余地があるのか、その辺はいかがなものなんか尋ねました。","respondent":"伊佐都市計画課長","answer":"区の市街地整備基本方針との整合性を十分図るというようなかかわり方がされてございまして、区の事業の方針との整合というのは非常に保たれる。やはり余りにも都の方針、そういった区の計画といいますか…","id":"exchange-001"},{"speaker":"沢田委員","kind":"確認","question":"この前の都の基本方針によると、全体としてさらに規制緩和の方向に動くようなことが非常に不安なんですけれども、実際的にはどうなんでしょうか。その辺はどうかということと、それから、実際にそれがその地域ごとにどこまで消化して利用されているかというようなデータはあるんか尋ねました。","respondent":"伊佐都市計画課長","answer":"次回詳しくご説明させていただきたいと思いますが、しかも政策目的に合致する点については柔軟に対応していくというような姿勢だと思います。あるエリアを例えば特定していただいた中で、どのぐらいが使われているかといったところは大体あるかなと思います。","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問・要望","question":"今後どこがどういうふうに変更になるかわからないんですけれども、そういう、この前は５カ所か何かでしたんですよね。激しいときに、すごく丁寧にやっぱりそこはやる必要があるように思うんですけれども、今においての考え方をお聞かせいただきたいと思うんです。","respondent":"伊佐都市計画課長","answer":"おおむね１年程度期間をいただけるものと考えていますので、住民説明会を行って、原案についてまとめていきたい。それから住民説明会５回、前回の参加状況等を勘案しますと、今回も同程度のご説明で私どもはご配付させていただきたいと今の段階では考えてあります。","id":"exchange-003"},{"speaker":"桜井委員","kind":"質問・要望","question":"それで、逆にもっと環境を保全してほしいという、今ちょっと拝見したらば、第１種のところというのはどんどん非常に少なくなっていっていますよね。だから、今の段階から積極的にそういう角度もぜひ考えていただきたいなというふうに思うんですけれども、いかがか尋ねました。","respondent":"伊佐都市計画課長","answer":"これを例えば説明会で用途地域全体の見直しになったときに、これはとてもその用途地域見直しの中で処理できる問題ではないというふうに私は思います。都市計画の制限をもとから入れば、動きが出てくれば…","id":"exchange-004"},{"speaker":"須藤副委員長","kind":"質問","question":"４１ページの用途指定のところで、何が何％ぐらいがこの品川区のまちづくりの総体像としてはいいんじゃないかというような思いは考えられるんですか。それとも地域からいろいろ声があったら、もう適宜やっちゃうのか、その辺はどうなんか尋ねました。","respondent":"伊佐都市計画課長","answer":"市街地整備基本方針に、にぎわいゾーンとか、そういったゾーニングを行ってあります。やはり市街地整備基本方針を定めてありますので、その方向の中でまちづくりを考えたけれども、ちょっと数字としては定めてございません。","id":"exchange-005"},{"speaker":"須藤副委員長","kind":"意見","question":"これは長い、小山七丁目のところの第１種で出るんだけれども、ぽこんと一つだけ商業のラインに入り込んでいるわけですねとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"高星副委員長","kind":"質問・要望","question":"地域の人たちが自分たちの町並みを残そうということで、その限定された地域の人たちがそれぞれ確認書を取り交わして地域協定というのをつくる。その辺どういうふうに考えていっていいのかということが一つと、今地区協定みたいなのがあるのかないのか、ちょっとお聞きしたい。","respondent":"田平建築課長、伊佐都市計画課長","answer":"縛りをかける範疇にも限度があるということで、なかなか私どもの公的に認知するようなところまでいかないというのが実態でもあるわけです。現実に、事実関係としては、そういった地元での動きというのはあります。 それはその都市計画上の制限をしていただきますので、そういう意味では厳しいといいますか、そういった運用がなされるです。それなりの地域の方への影響も大きくありますので、なかなかそれの合意を得ながら進めていくというのは…","id":"exchange-007"},{"speaker":"高星副委員長","kind":"質問・要望","question":"地域協定では何の縛りもないわけだから、地区計画に数えろと言っているのではなくて、そういうところをいかにまちづくりとして区が関与していくのか。地区計画がこうだから、地域協定はこうだとかということでなくて、その辺の整合性だとかをちょっとお聞かせいただきたいなと思います。","respondent":"田平建築課長","answer":"今区内に幾つか第１種低層地域が点在していますけれども、そういうところで、地元説明会などを何回か繰り返して打って出ていったことがあります。そういった地元からの声が上がってくるかどうかというところが問題ですけれども、以前に働きかけを行った際には…","id":"exchange-008"},{"speaker":"高星副委員長","kind":"質問・要望","question":"地元の人たちが中心に自然発生的に出てくるやつと、区のほうが逆に目的意識を持ってお願いする、いわゆるまちづくりというのと両方あるんですよね。だから、これからも、区もやっぱりお互いに相談をしながらまちづくりの一番いい方法をつくり上げていっていただきたいという要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"北野委員","kind":"質問","question":"それともまたそこの中で整備しながら、そういうところをやはり検討されながら、そういうところはどういうふうに考えていくのですか。わかりますか。","respondent":"伊佐都市計画課長","answer":"しかも東京都の指定方針、そういった形で、今のいろんなさまざまな状況を見ながら対応を検討してまいります。東京都の指定の方針、余り用途地域の利用は、要望があればさっと変えますというお約束もできないという状況です。","id":"exchange-010"},{"speaker":"北野委員","kind":"質問・要望","question":"住民の要望には利害関係というのがいろいろ入ってくるので、いろいろな要望は確かにあると思うんですね。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"桜井委員","kind":"質問","question":"今の１６３号線の関係でお聞きしたいんですけど、お部屋を借りている方の場合に、多分一つは住居の問題がまず心配がありますよね。そういう方々に対してどのような説明をされているんか尋ねました。","respondent":"中島街路事業担当課長","answer":"あるいは要望に沿うような形がどういうものなのかということを１件１件ご相談させていただきながら、契約に持っていくです。あるいはその手数料についての割引をして、宅建支部の協力を得て、この事業を円滑に進めていきたいというふうに考えているところです。","id":"exchange-012"},{"speaker":"桜井委員","kind":"質問・要望","question":"保証人がなければ借りられないわけですから、どうもパンフレットを読む限りにおいては、そういう姿勢が見えてこないんですよね。例えば具体的に区営住宅なり都営住宅なり、そういう区が責任を負ってできる限りのことはすべきだと思うんですけれども、いかがか尋ねました。","respondent":"中島街路事業担当課長","answer":"現在、あるいは昨年からの説明会等で地元の方と直接いろんなお話をしていますけれども、入りたいというような希望は実際にはそう出てございません。現在、当面公営住宅につきましては、３戸程度確保すれば対応可能というふうに考えてあります。","id":"exchange-013"},{"speaker":"桜井委員","kind":"質問・要望","question":"要望しておきます。従来の道路事業にかかわるそういう施策だけでない、いろんな多面的な生活再建ということでやっていただきたいというふうに強く要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"沢田委員","kind":"質問","question":"幾らで売るかという値段というんですか、実際には幅というのは非常に微妙ですよね。そこらは実際にはどうなのか、ちょっと教えてもらえるとありがたいんですが。","respondent":"中島街路事業担当課長","answer":"１件１件価格をもう土地につきまして決めていきますので、そういった意味では、権利者の方と交渉して価格が変わってくるということはございません。財産価格審議会で決まった価格によってお譲りいただくという形ですので、ご理解をよろしくお願いいたします。","id":"exchange-015"},{"speaker":"沢田委員","kind":"質問","question":"何かデータみたいなのがあれば教えてほしいということと、それから相手があっての交渉で、少しでも有利に売りたいというのがこれは人の常ですよね。本人が決めることなんじゃないでしょうかと、不動産屋がおさまっていて、ちょっと教えてほしいんです。","respondent":"中島街路事業担当課長","answer":"そういった部分では、そういった意味では、実際に一本橋通りの方々に理解は十分されてきているというふうに認識しています。そこにつきましては、先ほどご説明いたしましたけれども、手数料につきましても割引がありますというようなことでご説明をさせていただいてあります。","id":"exchange-016"},{"speaker":"中島委員","kind":"質問","question":"この中に借間人の方ですか、７３名、既にもう移転をされている方はどのぐらいいらっしゃるのか尋ねました。","respondent":"中島街路事業担当課長","answer":"この１週間ほど、二、三週間前から個別交渉に入っている段階でございまして、そういう点では契約した方はまだ１件もございません。","id":"exchange-017"},{"speaker":"中島委員","kind":"質問","question":"ちょっと何か早まって、大家さんのほうが、ここは拡幅になるんだよということで出してしまったという例もあるみたいなんですが、そのことはご存じか尋ねました。","respondent":"中島街路事業担当課長","answer":"１件、いわゆる区として交渉に行く前に、任意で契約して移った方がいらっしゃるという話は聞いてあります。ただ、生活福祉課のほうとちょっと今連絡をとり合って、対応可能かどうか検討しています。","id":"exchange-018"},{"speaker":"中島委員","kind":"質問・要望","question":"この７３世帯ですか、この中にはいろんな状況の方がいらっしゃると思うんですね。出てしまった方でもやはり区のほうとしては丁寧に対応していただきたいなということを一つ要望しておきたいと思うんですね。","respondent":"中島街路事業担当課長","answer":"この前のブロックの説明会等でもそういう話が出てあります。ただ、なるべく工事する際にはご迷惑がかからないように、時間帯等もご相談をさせていただきながら工事をしていきたいというふうな考えです。","id":"exchange-019"},{"speaker":"中島委員","kind":"質問・要望","question":"全体に一本橋商店街をきれいにしていくまでの期間が長いもんですから、それもやっぱりきめ細かに対応を今後していただきたいというふうに、これは要望にとどめておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"三上委員","kind":"質問","question":"全般的な道路事業のことで伺っていきたいんですけれども、東京都の買収も同じことかなと思うんですよね。そんなようなことでの買収する順位というのは、ある程度戦略的にねらいとかというものはあるのかどうかというのをちょっと伺っておきたいんですが。","respondent":"中島街路事業担当課長","answer":"私ども説明会等では、順序とすれば２６号線側から順次交渉に入らしますという説明をしています。そういった意味では一応流れはありますけれども、希望される方につきましては対応していけるというふうに考えてあります。","id":"exchange-021"},{"speaker":"三上委員","kind":"質問・要望","question":"その話を伺っていて安心した部分というのはあります。そこらあたり、ぜひお願いしておきたい、要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"沢田委員","kind":"質問・要望","question":"今日の新聞で、これは今後詳しく説明するというお話だったんですが、ちょっとわからないのでいいですか。それにしてもこの都市再生というのはどういう目的でやっているかということにかかってくると思いますので、それを教えていただきたい。","respondent":"南雲都市開発課長","answer":"国際的に日本が活力を維持することができないだろうということで、大都市の中心部の活力を高めるということが目的になっております。特に重点的に開発が行われるといいますか、行われ得るポテンシャルのある地域を指定し…","id":"exchange-023"},{"speaker":"沢田委員","kind":"確認","question":"確認しておきたいんですが、財政的には全くないということでいいんですか。産業施策の面で見て、優先順位に違いがあるんじゃないのかなというふうに思えてならないんですけれども、その辺の考えをちょっと。","respondent":"南雲都市開発課長","answer":"この資金ですが、債務保証というような金融面での支援をするということになっておりまして、この民間都市開発推進機構には国からも貸付が行われる。最終的には回り回って、衰退を避けるということで…","id":"exchange-024"},{"speaker":"沢田委員","kind":"質問","question":"これとの兼ね合いはどうなんですか。そこだけちょっと教えてほしいんです。","respondent":"南雲都市開発課長","answer":"その整備方針に沿って、各開発事業、例えばこれまでですと二丁目第１地区のオーバルコートというようなぐらいの単位で都市計画の提案をできる。これも地域ごとに定めています整備方針に合致したもの、これまでよりもスムーズな都市計画の適用で…","id":"exchange-025"},{"speaker":"沢田委員","kind":"質問","question":"その地区計画なり再開発の計画は、それは区のほうが出すという格好になっていますけれども、それを民間企業が出せるということなんですか。ちょっとそこらを現在とどう違うのか、教えてもらいたいと思います。","respondent":"南雲都市開発課長","answer":"２年近くかかっていたんですけれども、それを６カ月に短縮するということで、都市計画の手続期間を大幅に短縮するということが一番大きな変化です。計画全体がすぐれているかいないかというような観点からのチェックで、細かい規制については、これは緩和していくです。","id":"exchange-026"},{"speaker":"桜井委員","kind":"質問・要望","question":"結構そこの大崎東口第３地区で、今ここで２５名というふうに権利者が出ていますけれども、そういうのをちょっと教えていただきたいんですね。こういうのを計画していく上でも、何か私たちの歩いてきたところでは、だれが一体こういう計画というのをしたんか尋ねました。","respondent":"南雲都市開発課長","answer":"工場がどんどん移転して、その場所がその跡地が駐車場になったり住宅展示場になったりということで、この地区が空洞化してきた。副都心にも指定されているということで、こういう副都心にふさわしい地区に高度利用を図っていこうということで、これまで協議が進められてきたです。","id":"exchange-027"},{"speaker":"桜井委員","kind":"質問","question":"だって、権利の方は今言ったように、これは質問状とか書いたというんですけれども、権利関係の実態と、こういう家ってどうだったんですか。ですから、２５人の権利がどういうふうな方々がやっているのか、具体的に言ったらどこがやっているんか尋ねました。","respondent":"南雲都市開発課長","answer":"この地区では、現在計画につきましては、この地区の事業の推進の体制として現在大林組と日本舗道が参加組合員予定者ということになっております。この地区の都市計画などにつきましては…","id":"exchange-028"},{"speaker":"桜井委員","kind":"質問・要望","question":"それで、実際に中止になったところもあるし、ですから、どうもこの大崎の東口第３地区の説明ではちょっとよくわからないし、納得できないですよね。要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/690912?Template=document&Id=6234#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":41527,"voices":103}}]);
